HZ.gpoints=[{"id":"shi","level":1,"title":"是: A is B","pattern":"A + 是 + B","why":"是 links two nouns: A is B. It never changes, so there is no am, are, is, was or were to choose between.","mark":["是"],"mistake":["我是很高。","我很高。","是 joins nouns. Don't put it in front of a describing word like 高 (see 很)."],"ex":[["我|是|学生|。","wǒ|shì|xué sheng|","I am a student."],["他|是|我|的|老师|。","tā|shì|wǒ|de|lǎo shī|","He is my teacher."],["这|是|我|的|书|。","zhè|shì|wǒ|de|shū|","This is my book."]],"gap":[{"en":"I am Chinese.","before":"我","after":"中国人。","a":"是","wrong":["很","在","吗"],"pins":{"是":"shì","很":"hěn","在":"zài","吗":"ma"},"full":["我|是|中国|人|。","wǒ|shì|Zhōng guó|rén|","I am Chinese."]},{"en":"She is a doctor.","before":"她","after":"医生。","a":"是","wrong":["有","都","了"],"pins":{"是":"shì","有":"yǒu","都":"dōu","了":"le"},"full":["她|是|医生|。","tā|shì|yī shēng|","She is a doctor."]},{"en":"They aren't students.","before":"他们不","after":"学生。","a":"是","wrong":["没","很","在"],"pins":{"是":"shì","没":"méi","很":"hěn","在":"zài"},"full":["他们|不|是|学生|。","tā men|bù|shì|xué sheng|","They aren't students."]}],"order":[{"en":"He is my friend.","a":"他|是|我|的|朋友|。","alt":[],"full":["他|是|我|的|朋友|。","tā|shì|wǒ|de|péng you|","He is my friend."]},{"en":"That is my mum.","a":"那|是|我|妈妈|。","alt":[],"full":["那|是|我|妈妈|。","nà|shì|wǒ|mā ma|","That is my mum."]},{"en":"I am not a teacher.","a":"我|不|是|老师|。","alt":[],"full":["我|不|是|老师|。","wǒ|bù|shì|lǎo shī|","I am not a teacher."]},{"en":"Are you a student?","a":"你|是|学生|吗|？","alt":[],"full":["你|是|学生|吗|？","nǐ|shì|xué sheng|ma|","Are you a student?"]},{"en":"My dad is a doctor.","a":"我|爸爸|是|医生|。","alt":[],"full":["我|爸爸|是|医生|。","wǒ|bà ba|shì|yī shēng|","My dad is a doctor."]}],"spot":[{"en":"I am a student.","right":"我是学生。","wrong":"我学生是。","full":["我|是|学生|。","wǒ|shì|xué sheng|","I am a student."]},{"en":"I am tall.","right":"我很高。","wrong":"我是很高。","full":["我|很|高|。","wǒ|hěn|gāo|","I am tall."]}]},{"id":"bu-mei","level":1,"title":"不 and 没: saying no","pattern":"不 + verb (isn't, won't, doesn't) · 没 + verb (didn't, hasn't)","why":"不 says something isn't so, or that someone doesn't or won't do it. 没 says something didn't happen. 有 always takes 没.","mark":["不","没","没有"],"mistake":["我不有钱。","我没有钱。","有 is the one verb that never takes 不."],"ex":[["我|不|喝|咖啡|。","wǒ|bù|hē|kā fēi|","I don't drink coffee."],["他|昨天|没|来|。","tā|zuó tiān|méi|lái|","He didn't come yesterday."],["我|没有|钱|。","wǒ|méi yǒu|qián|","I don't have any money."]],"gap":[{"en":"I don't have time.","before":"我","after":"有时间。","a":"没","wrong":["不","很","吗"],"pins":{"没":"méi","不":"bù","很":"hěn","吗":"ma"},"full":["我|没有|时间|。","wǒ|méi yǒu|shí jiān|","I don't have time."]},{"en":"She isn't going to school tomorrow.","before":"她明天","after":"去学校。","a":"不","wrong":["没","很","吗"],"pins":{"不":"bù","没":"méi","很":"hěn","吗":"ma"},"full":["她|明天|不|去|学校|。","tā|míng tiān|bù|qù|xué xiào|","She isn't going to school tomorrow."]},{"en":"He didn't come yesterday.","before":"昨天他","after":"来。","a":"没","wrong":["不","也","吗"],"pins":{"没":"méi","不":"bù","也":"yě","吗":"ma"},"full":["昨天|他|没|来|。","zuó tiān|tā|méi|lái|","He didn't come yesterday."]},{"en":"I don't like eating fish.","before":"我","after":"喜欢吃鱼。","a":"不","wrong":["没","是","了"],"pins":{"不":"bù","没":"méi","是":"shì","了":"le"},"full":["我|不|喜欢|吃|鱼|。","wǒ|bù|xǐ huan|chī|yú|","I don't like eating fish."]}],"order":[{"en":"I don't drink tea.","a":"我|不|喝|茶|。","alt":[],"full":["我|不|喝|茶|。","wǒ|bù|hē|chá|","I don't drink tea."]},{"en":"He didn't go yesterday.","a":"他|昨天|没|去|。","alt":["昨天|他|没|去|。"],"full":["他|昨天|没|去|。","tā|zuó tiān|méi|qù|","He didn't go yesterday."]},{"en":"We don't have time today.","a":"今天|我们|没有|时间|。","alt":["我们|今天|没有|时间|。"],"full":["今天|我们|没有|时间|。","jīn tiān|wǒ men|méi yǒu|shí jiān|","We don't have time today."]},{"en":"My mum doesn't eat meat.","a":"我|妈妈|不|吃|肉|。","alt":[],"full":["我|妈妈|不|吃|肉|。","wǒ|mā ma|bù|chī|ròu|","My mum doesn't eat meat."]}],"spot":[{"en":"I don't have any money.","right":"我没有钱。","wrong":"我不有钱。","full":["我|没有|钱|。","wǒ|méi yǒu|qián|","I don't have any money."]},{"en":"He didn't come yesterday.","right":"他昨天没来。","wrong":"他昨天不来。","full":["他|昨天|没|来|。","tā|zuó tiān|méi|lái|","He didn't come yesterday."]}]},{"id":"ma","level":1,"title":"吗: yes-or-no questions","pattern":"Statement + 吗？","why":"Put 吗 on the end of a statement and it becomes a yes-or-no question. The word order stays exactly the same.","mark":["吗"],"mistake":["你叫什么名字吗？","你叫什么名字？","A question word like 什么 already makes a question, so it doesn't need 吗."],"ex":[["你|好|吗|？","nǐ|hǎo|ma|","How are you?"],["你|是|老师|吗|？","nǐ|shì|lǎo shī|ma|","Are you a teacher?"],["他|喝茶|吗|？","tā|hē chá|ma|","Does he drink tea?"]],"gap":[{"en":"Do you like China?","before":"你喜欢中国","after":"？","a":"吗","wrong":["的","了","很"],"pins":{"吗":"ma","的":"de","了":"le","很":"hěn"},"full":["你|喜欢|中国|吗|？","nǐ|xǐ huan|Zhōng guó|ma|","Do you like China?"]},{"en":"Is he a student?","before":"他是学生","after":"？","a":"吗","wrong":["不","是","也"],"pins":{"吗":"ma","不":"bù","是":"shì","也":"yě"},"full":["他|是|学生|吗|？","tā|shì|xué sheng|ma|","Is he a student?"]},{"en":"Is this your book?","before":"这","after":"你的书吗？","a":"是","wrong":["吗","很","了"],"pins":{"是":"shì","吗":"ma","很":"hěn","了":"le"},"full":["这|是|你|的|书|吗|？","zhè|shì|nǐ|de|shū|ma|","Is this your book?"]},{"en":"Are you going to school today?","before":"你今天去学校","after":"？","a":"吗","wrong":["的","很","在"],"pins":{"吗":"ma","的":"de","很":"hěn","在":"zài"},"full":["你|今天|去|学校|吗|？","nǐ|jīn tiān|qù|xué xiào|ma|","Are you going to school today?"]}],"order":[{"en":"Do you drink coffee?","a":"你|喝|咖啡|吗|？","alt":[],"full":["你|喝|咖啡|吗|？","nǐ|hē|kā fēi|ma|","Do you drink coffee?"]},{"en":"Is she your older sister?","a":"她|是|你|的|姐姐|吗|？","alt":[],"full":["她|是|你|的|姐姐|吗|？","tā|shì|nǐ|de|jiě jie|ma|","Is she your older sister?"]},{"en":"Do you have a dog?","a":"你|有|狗|吗|？","alt":[],"full":["你|有|狗|吗|？","nǐ|yǒu|gǒu|ma|","Do you have a dog?"]},{"en":"Is he coming tomorrow?","a":"他|明天|来|吗|？","alt":["明天|他|来|吗|？"],"full":["他|明天|来|吗|？","tā|míng tiān|lái|ma|","Is he coming tomorrow?"]}],"spot":[{"en":"Are you a teacher?","right":"你是老师吗？","wrong":"你吗是老师？","full":["你|是|老师|吗|？","nǐ|shì|lǎo shī|ma|","Are you a teacher?"]},{"en":"What is your name?","right":"你叫什么名字？","wrong":"你叫什么名字吗？","full":["你|叫|什么|名字|？","nǐ|jiào|shén me|míng zi|","What is your name?"]}]},{"id":"de","level":1,"title":"的: my, and describing","pattern":"Owner or description + 的 + noun","why":"The owner or the description always comes before the thing, the opposite of \"the book of mine\". With close family it is often dropped: 我妈妈.","mark":["的"],"mistake":["书的我","我的书","Owner first, then 的, then the thing."],"ex":[["这|是|我|的|书|。","zhè|shì|wǒ|de|shū|","This is my book."],["他|的|朋友|很|好|。","tā|de|péng you|hěn|hǎo|","His friend is very nice."],["我|喜欢|红色|的|车|。","wǒ|xǐ huan|hóng sè|de|chē|","I like red cars."]],"gap":[{"en":"This is the teacher's book.","before":"这是老师","after":"书。","a":"的","wrong":["了","吗","是"],"pins":{"的":"de","了":"le","吗":"ma","是":"shì"},"full":["这|是|老师|的|书|。","zhè|shì|lǎo shī|de|shū|","This is the teacher's book."]},{"en":"That is my computer.","before":"那是我","after":"电脑。","a":"的","wrong":["很","在","不"],"pins":{"的":"de","很":"hěn","在":"zài","不":"bù"},"full":["那|是|我|的|电脑|。","nà|shì|wǒ|de|diàn nǎo|","That is my computer."]},{"en":"She is my friend.","before":"她是我","after":"朋友。","a":"的","wrong":["吗","了","都"],"pins":{"的":"de","吗":"ma","了":"le","都":"dōu"},"full":["她|是|我|的|朋友|。","tā|shì|wǒ|de|péng you|","She is my friend."]},{"en":"Whose book is this?","before":"这是谁","after":"书？","a":"的","wrong":["吗","了","很"],"pins":{"的":"de","吗":"ma","了":"le","很":"hěn"},"full":["这|是|谁|的|书|？","zhè|shì|shéi|de|shū|","Whose book is this?"]}],"order":[{"en":"This is his phone.","a":"这|是|他|的|手机|。","alt":[],"full":["这|是|他|的|手机|。","zhè|shì|tā|de|shǒu jī|","This is his phone."]},{"en":"My friend's home is very big.","a":"我|朋友|的|家|很|大|。","alt":[],"full":["我|朋友|的|家|很|大|。","wǒ|péng you|de|jiā|hěn|dà|","My friend's home is very big."]},{"en":"I like her dog.","a":"我|喜欢|她|的|狗|。","alt":[],"full":["我|喜欢|她|的|狗|。","wǒ|xǐ huan|tā|de|gǒu|","I like her dog."]},{"en":"That is my dad's car.","a":"那|是|我|爸爸|的|车|。","alt":[],"full":["那|是|我|爸爸|的|车|。","nà|shì|wǒ|bà ba|de|chē|","That is my dad's car."]}],"spot":[{"en":"This is my book.","right":"这是我的书。","wrong":"这是书的我。","full":["这|是|我|的|书|。","zhè|shì|wǒ|de|shū|","This is my book."]},{"en":"I like his dog.","right":"我喜欢他的狗。","wrong":"我喜欢狗的他。","full":["我|喜欢|他|的|狗|。","wǒ|xǐ huan|tā|de|gǒu|","I like his dog."]}]},{"id":"measure","level":1,"title":"Measure words","pattern":"Number or 这/那 + measure word + noun","why":"A number can't sit directly on a noun: a measure word goes between them. 个 is the general one, 本 is for books, 杯 for cups and 只 for many animals. For \"two\" of something, say 两, not 二.","mark":["本","杯","个"],"mistake":["我有三书。","我有三本书。","A number needs a measure word before the noun."],"ex":[["我|有|三|本|书|。","wǒ|yǒu|sān|běn|shū|","I have three books."],["我|要|两|杯|茶|。","wǒ|yào|liǎng|bēi|chá|","I'd like two cups of tea."],["这|个|人|是|我|的|老师|。","zhè|gè|rén|shì|wǒ|de|lǎo shī|","This person is my teacher."]],"gap":[{"en":"I have a dog.","before":"我有一","after":"狗。","a":"只","wrong":["本","杯","张"],"pins":{"只":"zhī","本":"běn","杯":"bēi","张":"zhāng"},"full":["我|有|一|只|狗|。","wǒ|yǒu|yī|zhī|gǒu|","I have a dog."]},{"en":"There are three books on the table.","before":"桌子上有三","after":"书。","a":"本","wrong":["只","杯","条"],"pins":{"本":"běn","只":"zhī","杯":"bēi","条":"tiáo"},"full":["桌子|上|有|三|本|书|。","zhuō zi|shang|yǒu|sān|běn|shū|","There are three books on the table."]},{"en":"I'd like a glass of water.","before":"我要一","after":"水。","a":"杯","wrong":["本","只","张"],"pins":{"杯":"bēi","本":"běn","只":"zhī","张":"zhāng"},"full":["我|要|一|杯|水|。","wǒ|yào|yī|bēi|shuǐ|","I'd like a glass of water."]},{"en":"There are five people in our family.","before":"我们家有五","after":"人。","a":"个","wrong":["本","杯","张"],"pins":{"个":"gè","本":"běn","杯":"bēi","张":"zhāng"},"full":["我们|家|有|五|个人|。","wǒ men|jiā|yǒu|wǔ|gè rén|","There are five people in our family."]}],"order":[{"en":"I have two friends.","a":"我|有|两|个|朋友|。","alt":[],"full":["我|有|两|个|朋友|。","wǒ|yǒu|liǎng|gè|péng you|","I have two friends."]},{"en":"This book is very good.","a":"这|本|书|很|好|。","alt":[],"full":["这|本|书|很|好|。","zhè|běn|shū|hěn|hǎo|","This book is very good."]},{"en":"She wants three cups of coffee.","a":"她|要|三|杯|咖啡|。","alt":[],"full":["她|要|三|杯|咖啡|。","tā|yào|sān|bēi|kā fēi|","She wants three cups of coffee."]},{"en":"That person is my dad.","a":"那|个|人|是|我|爸爸|。","alt":[],"full":["那|个|人|是|我|爸爸|。","nà|gè|rén|shì|wǒ|bà ba|","That person is my dad."]}],"spot":[{"en":"I have three books.","right":"我有三本书。","wrong":"我有三书。","full":["我|有|三|本|书|。","wǒ|yǒu|sān|běn|shū|","I have three books."]},{"en":"I have two friends.","right":"我有两个朋友。","wrong":"我有二个朋友。","full":["我|有|两|个|朋友|。","wǒ|yǒu|liǎng|gè|péng you|","I have two friends."]}]},{"id":"hen","level":1,"title":"很 + describing word","pattern":"Noun + 很 + adjective","why":"Chinese adjectives work like verbs, so they don't need 是. 很 usually joins them, and often means little more than \"is\", not a strong \"very\".","mark":["很"],"mistake":["她是漂亮。","她很漂亮。","No 是 before an adjective."],"ex":[["今天|很|热|。","jīn tiān|hěn|rè|","It is hot today."],["这|个|很|好吃|。","zhè|gè|hěn|hǎo chī|","This is delicious."],["她|很|高|。","tā|hěn|gāo|","She is tall."]],"gap":[{"en":"My teacher is nice.","before":"我的老师","after":"好。","a":"很","wrong":["是","的","吗"],"pins":{"很":"hěn","是":"shì","的":"de","吗":"ma"},"full":["我|的|老师|很|好|。","wǒ|de|lǎo shī|hěn|hǎo|","My teacher is nice."]},{"en":"Chinese is hard.","before":"中文","after":"难。","a":"很","wrong":["是","没","的"],"pins":{"很":"hěn","是":"shì","没":"méi","的":"de"},"full":["中文|很|难|。","Zhōng wén|hěn|nán|","Chinese is hard."]},{"en":"The weather is good today.","before":"今天天气","after":"好。","a":"很","wrong":["是","有","在"],"pins":{"很":"hěn","是":"shì","有":"yǒu","在":"zài"},"full":["今天|天气|很|好|。","jīn tiān|tiān qì|hěn|hǎo|","The weather is good today."]},{"en":"This apple is big.","before":"这个苹果","after":"大。","a":"很","wrong":["是","了","吗"],"pins":{"很":"hěn","是":"shì","了":"le","吗":"ma"},"full":["这|个|苹果|很|大|。","zhè|gè|píng guǒ|hěn|dà|","This apple is big."]}],"order":[{"en":"My mum is very busy today.","a":"今天|我|妈妈|很|忙|。","alt":["我|妈妈|今天|很|忙|。"],"full":["今天|我|妈妈|很|忙|。","jīn tiān|wǒ|mā ma|hěn|máng|","My mum is very busy today."]},{"en":"This book is very expensive.","a":"这|本|书|很|贵|。","alt":[],"full":["这|本|书|很|贵|。","zhè|běn|shū|hěn|guì|","This book is very expensive."]},{"en":"The weather is cold today.","a":"今天|天气|很|冷|。","alt":["天气|今天|很|冷|。"],"full":["今天|天气|很|冷|。","jīn tiān|tiān qì|hěn|lěng|","The weather is cold today."]},{"en":"My friend is very tall.","a":"我|朋友|很|高|。","alt":[],"full":["我|朋友|很|高|。","wǒ|péng you|hěn|gāo|","My friend is very tall."]}],"spot":[{"en":"She is beautiful.","right":"她很漂亮。","wrong":"她是漂亮。","full":["她|很|漂亮|。","tā|hěn|piào liang|","She is beautiful."]},{"en":"It is hot today.","right":"今天很热。","wrong":"今天是热。","full":["今天|很|热|。","jīn tiān|hěn|rè|","It is hot today."]}]},{"id":"ye-dou","level":1,"title":"也 and 都: too and all","pattern":"Subject + 也 or 都 + verb","why":"Both go straight before the verb, never at the front of the sentence. 都 sums up the people or things named before it.","mark":["也","都"],"mistake":["也我是学生。","我也是学生。","也 follows the subject and comes before the verb."],"ex":[["我|也|是|学生|。","wǒ|yě|shì|xué sheng|","I am a student too."],["我们|都|喜欢|茶|。","wǒ men|dōu|xǐ huan|chá|","We all like tea."],["他们|都|是|老师|。","tā men|dōu|shì|lǎo shī|","They are all teachers."]],"gap":[{"en":"I drink tea too.","before":"我","after":"喝茶。","a":"也","wrong":["吗","的","很"],"pins":{"也":"yě","吗":"ma","的":"de","很":"hěn"},"full":["我|也|喝茶|。","wǒ|yě|hē chá|","I drink tea too."]},{"en":"They are all Chinese.","before":"他们","after":"是中国人。","a":"都","wrong":["也","很","吗"],"pins":{"都":"dōu","也":"yě","很":"hěn","吗":"ma"},"full":["他们|都|是|中国|人|。","tā men|dōu|shì|Zhōng guó|rén|","They are all Chinese."]},{"en":"She likes cats, and I like cats too.","before":"她喜欢猫，我","after":"喜欢猫。","a":"也","wrong":["都","很","了"],"pins":{"也":"yě","都":"dōu","很":"hěn","了":"le"},"full":["她|喜欢|猫|，|我|也|喜欢|猫|。","tā|xǐ huan|māo||wǒ|yě|xǐ huan|māo|","She likes cats, and I like cats too."]},{"en":"We are all going to school.","before":"我们","after":"去学校。","a":"都","wrong":["也","的","吗"],"pins":{"都":"dōu","也":"yě","的":"de","吗":"ma"},"full":["我们|都|去|学校|。","wǒ men|dōu|qù|xué xiào|","We are all going to school."]}],"order":[{"en":"My friend is also a teacher.","a":"我|朋友|也|是|老师|。","alt":[],"full":["我|朋友|也|是|老师|。","wǒ|péng you|yě|shì|lǎo shī|","My friend is also a teacher."]},{"en":"They all have cars.","a":"他们|都|有|车|。","alt":[],"full":["他们|都|有|车|。","tā men|dōu|yǒu|chē|","They all have cars."]},{"en":"We are all very busy.","a":"我们|都|很|忙|。","alt":[],"full":["我们|都|很|忙|。","wǒ men|dōu|hěn|máng|","We are all very busy."]},{"en":"He also likes dogs.","a":"他|也|喜欢|狗|。","alt":[],"full":["他|也|喜欢|狗|。","tā|yě|xǐ huan|gǒu|","He also likes dogs."]}],"spot":[{"en":"I am a student too.","right":"我也是学生。","wrong":"也我是学生。","full":["我|也|是|学生|。","wǒ|yě|shì|xué sheng|","I am a student too."]},{"en":"We are all going.","right":"我们都去。","wrong":"都我们去。","full":["我们|都|去|。","wǒ men|dōu|qù|","We are all going."]}]},{"id":"zai","level":1,"title":"在 + place + verb","pattern":"Subject + 在 + place + verb","why":"Where something happens comes before the action: literally \"I at home eat\". English puts it at the end.","mark":["在"],"mistake":["我吃饭在家。","我在家吃饭。","The place goes before the verb."],"ex":[["我|在|家|吃饭|。","wǒ|zài|jiā|chī fàn|","I eat at home."],["他|在|学校|工作|。","tā|zài|xué xiào|gōng zuò|","He works at a school."],["她|在|北京|学习|中文|。","tā|zài|Běi jīng|xué xí|Zhōng wén|","She studies Chinese in Beijing."]],"gap":[{"en":"I study at school.","before":"我","after":"学校学习。","a":"在","wrong":["是","有","很"],"pins":{"在":"zài","是":"shì","有":"yǒu","很":"hěn"},"full":["我|在|学校|学习|。","wǒ|zài|xué xiào|xué xí|","I study at school."]},{"en":"They read at home.","before":"他们","after":"家看书。","a":"在","wrong":["很","的","吗"],"pins":{"在":"zài","很":"hěn","的":"de","吗":"ma"},"full":["他们|在|家|看书|。","tā men|zài|jiā|kàn shū|","They read at home."]},{"en":"My mum works at a hospital.","before":"我妈妈","after":"医院工作。","a":"在","wrong":["是","有","很"],"pins":{"在":"zài","是":"shì","有":"yǒu","很":"hěn"},"full":["我|妈妈|在|医院|工作|。","wǒ|mā ma|zài|yī yuàn|gōng zuò|","My mum works at a hospital."]},{"en":"Where do you work?","before":"你","after":"哪儿工作？","a":"在","wrong":["吗","很","了"],"pins":{"在":"zài","吗":"ma","很":"hěn","了":"le"},"full":["你|在|哪儿|工作|？","nǐ|zài|nǎ r|gōng zuò|","Where do you work?"]}],"order":[{"en":"I read at home.","a":"我|在|家|看书|。","alt":[],"full":["我|在|家|看书|。","wǒ|zài|jiā|kàn shū|","I read at home."]},{"en":"She drinks coffee at school.","a":"她|在|学校|喝|咖啡|。","alt":[],"full":["她|在|学校|喝|咖啡|。","tā|zài|xué xiào|hē|kā fēi|","She drinks coffee at school."]},{"en":"We eat at a restaurant.","a":"我们|在|饭店|吃饭|。","alt":[],"full":["我们|在|饭店|吃饭|。","wǒ men|zài|fàn diàn|chī fàn|","We eat at a restaurant."]},{"en":"My dad works in Beijing.","a":"我|爸爸|在|北京|工作|。","alt":[],"full":["我|爸爸|在|北京|工作|。","wǒ|bà ba|zài|Běi jīng|gōng zuò|","My dad works in Beijing."]}],"spot":[{"en":"I eat at home.","right":"我在家吃饭。","wrong":"我吃饭在家。","full":["我|在|家|吃饭|。","wǒ|zài|jiā|chī fàn|","I eat at home."]},{"en":"He works at a school.","right":"他在学校工作。","wrong":"他工作在学校。","full":["他|在|学校|工作|。","tā|zài|xué xiào|gōng zuò|","He works at a school."]}]},{"id":"time","level":1,"title":"Time goes before the verb","pattern":"Time + subject + verb, or subject + time + verb","why":"When something happens goes before the verb, either at the very start of the sentence or just after the subject. It doesn't go at the end, as it can in English.","mark":["明天","今天","晚上","每天","上午","今年"],"mistake":["我去学校明天。","我明天去学校。","The time word comes before the verb."],"ex":[["我|明天|去|北京|。","wǒ|míng tiān|qù|Běi jīng|","I am going to Beijing tomorrow."],["今天|他|不|工作|。","jīn tiān|tā|bù|gōng zuò|","He isn't working today."],["我们|晚上|吃饭|。","wǒ men|wǎn shang|chī fàn|","We eat in the evening."]],"gap":[{"en":"I am going to school tomorrow.","before":"我","after":"去学校。","a":"明天","wrong":["学校","很","吗"],"pins":{"明天":"míng tiān","学校":"xué xiào","很":"hěn","吗":"ma"},"full":["我|明天|去|学校|。","wǒ|míng tiān|qù|xué xiào|","I am going to school tomorrow."]},{"en":"He drinks tea every day.","before":"他","after":"喝茶。","a":"每天","wrong":["很","的","在"],"pins":{"每天":"měi tiān","很":"hěn","的":"de","在":"zài"},"full":["他|每|天|喝茶|。","tā|měi|tiān|hē chá|","He drinks tea every day."]},{"en":"I am not working today.","before":"","after":"我不工作。","a":"今天","wrong":["很","吗","的"],"pins":{"今天":"jīn tiān","很":"hěn","吗":"ma","的":"de"},"full":["今天|我|不|工作|。","jīn tiān|wǒ|bù|gōng zuò|","I am not working today."]},{"en":"We read in the evening.","before":"我们","after":"看书。","a":"晚上","wrong":["是","了","吗"],"pins":{"晚上":"wǎn shang","是":"shì","了":"le","吗":"ma"},"full":["我们|晚上|看书|。","wǒ men|wǎn shang|kàn shū|","We read in the evening."]}],"order":[{"en":"I go to school every day.","a":"我|每天|去|学校|。","alt":["每天|我|去|学校|。"],"full":["我|每天|去|学校|。","wǒ|měi tiān|qù|xué xiào|","I go to school every day."]},{"en":"She is coming tomorrow.","a":"她|明天|来|。","alt":["明天|她|来|。"],"full":["她|明天|来|。","tā|míng tiān|lái|","She is coming tomorrow."]},{"en":"My dad works in the morning.","a":"我|爸爸|上午|工作|。","alt":["上午|我|爸爸|工作|。"],"full":["我|爸爸|上午|工作|。","wǒ|bà ba|shàng wǔ|gōng zuò|","My dad works in the morning."]},{"en":"I am not going to Beijing this year.","a":"今年|我|不|去|北京|。","alt":["我|今年|不|去|北京|。"],"full":["今年|我|不|去|北京|。","jīn nián|wǒ|bù|qù|Běi jīng|","I am not going to Beijing this year."]}],"spot":[{"en":"I am going to school tomorrow.","right":"我明天去学校。","wrong":"我去学校明天。","full":["我|明天|去|学校|。","wǒ|míng tiān|qù|xué xiào|","I am going to school tomorrow."]},{"en":"He drinks tea every day.","right":"他每天喝茶。","wrong":"他喝茶每天。","full":["他|每|天|喝茶|。","tā|měi|tiān|hē chá|","He drinks tea every day."]}]},{"id":"le","level":1,"title":"了 after a verb: it's done","pattern":"Verb + 了 + amount + object","why":"了 after a verb says the action was completed. It isn't a past tense: it marks that something got done, and it usually comes with an amount, as in 三本书. To say it didn't happen, use 没 and drop the 了.","mark":["了"],"mistake":["我没买了书。","我没买书。","没 already says it didn't happen, so 了 goes."],"ex":[["我|买|了|三|本|书|。","wǒ|mǎi|le|sān|běn|shū|","I bought three books."],["他|喝|了|一|杯|茶|。","tā|hē|le|yī|bēi|chá|","He drank a cup of tea."],["她|吃|了|很|多|苹果|。","tā|chī|le|hěn|duō|píng guǒ|","She ate a lot of apples."]],"gap":[{"en":"I bought two cups of coffee.","before":"我买","after":"两杯咖啡。","a":"了","wrong":["的","吗","很"],"pins":{"了":"le","的":"de","吗":"ma","很":"hěn"},"full":["我|买|了|两|杯|咖啡|。","wǒ|mǎi|le|liǎng|bēi|kā fēi|","I bought two cups of coffee."]},{"en":"He read three books.","before":"他看","after":"三本书。","a":"了","wrong":["的","很","吗"],"pins":{"了":"le","的":"de","很":"hěn","吗":"ma"},"full":["他|看|了|三|本|书|。","tā|kàn|le|sān|běn|shū|","He read three books."]},{"en":"I didn't buy books yesterday.","before":"昨天我","after":"买书。","a":"没","wrong":["不","了","很"],"pins":{"没":"méi","不":"bù","了":"le","很":"hěn"},"full":["昨天|我|没|买|书|。","zuó tiān|wǒ|méi|mǎi|shū|","I didn't buy books yesterday."]},{"en":"She drank a glass of water.","before":"她喝","after":"一杯水。","a":"了","wrong":["吗","的","也"],"pins":{"了":"le","吗":"ma","的":"de","也":"yě"},"full":["她|喝|了|一|杯|水|。","tā|hē|le|yī|bēi|shuǐ|","She drank a glass of water."]}],"order":[{"en":"I ate two apples.","a":"我|吃|了|两|个|苹果|。","alt":[],"full":["我|吃|了|两|个|苹果|。","wǒ|chī|le|liǎng|gè|píng guǒ|","I ate two apples."]},{"en":"He bought one book.","a":"他|买|了|一|本|书|。","alt":[],"full":["他|买|了|一|本|书|。","tā|mǎi|le|yī|běn|shū|","He bought one book."]},{"en":"We drank three cups of tea.","a":"我们|喝|了|三|杯|茶|。","alt":[],"full":["我们|喝|了|三|杯|茶|。","wǒ men|hē|le|sān|bēi|chá|","We drank three cups of tea."]},{"en":"My friend read this book.","a":"我|朋友|看|了|这|本|书|。","alt":[],"full":["我|朋友|看|了|这|本|书|。","wǒ|péng you|kàn|le|zhè|běn|shū|","My friend read this book."]}],"spot":[{"en":"I didn't buy books.","right":"我没买书。","wrong":"我没买了书。","full":["我|没|买|书|。","wǒ|méi|mǎi|shū|","I didn't buy books."]},{"en":"I bought three books.","right":"我买了三本书。","wrong":"了我买三本书。","full":["我|买|了|三|本|书|。","wǒ|mǎi|le|sān|běn|shū|","I bought three books."]}]},{"id":"you","level":1,"title":"有: have, and there is","pattern":"Person + 有 + thing · Place + 有 + thing","why":"有 means \"have\", and after a place it means \"there is\". Its negative is always 没有.","mark":["有"],"mistake":["教室里是很多人。","教室里有很多人。","For \"there is\", use 有, not 是."],"ex":[["我|有|一|个|哥哥|。","wǒ|yǒu|yī|gè|gē ge|","I have an older brother."],["桌子|上|有|一|本|书|。","zhuō zi|shang|yǒu|yī|běn|shū|","There is a book on the table."],["学校|里|有|很|多|学生|。","xué xiào|li|yǒu|hěn|duō|xué sheng|","There are many students in the school."]],"gap":[{"en":"I have two younger sisters.","before":"我","after":"两个妹妹。","a":"有","wrong":["是","在","很"],"pins":{"有":"yǒu","是":"shì","在":"zài","很":"hěn"},"full":["我|有|两|个|妹妹|。","wǒ|yǒu|liǎng|gè|mèi mei|","I have two younger sisters."]},{"en":"There is a cat at home.","before":"家里","after":"一只猫。","a":"有","wrong":["是","很","吗"],"pins":{"有":"yǒu","是":"shì","很":"hěn","吗":"ma"},"full":["家里|有|一|只|猫|。","jiā li|yǒu|yī|zhī|māo|","There is a cat at home."]},{"en":"He doesn't have a car.","before":"他没","after":"车。","a":"有","wrong":["是","在","很"],"pins":{"有":"yǒu","是":"shì","在":"zài","很":"hěn"},"full":["他|没有|车|。","tā|méi yǒu|chē|","He doesn't have a car."]}],"order":[{"en":"I have many friends.","a":"我|有|很多|朋友|。","alt":[],"full":["我|有|很多|朋友|。","wǒ|yǒu|hěn duō|péng you|","I have many friends."]},{"en":"There are three people at home.","a":"家|里|有|三|个|人|。","alt":[],"full":["家|里|有|三|个|人|。","jiā|li|yǒu|sān|gè|rén|","There are three people at home."]},{"en":"Do you have a phone?","a":"你|有|手机|吗|？","alt":[],"full":["你|有|手机|吗|？","nǐ|yǒu|shǒu jī|ma|","Do you have a phone?"]}],"spot":[{"en":"There are many people in the classroom.","right":"教室里有很多人。","wrong":"教室里是很多人。","full":["教室|里|有|很|多|人|。","jiào shì|li|yǒu|hěn|duō|rén|","There are many people in the classroom."]},{"en":"I don't have an older brother.","right":"我没有哥哥。","wrong":"我不有哥哥。","full":["我|没有|哥哥|。","wǒ|méi yǒu|gē ge|","I don't have an older brother."]}]},{"id":"zai-verb","level":1,"title":"在: is at a place","pattern":"Person or thing + 在 + place","why":"是 says what something is. 在 says where it is, and it is the verb of the sentence, so no 是 is needed.","mark":["在"],"mistake":["他是学校。","他在学校。","He isn't a school: use 在 for where someone is."],"ex":[["我|在|家|。","wǒ|zài|jiā|","I am at home."],["书|在|桌子|上|。","shū|zài|zhuō zi|shang|","The book is on the table."],["你|妈妈|在|哪儿|？","nǐ|mā ma|zài|nǎ r|","Where is your mum?"]],"gap":[{"en":"The teacher is at school.","before":"老师","after":"学校。","a":"在","wrong":["是","有","很"],"pins":{"在":"zài","是":"shì","有":"yǒu","很":"hěn"},"full":["老师|在|学校|。","lǎo shī|zài|xué xiào|","The teacher is at school."]},{"en":"My phone is on the table.","before":"我的手机","after":"桌子上。","a":"在","wrong":["是","的","吗"],"pins":{"在":"zài","是":"shì","的":"de","吗":"ma"},"full":["我|的|手机|在|桌子|上|。","wǒ|de|shǒu jī|zài|zhuō zi|shang|","My phone is on the table."]},{"en":"They are in Beijing.","before":"他们","after":"北京。","a":"在","wrong":["是","很","吗"],"pins":{"在":"zài","是":"shì","很":"hěn","吗":"ma"},"full":["他们|在|北京|。","tā men|zài|Běi jīng|","They are in Beijing."]}],"order":[{"en":"My dad is in Beijing.","a":"我|爸爸|在|北京|。","alt":[],"full":["我|爸爸|在|北京|。","wǒ|bà ba|zài|Běi jīng|","My dad is in Beijing."]},{"en":"Where is your book?","a":"你|的|书|在|哪儿|？","alt":[],"full":["你|的|书|在|哪儿|？","nǐ|de|shū|zài|nǎ r|","Where is your book?"]},{"en":"The cat is on the table.","a":"猫|在|桌子|上|。","alt":[],"full":["猫|在|桌子|上|。","māo|zài|zhuō zi|shang|","The cat is on the table."]}],"spot":[{"en":"He is at the hospital.","right":"他在医院。","wrong":"他是医院。","full":["他|在|医院|。","tā|zài|yī yuàn|","He is at the hospital."]},{"en":"The book is on the table.","right":"书在桌子上。","wrong":"书是桌子上。","full":["书|在|桌子|上|。","shū|zài|zhuō zi|shang|","The book is on the table."]}]},{"id":"ne","level":1,"title":"呢: and you?","pattern":"Topic + 呢？","why":"呢 after a person or thing asks the same question about them, or asks where they are. It saves repeating yourself.","mark":["呢"],"mistake":["我很好，你吗？","我很好，你呢？","吗 needs a whole statement before it. For \"and you?\", use 呢."],"ex":[["我|很|好|，|你|呢|？","wǒ|hěn|hǎo||nǐ|ne|","I'm fine, and you?"],["我|喝茶|，|他|呢|？","wǒ|hē chá||tā|ne|","I'm having tea, what about him?"],["我|的|书|呢|？","wǒ|de|shū|ne|","Where is my book?"]],"gap":[{"en":"I'm a teacher, and you?","before":"我是老师，你","after":"？","a":"呢","wrong":["吗","的","了"],"pins":{"呢":"ne","吗":"ma","的":"de","了":"le"},"full":["我|是|老师|，|你|呢|？","wǒ|shì|lǎo shī||nǐ|ne|","I'm a teacher, and you?"]},{"en":"He is going to Beijing, and you?","before":"他去北京，你","after":"？","a":"呢","wrong":["吗","很","的"],"pins":{"呢":"ne","吗":"ma","很":"hěn","的":"de"},"full":["他|去|北京|，|你|呢|？","tā|qù|Běi jīng||nǐ|ne|","He is going to Beijing, and you?"]},{"en":"Where is my phone?","before":"我的手机","after":"？","a":"呢","wrong":["吗","很","也"],"pins":{"呢":"ne","吗":"ma","很":"hěn","也":"yě"},"full":["我|的|手机|呢|？","wǒ|de|shǒu jī|ne|","Where is my phone?"]}],"order":[{"en":"And your friend?","a":"你|的|朋友|呢|？","alt":[],"full":["你|的|朋友|呢|？","nǐ|de|péng you|ne|","And your friend?"]},{"en":"Where is my dad?","a":"我|爸爸|呢|？","alt":[],"full":["我|爸爸|呢|？","wǒ|bà ba|ne|","Where is my dad?"]},{"en":"Where is the teacher's book?","a":"老师|的|书|呢|？","alt":[],"full":["老师|的|书|呢|？","lǎo shī|de|shū|ne|","Where is the teacher's book?"]}],"spot":[{"en":"I'm busy, and you?","right":"我很忙，你呢？","wrong":"我很忙，你吗？","full":["我|很|忙|，|你|呢|？","wǒ|hěn|máng||nǐ|ne|","I'm busy, and you?"]},{"en":"Where is my book?","right":"我的书呢？","wrong":"我的书吗？","full":["我|的|书|呢|？","wǒ|de|shū|ne|","Where is my book?"]}]},{"id":"qwords","level":1,"title":"Question words stay in place","pattern":"The question word goes where the answer will go","why":"English moves \"what\" and \"where\" to the front. Chinese leaves them where the answer would be, so a question has the same order as its answer.","mark":["什么","谁","哪儿"],"mistake":["什么你喜欢？","你喜欢什么？","Keep the normal word order."],"ex":[["你|喜欢|什么|？","nǐ|xǐ huan|shén me|","What do you like?"],["他|是|谁|？","tā|shì|shéi|","Who is he?"],["你|去|哪儿|？","nǐ|qù|nǎ r|","Where are you going?"]],"gap":[{"en":"What is your name?","before":"你叫","after":"名字？","a":"什么","wrong":["谁","哪儿","吗"],"pins":{"什么":"shén me","谁":"shéi","哪儿":"nǎ r","吗":"ma"},"full":["你|叫|什么|名字|？","nǐ|jiào|shén me|míng zi|","What is your name?"]},{"en":"Who is that person?","before":"那个人是","after":"？","a":"谁","wrong":["什么","哪儿","吗"],"pins":{"谁":"shéi","什么":"shén me","哪儿":"nǎ r","吗":"ma"},"full":["那|个|人|是|谁|？","nà|gè|rén|shì|shéi|","Who is that person?"]},{"en":"Where is your mum?","before":"你妈妈在","after":"？","a":"哪儿","wrong":["什么","谁","很"],"pins":{"哪儿":"nǎ r","什么":"shén me","谁":"shéi","很":"hěn"},"full":["你|妈妈|在|哪儿|？","nǐ|mā ma|zài|nǎ r|","Where is your mum?"]}],"order":[{"en":"What are you eating?","a":"你|吃|什么|？","alt":[],"full":["你|吃|什么|？","nǐ|chī|shén me|","What are you eating?"]},{"en":"Where are you going tomorrow?","a":"你|明天|去|哪儿|？","alt":["明天|你|去|哪儿|？"],"full":["你|明天|去|哪儿|？","nǐ|míng tiān|qù|nǎ r|","Where are you going tomorrow?"]},{"en":"Who is your teacher?","a":"谁|是|你|的|老师|？","alt":["你|的|老师|是|谁|？"],"full":["谁|是|你|的|老师|？","shéi|shì|nǐ|de|lǎo shī|","Who is your teacher?"]}],"spot":[{"en":"What are you drinking?","right":"你喝什么？","wrong":"什么你喝？","full":["你|喝|什么|？","nǐ|hē|shén me|","What are you drinking?"]},{"en":"Where do you live?","right":"你住在哪儿？","wrong":"哪儿你住？","full":["你|住|在|哪儿|？","nǐ|zhù|zài|nǎ r|","Where do you live?"]}]},{"id":"ji-duoshao","level":1,"title":"几 and 多少: how many","pattern":"几 + measure word + noun · 多少 + noun","why":"几 is for numbers you expect to be small, and it needs a measure word. 多少 is for any amount, and often goes straight on the noun, as in 多少钱.","mark":["几","多少"],"mistake":["你有几书？","你有几本书？","几 needs a measure word, just as a number does."],"ex":[["你|有|几|个|孩子|？","nǐ|yǒu|jǐ|gè|hái zi|","How many children do you have?"],["现在|几点|？","xiàn zài|jǐ diǎn|","What time is it now?"],["这|个|多少|钱|？","zhè|gè|duō shao|qián|","How much is this?"]],"gap":[{"en":"How many people are in your family?","before":"你家有","after":"个人？","a":"几","wrong":["什么","谁","很"],"pins":{"几":"jǐ","什么":"shén me","谁":"shéi","很":"hěn"},"full":["你|家|有|几|个|人|？","nǐ|jiā|yǒu|jǐ|gè|rén|","How many people are in your family?"]},{"en":"How much is this book?","before":"这本书","after":"钱？","a":"多少","wrong":["几","什么","很"],"pins":{"多少":"duō shao","几":"jǐ","什么":"shén me","很":"hěn"},"full":["这|本|书|多少|钱|？","zhè|běn|shū|duō shao|qián|","How much is this book?"]},{"en":"What day of the week is it today?","before":"今天星期","after":"？","a":"几","wrong":["什么","多","吗"],"pins":{"几":"jǐ","什么":"shén me","多":"duō","吗":"ma"},"full":["今天|星期几|？","jīn tiān|xīng qī jǐ|","What day of the week is it today?"]}],"order":[{"en":"How many books do you have?","a":"你|有|几|本|书|？","alt":[],"full":["你|有|几|本|书|？","nǐ|yǒu|jǐ|běn|shū|","How many books do you have?"]},{"en":"How much is this cup of tea?","a":"这|杯|茶|多少|钱|？","alt":[],"full":["这|杯|茶|多少|钱|？","zhè|bēi|chá|duō shao|qián|","How much is this cup of tea?"]},{"en":"What time is it now?","a":"现在|几|点|？","alt":[],"full":["现在|几|点|？","xiàn zài|jǐ|diǎn|","What time is it now?"]}],"spot":[{"en":"How many books do you have?","right":"你有几本书？","wrong":"你有几书？","full":["你|有|几|本|书|？","nǐ|yǒu|jǐ|běn|shū|","How many books do you have?"]},{"en":"How much is this?","right":"这个多少钱？","wrong":"这个几钱？","full":["这|个|多少|钱|？","zhè|gè|duō shao|qián|","How much is this?"]}]},{"id":"hui","level":1,"title":"会: can, a skill you learned","pattern":"会 + verb","why":"会 is for what you have learned to do: speak a language, drive, swim. It goes before the verb.","mark":["会"],"mistake":["我会中文说。","我会说中文。","会, then the verb, then what you do."],"ex":[["我|会|说|中文|。","wǒ|huì|shuō|Zhōng wén|","I can speak Chinese."],["他|不|会|开车|。","tā|bù|huì|kāi chē|","He can't drive."],["你|会|做饭|吗|？","nǐ|huì|zuò fàn|ma|","Can you cook?"]],"gap":[{"en":"I can swim.","before":"我","after":"游泳。","a":"会","wrong":["是","很","的"],"pins":{"会":"huì","是":"shì","很":"hěn","的":"de"},"full":["我|会|游泳|。","wǒ|huì|yóu yǒng|","I can swim."]},{"en":"She can't drive.","before":"她不","after":"开车。","a":"会","wrong":["是","很","了"],"pins":{"会":"huì","是":"shì","很":"hěn","了":"le"},"full":["她|不|会|开车|。","tā|bù|huì|kāi chē|","She can't drive."]},{"en":"Can you speak English?","before":"你","after":"说英语吗？","a":"会","wrong":["是","很","了"],"pins":{"会":"huì","是":"shì","很":"hěn","了":"le"},"full":["你|会|说|英语|吗|？","nǐ|huì|shuō|Yīng yǔ|ma|","Can you speak English?"]}],"order":[{"en":"My mum can cook.","a":"我|妈妈|会|做饭|。","alt":[],"full":["我|妈妈|会|做饭|。","wǒ|mā ma|huì|zuò fàn|","My mum can cook."]},{"en":"He can't speak Chinese.","a":"他|不|会|说|中文|。","alt":[],"full":["他|不|会|说|中文|。","tā|bù|huì|shuō|Zhōng wén|","He can't speak Chinese."]},{"en":"Can you drive?","a":"你|会|开车|吗|？","alt":[],"full":["你|会|开车|吗|？","nǐ|huì|kāi chē|ma|","Can you drive?"]}],"spot":[{"en":"I can speak Chinese.","right":"我会说中文。","wrong":"我会中文说。","full":["我|会|说|中文|。","wǒ|huì|shuō|Zhōng wén|","I can speak Chinese."]},{"en":"He can't swim.","right":"他不会游泳。","wrong":"他会不游泳。","full":["他|不|会|游泳|。","tā|bù|huì|yóu yǒng|","He can't swim."]}]},{"id":"xiang","level":1,"title":"想: would like to","pattern":"想 + verb","why":"想 before a verb says what you would like to do. It is softer than 要. 不想 goes in front for \"don't want to\".","mark":["想"],"mistake":["我吃想饭。","我想吃饭。","想 comes before the verb."],"ex":[["我|想|喝|水|。","wǒ|xiǎng|hē|shuǐ|","I'd like some water."],["他|想|去|中国|。","tā|xiǎng|qù|Zhōng guó|","He wants to go to China."],["我|不|想|工作|。","wǒ|bù|xiǎng|gōng zuò|","I don't want to work."]],"gap":[{"en":"I'd like to go to Beijing.","before":"我","after":"去北京。","a":"想","wrong":["是","很","的"],"pins":{"想":"xiǎng","是":"shì","很":"hěn","的":"de"},"full":["我|想|去|北京|。","wǒ|xiǎng|qù|Běi jīng|","I'd like to go to Beijing."]},{"en":"What would you like to eat?","before":"你","after":"吃什么？","a":"想","wrong":["是","很","吗"],"pins":{"想":"xiǎng","是":"shì","很":"hěn","吗":"ma"},"full":["你|想|吃|什么|？","nǐ|xiǎng|chī|shén me|","What would you like to eat?"]},{"en":"She doesn't want to read.","before":"她不","after":"看书。","a":"想","wrong":["是","的","了"],"pins":{"想":"xiǎng","是":"shì","的":"de","了":"le"},"full":["她|不|想|看书|。","tā|bù|xiǎng|kàn shū|","She doesn't want to read."]}],"order":[{"en":"I'd like to buy a book.","a":"我|想|买|一|本|书|。","alt":[],"full":["我|想|买|一|本|书|。","wǒ|xiǎng|mǎi|yī|běn|shū|","I'd like to buy a book."]},{"en":"Would you like some tea?","a":"你|想|喝|茶|吗|？","alt":[],"full":["你|想|喝|茶|吗|？","nǐ|xiǎng|hē|chá|ma|","Would you like some tea?"]},{"en":"We want to go to school tomorrow.","a":"我们|明天|想|去|学校|。","alt":["明天|我们|想|去|学校|。"],"full":["我们|明天|想|去|学校|。","wǒ men|míng tiān|xiǎng|qù|xué xiào|","We want to go to school tomorrow."]}],"spot":[{"en":"I'd like some tea.","right":"我想喝茶。","wrong":"我喝想茶。","full":["我|想|喝茶|。","wǒ|xiǎng|hē chá|","I'd like some tea."]},{"en":"He wants to eat an apple.","right":"他想吃苹果。","wrong":"他吃想苹果。","full":["他|想|吃|苹果|。","tā|xiǎng|chī|píng guǒ|","He wants to eat an apple."]}]},{"id":"neng","level":1,"title":"能: can, if it's possible","pattern":"能 + verb","why":"能 says that something is possible or allowed. 会 is for a skill you have learned; 能 is for whether you are able to right now.","mark":["能"],"mistake":["你能吗帮我？","你能帮我吗？","吗 goes at the very end."],"ex":[["我|明天|能|来|。","wǒ|míng tiān|néng|lái|","I can come tomorrow."],["你|能|帮|我|吗|？","nǐ|néng|bāng|wǒ|ma|","Can you help me?"],["这里|不|能|吃饭|。","zhè li|bù|néng|chī fàn|","You can't eat here."]],"gap":[{"en":"I can't come today.","before":"今天我不","after":"来。","a":"能","wrong":["是","很","的"],"pins":{"能":"néng","是":"shì","很":"hěn","的":"de"},"full":["今天|我|不|能|来|。","jīn tiān|wǒ|bù|néng|lái|","I can't come today."]},{"en":"Can you help me?","before":"你","after":"帮我吗？","a":"能","wrong":["是","很","了"],"pins":{"能":"néng","是":"shì","很":"hěn","了":"le"},"full":["你|能|帮|我|吗|？","nǐ|néng|bāng|wǒ|ma|","Can you help me?"]},{"en":"You can't drink tea here.","before":"这里不","after":"喝茶。","a":"能","wrong":["是","很","了"],"pins":{"能":"néng","是":"shì","很":"hěn","了":"le"},"full":["这里|不|能|喝茶|。","zhè li|bù|néng|hē chá|","You can't drink tea here."]}],"order":[{"en":"Can you help me?","a":"你|能|帮|我|吗|？","alt":[],"full":["你|能|帮|我|吗|？","nǐ|néng|bāng|wǒ|ma|","Can you help me?"]},{"en":"I can't go today.","a":"我|今天|不|能|去|。","alt":["今天|我|不|能|去|。"],"full":["我|今天|不|能|去|。","wǒ|jīn tiān|bù|néng|qù|","I can't go today."]},{"en":"I can come tomorrow.","a":"明天|我|能|来|。","alt":["我|明天|能|来|。"],"full":["明天|我|能|来|。","míng tiān|wǒ|néng|lái|","I can come tomorrow."]}],"spot":[{"en":"Can you help me?","right":"你能帮我吗？","wrong":"你帮能我吗？","full":["你|能|帮|我|吗|？","nǐ|néng|bāng|wǒ|ma|","Can you help me?"]},{"en":"You can't eat here.","right":"这里不能吃饭。","wrong":"不能这里吃饭。","full":["这里|不|能|吃饭|。","zhè li|bù|néng|chī fàn|","You can't eat here."]}]},{"id":"he","level":1,"title":"和: and, between nouns","pattern":"Noun + 和 + noun","why":"和 joins people and things. Unlike English \"and\", it doesn't join verbs or whole sentences.","mark":["和"],"mistake":["我吃饭和喝茶。","我吃饭，也喝茶。","和 joins nouns, not actions."],"ex":[["我|和|他|是|朋友|。","wǒ|hé|tā|shì|péng you|","He and I are friends."],["我|喜欢|猫|和|狗|。","wǒ|xǐ huan|māo|hé|gǒu|","I like cats and dogs."],["爸爸|和|妈妈|都|很|忙|。","bà ba|hé|mā ma|dōu|hěn|máng|","Dad and Mum are both busy."]],"gap":[{"en":"You and I are both students.","before":"我","after":"你都是学生。","a":"和","wrong":["也","很","吗"],"pins":{"和":"hé","也":"yě","很":"hěn","吗":"ma"},"full":["我|和|你|都|是|学生|。","wǒ|hé|nǐ|dōu|shì|xué sheng|","You and I are both students."]},{"en":"I like tea and coffee.","before":"我喜欢茶","after":"咖啡。","a":"和","wrong":["也","是","很"],"pins":{"和":"hé","也":"yě","是":"shì","很":"hěn"},"full":["我|喜欢|茶|和|咖啡|。","wǒ|xǐ huan|chá|hé|kā fēi|","I like tea and coffee."]},{"en":"Dad and Mum are at home.","before":"爸爸","after":"妈妈在家。","a":"和","wrong":["也","很","吗"],"pins":{"和":"hé","也":"yě","很":"hěn","吗":"ma"},"full":["爸爸|和|妈妈|在|家|。","bà ba|hé|mā ma|zài|jiā|","Dad and Mum are at home."]}],"order":[{"en":"He and I are friends.","a":"我|和|他|是|朋友|。","alt":["他|和|我|是|朋友|。"],"full":["我|和|他|是|朋友|。","wǒ|hé|tā|shì|péng you|","He and I are friends."]},{"en":"She likes cats and dogs.","a":"她|喜欢|猫|和|狗|。","alt":["她|喜欢|狗|和|猫|。"],"full":["她|喜欢|猫|和|狗|。","tā|xǐ huan|māo|hé|gǒu|","She likes cats and dogs."]},{"en":"The teachers and students are all at school.","a":"老师|和|学生|都|在|学校|。","alt":["学生|和|老师|都|在|学校|。"],"full":["老师|和|学生|都|在|学校|。","lǎo shī|hé|xué sheng|dōu|zài|xué xiào|","The teachers and students are all at school."]}],"spot":[{"en":"He and I are friends.","right":"我和他是朋友。","wrong":"我是朋友和他。","full":["我|和|他|是|朋友|。","wǒ|hé|tā|shì|péng you|","He and I are friends."]},{"en":"I like cats and dogs.","right":"我喜欢猫和狗。","wrong":"我喜欢和猫狗。","full":["我|喜欢|猫|和|狗|。","wǒ|xǐ huan|māo|hé|gǒu|","I like cats and dogs."]}]},{"id":"tai","level":1,"title":"太…了: too, or so","pattern":"太 + adjective + 了","why":"太…了 means \"too\" or, when you are pleased, \"so\". The 了 here has nothing to do with the past. 不太 means \"not very\", and takes no 了.","mark":["太","了"],"mistake":["这个是太贵。","这个太贵了。","No 是, and finish with 了."],"ex":[["太|好|了|！","tài|hǎo|le|","That's great!"],["这|个|太|贵|了|。","zhè|gè|tài|guì|le|","This is too expensive."],["今天|太|热|了|。","jīn tiān|tài|rè|le|","It is so hot today."]],"gap":[{"en":"This book is too expensive.","before":"这本书太贵","after":"。","a":"了","wrong":["的","吗","很"],"pins":{"了":"le","的":"de","吗":"ma","很":"hěn"},"full":["这|本|书|太|贵|了|。","zhè|běn|shū|tài|guì|le|","This book is too expensive."]},{"en":"That's great!","before":"","after":"好了！","a":"太","wrong":["是","的","吗"],"pins":{"太":"tài","是":"shì","的":"de","吗":"ma"},"full":["太|好|了|！","tài|hǎo|le|","That's great!"]},{"en":"It is too cold today.","before":"今天","after":"冷了。","a":"太","wrong":["是","的","吗"],"pins":{"太":"tài","是":"shì","的":"de","吗":"ma"},"full":["今天|太|冷|了|。","jīn tiān|tài|lěng|le|","It is too cold today."]}],"order":[{"en":"This is too expensive.","a":"这个|太|贵|了|。","alt":[],"full":["这个|太|贵|了|。","zhè gè|tài|guì|le|","This is too expensive."]},{"en":"It is so hot today.","a":"今天|太|热|了|。","alt":[],"full":["今天|太|热|了|。","jīn tiān|tài|rè|le|","It is so hot today."]},{"en":"I am too busy.","a":"我|太|忙|了|。","alt":[],"full":["我|太|忙|了|。","wǒ|tài|máng|le|","I am too busy."]}],"spot":[{"en":"That's great!","right":"太好了！","wrong":"太好吗！","full":["太|好|了|！","tài|hǎo|le|","That's great!"]},{"en":"It is too cold today.","right":"今天太冷了。","wrong":"今天是太冷。","full":["今天|太|冷|了|。","jīn tiān|tài|lěng|le|","It is too cold today."]}]},{"id":"ba-particle","level":1,"title":"吧: let's, and right?","pattern":"Sentence + 吧","why":"吧 softens a sentence into a suggestion (\"let's\"), or turns it into a guess you want confirmed (\"right?\").","mark":["吧"],"mistake":["我们吧走。","我们走吧。","吧 goes at the very end."],"ex":[["我们|走|吧|。","wǒ men|zǒu|ba|","Let's go."],["你|是|老师|吧|？","nǐ|shì|lǎo shī|ba|","You're a teacher, right?"],["喝茶|吧|。","hē chá|ba|","Have some tea."]],"gap":[{"en":"Let's eat.","before":"我们吃饭","after":"。","a":"吧","wrong":["吗","很","的"],"pins":{"吧":"ba","吗":"ma","很":"hěn","的":"de"},"full":["我们|吃饭|吧|。","wǒ men|chī fàn|ba|","Let's eat."]},{"en":"You're a student, right?","before":"你是学生","after":"？","a":"吧","wrong":["很","也","是"],"pins":{"吧":"ba","很":"hěn","也":"yě","是":"shì"},"full":["你|是|学生|吧|？","nǐ|shì|xué sheng|ba|","You're a student, right?"]},{"en":"Let's go to Beijing.","before":"我们去北京","after":"。","a":"吧","wrong":["很","也","是"],"pins":{"吧":"ba","很":"hěn","也":"yě","是":"shì"},"full":["我们|去|北京|吧|。","wǒ men|qù|Běi jīng|ba|","Let's go to Beijing."]}],"order":[{"en":"Let's go.","a":"我们|走|吧|。","alt":[],"full":["我们|走|吧|。","wǒ men|zǒu|ba|","Let's go."]},{"en":"Let's go together.","a":"我们|一起|去|吧|。","alt":[],"full":["我们|一起|去|吧|。","wǒ men|yī qǐ|qù|ba|","Let's go together."]},{"en":"Have some tea.","a":"你|喝|茶|吧|。","alt":[],"full":["你|喝|茶|吧|。","nǐ|hē|chá|ba|","Have some tea."]}],"spot":[{"en":"Let's go.","right":"我们走吧。","wrong":"我们吧走。","full":["我们|走|吧|。","wǒ men|zǒu|ba|","Let's go."]},{"en":"Let's eat together.","right":"我们一起吃饭吧。","wrong":"吧我们一起吃饭。","full":["我们|一起|吃饭|吧|。","wǒ men|yī qǐ|chī fàn|ba|","Let's eat together."]}]},{"id":"yao","level":2,"title":"要: going to, want","pattern":"要 + verb","why":"要 before a verb says you are going to do something, or firmly want to. It is stronger than 想.","mark":["要"],"mistake":["我要去明天。","我明天要去。","The time goes before 要."],"ex":[["我|明天|要|去|北京|。","wǒ|míng tiān|yào|qù|Běi jīng|","I am going to Beijing tomorrow."],["我|要|喝|水|。","wǒ|yào|hē|shuǐ|","I want some water."],["你|要|买|什么|？","nǐ|yào|mǎi|shén me|","What do you want to buy?"]],"gap":[{"en":"I want to buy a book.","before":"我","after":"买一本书。","a":"要","wrong":["是","很","的"],"pins":{"要":"yào","是":"shì","很":"hěn","的":"de"},"full":["我|要|买|一|本|书|。","wǒ|yào|mǎi|yī|běn|shū|","I want to buy a book."]},{"en":"He is going to school tomorrow.","before":"他明天","after":"去学校。","a":"要","wrong":["是","很","的"],"pins":{"要":"yào","是":"shì","很":"hěn","的":"de"},"full":["他|明天|要|去|学校|。","tā|míng tiān|yào|qù|xué xiào|","He is going to school tomorrow."]},{"en":"What do you want to drink?","before":"你","after":"喝什么？","a":"要","wrong":["是","很","吗"],"pins":{"要":"yào","是":"shì","很":"hěn","吗":"ma"},"full":["你|要|喝|什么|？","nǐ|yào|hē|shén me|","What do you want to drink?"]}],"order":[{"en":"I want coffee.","a":"我|要|喝|咖啡|。","alt":[],"full":["我|要|喝|咖啡|。","wǒ|yào|hē|kā fēi|","I want coffee."]},{"en":"What do you want to buy?","a":"你|要|买|什么|？","alt":[],"full":["你|要|买|什么|？","nǐ|yào|mǎi|shén me|","What do you want to buy?"]},{"en":"She is coming tomorrow.","a":"她|明天|要|来|。","alt":["明天|她|要|来|。"],"full":["她|明天|要|来|。","tā|míng tiān|yào|lái|","She is coming tomorrow."]}],"spot":[{"en":"I am going to school tomorrow.","right":"我明天要去学校。","wrong":"我要去学校明天。","full":["我|明天|要|去|学校|。","wǒ|míng tiān|yào|qù|xué xiào|","I am going to school tomorrow."]},{"en":"What do you want to drink?","right":"你要喝什么？","wrong":"你喝要什么？","full":["你|要|喝|什么|？","nǐ|yào|hē|shén me|","What do you want to drink?"]}]},{"id":"zhengzai","level":2,"title":"正在: doing it right now","pattern":"正在 + verb","why":"正在 before a verb says the action is going on right now. 在 alone can do the same, and 呢 often ends the sentence.","mark":["正在"],"mistake":["我正在吃饭了。","我正在吃饭。","正在 means it is still going on, so it doesn't take 了."],"ex":[["我|正在|吃饭|。","wǒ|zhèng zài|chī fàn|","I am eating."],["他|正在|工作|呢|。","tā|zhèng zài|gōng zuò|ne|","He is working."],["妈妈|正在|看书|。","mā ma|zhèng zài|kàn shū|","Mum is reading."]],"gap":[{"en":"I am reading.","before":"我","after":"看书。","a":"正在","wrong":["是","很","了"],"pins":{"正在":"zhèng zài","是":"shì","很":"hěn","了":"le"},"full":["我|正在|看书|。","wǒ|zhèng zài|kàn shū|","I am reading."]},{"en":"She is working.","before":"她","after":"工作呢。","a":"正在","wrong":["是","很","了"],"pins":{"正在":"zhèng zài","是":"shì","很":"hěn","了":"le"},"full":["她|正在|工作|呢|。","tā|zhèng zài|gōng zuò|ne|","She is working."]},{"en":"They are eating.","before":"他们","after":"吃饭。","a":"正在","wrong":["是","很","的"],"pins":{"正在":"zhèng zài","是":"shì","很":"hěn","的":"de"},"full":["他们|正在|吃饭|。","tā men|zhèng zài|chī fàn|","They are eating."]}],"order":[{"en":"Dad is working.","a":"爸爸|正在|工作|。","alt":[],"full":["爸爸|正在|工作|。","bà ba|zhèng zài|gōng zuò|","Dad is working."]},{"en":"We are eating.","a":"我们|正在|吃饭|呢|。","alt":[],"full":["我们|正在|吃饭|呢|。","wǒ men|zhèng zài|chī fàn|ne|","We are eating."]},{"en":"The students are studying Chinese.","a":"学生|正在|学习|中文|。","alt":[],"full":["学生|正在|学习|中文|。","xué sheng|zhèng zài|xué xí|Zhōng wén|","The students are studying Chinese."]}],"spot":[{"en":"I am eating.","right":"我正在吃饭。","wrong":"我正在吃饭了。","full":["我|正在|吃饭|。","wǒ|zhèng zài|chī fàn|","I am eating."]},{"en":"He is working.","right":"他正在工作。","wrong":"他工作正在。","full":["他|正在|工作|。","tā|zhèng zài|gōng zuò|","He is working."]}]},{"id":"guo","level":2,"title":"过: have you ever","pattern":"Verb + 过","why":"过 after a verb says you have done it at some time in your life. To say you never have, use 没, and keep the 过.","mark":["过"],"mistake":["我不去过中国。","我没去过中国。","过 takes 没, not 不."],"ex":[["我|去|过|北京|。","wǒ|qù|guo|Běi jīng|","I have been to Beijing."],["你|吃|过|中国|菜|吗|？","nǐ|chī|guo|Zhōng guó|cài|ma|","Have you ever had Chinese food?"],["我|没|看|过|这|本|书|。","wǒ|méi|kàn|guo|zhè|běn|shū|","I haven't read this book."]],"gap":[{"en":"I have been to China.","before":"我去","after":"中国。","a":"过","wrong":["的","很","吗"],"pins":{"过":"guo","的":"de","很":"hěn","吗":"ma"},"full":["我|去|过|中国|。","wǒ|qù|guo|Zhōng guó|","I have been to China."]},{"en":"She has never eaten fish.","before":"她没吃","after":"鱼。","a":"过","wrong":["的","很","吗"],"pins":{"过":"guo","的":"de","很":"hěn","吗":"ma"},"full":["她|没|吃|过|鱼|。","tā|méi|chī|guo|yú|","She has never eaten fish."]},{"en":"I have never been to Beijing.","before":"我","after":"去过北京。","a":"没","wrong":["不","很","吗"],"pins":{"没":"méi","不":"bù","很":"hěn","吗":"ma"},"full":["我|没|去|过|北京|。","wǒ|méi|qù|guo|Běi jīng|","I have never been to Beijing."]}],"order":[{"en":"I have been to Beijing.","a":"我|去|过|北京|。","alt":[],"full":["我|去|过|北京|。","wǒ|qù|guo|Běi jīng|","I have been to Beijing."]},{"en":"Have you ever had Chinese food?","a":"你|吃|过|中国|菜|吗|？","alt":[],"full":["你|吃|过|中国|菜|吗|？","nǐ|chī|guo|Zhōng guó|cài|ma|","Have you ever had Chinese food?"]},{"en":"I haven't read this book.","a":"我|没|看|过|这|本|书|。","alt":[],"full":["我|没|看|过|这|本|书|。","wǒ|méi|kàn|guo|zhè|běn|shū|","I haven't read this book."]}],"spot":[{"en":"I have never been to China.","right":"我没去过中国。","wrong":"我不去过中国。","full":["我|没|去|过|中国|。","wǒ|méi|qù|guo|Zhōng guó|","I have never been to China."]},{"en":"Have you been to Beijing?","right":"你去过北京吗？","wrong":"你过去北京吗？","full":["你|去|过|北京|吗|？","nǐ|qù|guo|Běi jīng|ma|","Have you been to Beijing?"]}]},{"id":"bi","level":2,"title":"比: more than","pattern":"A + 比 + B + adjective","why":"比 compares two things, and the adjective alone already means \"more\". That is why 很 can't go with it.","mark":["比"],"mistake":["他比我很高。","他比我高。","No 很 in a 比 sentence."],"ex":[["他|比|我|高|。","tā|bǐ|wǒ|gāo|","He is taller than me."],["今天|比|昨天|热|。","jīn tiān|bǐ|zuó tiān|rè|","Today is hotter than yesterday."],["这|本|书|比|那|本|书|贵|。","zhè|běn|shū|bǐ|nà|běn|shū|guì|","This book is more expensive than that one."]],"gap":[{"en":"I am taller than him.","before":"我","after":"他高。","a":"比","wrong":["很","是","的"],"pins":{"比":"bǐ","很":"hěn","是":"shì","的":"de"},"full":["我|比|他|高|。","wǒ|bǐ|tā|gāo|","I am taller than him."]},{"en":"Today is colder than yesterday.","before":"今天","after":"昨天冷。","a":"比","wrong":["很","是","的"],"pins":{"比":"bǐ","很":"hěn","是":"shì","的":"de"},"full":["今天|比|昨天|冷|。","jīn tiān|bǐ|zuó tiān|lěng|","Today is colder than yesterday."]},{"en":"This one is bigger than that one.","before":"这个比那个","after":"。","a":"大","wrong":["很","是","吗"],"pins":{"大":"dà","很":"hěn","是":"shì","吗":"ma"},"full":["这|个|比|那|个|大|。","zhè|gè|bǐ|nà|gè|dà|","This one is bigger than that one."]}],"order":[{"en":"He is taller than me.","a":"他|比|我|高|。","alt":[],"full":["他|比|我|高|。","tā|bǐ|wǒ|gāo|","He is taller than me."]},{"en":"Today is hotter than yesterday.","a":"今天|比|昨天|热|。","alt":[],"full":["今天|比|昨天|热|。","jīn tiān|bǐ|zuó tiān|rè|","Today is hotter than yesterday."]},{"en":"This book is more expensive than that book.","a":"这|本|书|比|那|本|书|贵|。","alt":[],"full":["这|本|书|比|那|本|书|贵|。","zhè|běn|shū|bǐ|nà|běn|shū|guì|","This book is more expensive than that book."]}],"spot":[{"en":"He is taller than me.","right":"他比我高。","wrong":"他比我很高。","full":["他|比|我|高|。","tā|bǐ|wǒ|gāo|","He is taller than me."]},{"en":"Today is colder than yesterday.","right":"今天比昨天冷。","wrong":"今天冷比昨天。","full":["今天|比|昨天|冷|。","jīn tiān|bǐ|zuó tiān|lěng|","Today is colder than yesterday."]}]},{"id":"yiyang","level":2,"title":"跟…一样: the same as","pattern":"A + 跟 + B + 一样 + (adjective)","why":"跟…一样 says two things are the same. Add an adjective to say in what way: as tall as, as cold as.","mark":["一样","跟"],"mistake":["我跟他一样很高。","我跟他一样高。","No 很 before the adjective here."],"ex":[["我|跟|他|一样|高|。","wǒ|gēn|tā|yī yàng|gāo|","I am as tall as him."],["这|个|跟|那|个|一样|。","zhè|gè|gēn|nà|gè|yī yàng|","This is the same as that."],["今天|跟|昨天|一样|冷|。","jīn tiān|gēn|zuó tiān|yī yàng|lěng|","Today is as cold as yesterday."]],"gap":[{"en":"I am as tall as him.","before":"我","after":"他一样高。","a":"跟","wrong":["比","很","是"],"pins":{"跟":"gēn","比":"bǐ","很":"hěn","是":"shì"},"full":["我|跟|他|一样|高|。","wǒ|gēn|tā|yī yàng|gāo|","I am as tall as him."]},{"en":"This is the same as that.","before":"这个跟那个","after":"。","a":"一样","wrong":["很","比","吗"],"pins":{"一样":"yī yàng","很":"hěn","比":"bǐ","吗":"ma"},"full":["这|个|跟|那|个|一样|。","zhè|gè|gēn|nà|gè|yī yàng|","This is the same as that."]},{"en":"Today is as hot as yesterday.","before":"今天跟昨天一样","after":"。","a":"热","wrong":["很","比","吗"],"pins":{"热":"rè","很":"hěn","比":"bǐ","吗":"ma"},"full":["今天|跟|昨天|一样|热|。","jīn tiān|gēn|zuó tiān|yī yàng|rè|","Today is as hot as yesterday."]}],"order":[{"en":"I am as tall as her.","a":"我|跟|她|一样|高|。","alt":[],"full":["我|跟|她|一样|高|。","wǒ|gēn|tā|yī yàng|gāo|","I am as tall as her."]},{"en":"This book is the same as that book.","a":"这|本|书|跟|那|本|书|一样|。","alt":[],"full":["这|本|书|跟|那|本|书|一样|。","zhè|běn|shū|gēn|nà|běn|shū|yī yàng|","This book is the same as that book."]},{"en":"Today is as cold as yesterday.","a":"今天|跟|昨天|一样|冷|。","alt":[],"full":["今天|跟|昨天|一样|冷|。","jīn tiān|gēn|zuó tiān|yī yàng|lěng|","Today is as cold as yesterday."]}],"spot":[{"en":"I am as tall as him.","right":"我跟他一样高。","wrong":"我跟他一样很高。","full":["我|跟|他|一样|高|。","wǒ|gēn|tā|yī yàng|gāo|","I am as tall as him."]},{"en":"This is the same as that.","right":"这个跟那个一样。","wrong":"这个一样跟那个。","full":["这|个|跟|那|个|一样|。","zhè|gè|gēn|nà|gè|yī yàng|","This is the same as that."]}]},{"id":"de-how","level":2,"title":"得: how something is done","pattern":"Verb + 得 + how","why":"得 after a verb describes how well or how fast it is done. If there is an object, it goes first: 他中文说得很好.","mark":["得"],"mistake":["他说得中文很好。","他中文说得很好。","The object can't come straight after 得."],"ex":[["他|跑|得|很|快|。","tā|pǎo|de|hěn|kuài|","He runs fast."],["她|说|得|很|好|。","tā|shuō|de|hěn|hǎo|","She speaks well."],["我|吃|得|很|多|。","wǒ|chī|de|hěn|duō|","I eat a lot."]],"gap":[{"en":"He runs fast.","before":"他跑","after":"很快。","a":"得","wrong":["的","了","吗"],"pins":{"得":"de","的":"de","了":"le","吗":"ma"},"full":["他|跑|得|很|快|。","tā|pǎo|de|hěn|kuài|","He runs fast."]},{"en":"She writes well.","before":"她写","after":"很好。","a":"得","wrong":["的","了","吗"],"pins":{"得":"de","的":"de","了":"le","吗":"ma"},"full":["她|写|得|很|好|。","tā|xiě|de|hěn|hǎo|","She writes well."]},{"en":"You speak too fast.","before":"你说","after":"太快了。","a":"得","wrong":["的","吗","也"],"pins":{"得":"de","的":"de","吗":"ma","也":"yě"},"full":["你|说|得|太|快|了|。","nǐ|shuō|de|tài|kuài|le|","You speak too fast."]}],"order":[{"en":"He runs fast.","a":"他|跑|得|很|快|。","alt":[],"full":["他|跑|得|很|快|。","tā|pǎo|de|hěn|kuài|","He runs fast."]},{"en":"She does it very well.","a":"她|做|得|很|好|。","alt":[],"full":["她|做|得|很|好|。","tā|zuò|de|hěn|hǎo|","She does it very well."]},{"en":"I ate a lot today.","a":"我|今天|吃|得|很|多|。","alt":["今天|我|吃|得|很|多|。"],"full":["我|今天|吃|得|很|多|。","wǒ|jīn tiān|chī|de|hěn|duō|","I ate a lot today."]}],"spot":[{"en":"He speaks very well.","right":"他说得很好。","wrong":"他说很好得。","full":["他|说|得|很|好|。","tā|shuō|de|hěn|hǎo|","He speaks very well."]},{"en":"He speaks Chinese very well.","right":"他中文说得很好。","wrong":"他说得中文很好。","full":["他|中文|说|得|很|好|。","tā|Zhōng wén|shuō|de|hěn|hǎo|","He speaks Chinese very well."]}]},{"id":"gei","level":2,"title":"给: for, or to someone","pattern":"给 + person + verb","why":"给 before a person says who the action is for or to. As a verb on its own, it simply means \"give\".","mark":["给"],"mistake":["我给打电话他。","我给他打电话。","The person goes straight after 给."],"ex":[["我|给|他|打电话|。","wǒ|gěi|tā|dǎ diàn huà|","I'll phone him."],["妈妈|给|我|做饭|。","mā ma|gěi|wǒ|zuò fàn|","Mum cooks for me."],["老师|给|我们|一|本|书|。","lǎo shī|gěi|wǒ men|yī|běn|shū|","The teacher gives us a book."]],"gap":[{"en":"I'm phoning my mum.","before":"我","after":"妈妈打电话。","a":"给","wrong":["是","很","的"],"pins":{"给":"gěi","是":"shì","很":"hěn","的":"de"},"full":["我|给|妈妈|打电话|。","wǒ|gěi|mā ma|dǎ diàn huà|","I'm phoning my mum."]},{"en":"He bought me a cup of tea.","before":"他","after":"我买了一杯茶。","a":"给","wrong":["是","很","的"],"pins":{"给":"gěi","是":"shì","很":"hěn","的":"de"},"full":["他|给|我|买|了|一|杯|茶|。","tā|gěi|wǒ|mǎi|le|yī|bēi|chá|","He bought me a cup of tea."]},{"en":"Please give me a glass of water.","before":"请","after":"我一杯水。","a":"给","wrong":["是","很","的"],"pins":{"给":"gěi","是":"shì","很":"hěn","的":"de"},"full":["请|给|我|一|杯|水|。","qǐng|gěi|wǒ|yī|bēi|shuǐ|","Please give me a glass of water."]}],"order":[{"en":"I'll phone him.","a":"我|给|他|打|电话|。","alt":[],"full":["我|给|他|打|电话|。","wǒ|gěi|tā|dǎ|diàn huà|","I'll phone him."]},{"en":"Mum cooks for me.","a":"妈妈|给|我|做饭|。","alt":[],"full":["妈妈|给|我|做饭|。","mā ma|gěi|wǒ|zuò fàn|","Mum cooks for me."]},{"en":"Please give me a cup of tea.","a":"请|给|我|一|杯|茶|。","alt":[],"full":["请|给|我|一|杯|茶|。","qǐng|gěi|wǒ|yī|bēi|chá|","Please give me a cup of tea."]}],"spot":[{"en":"I'll phone him.","right":"我给他打电话。","wrong":"我给打电话他。","full":["我|给|他|打电话|。","wǒ|gěi|tā|dǎ diàn huà|","I'll phone him."]},{"en":"Mum cooks for me.","right":"妈妈给我做饭。","wrong":"妈妈做饭我给。","full":["妈妈|给|我|做饭|。","mā ma|gěi|wǒ|zuò fàn|","Mum cooks for me."]}]},{"id":"cong-dao","level":2,"title":"从…到: from and to","pattern":"从 + start + 到 + end","why":"从 marks where or when something starts, 到 where or when it ends. The whole phrase goes before the verb.","mark":["从","到"],"mistake":["我来从北京。","我从北京来。","从 and its place come before the verb."],"ex":[["从|我|家|到|学校|很|近|。","cóng|wǒ|jiā|dào|xué xiào|hěn|jìn|","It is close from my home to the school."],["我|从|北京|来|。","wǒ|cóng|Běi jīng|lái|","I come from Beijing."],["我|从|八|点|到|五|点|工作|。","wǒ|cóng|bā|diǎn|dào|wǔ|diǎn|gōng zuò|","I work from eight to five."]],"gap":[{"en":"I come from Beijing.","before":"我","after":"北京来。","a":"从","wrong":["到","很","的"],"pins":{"从":"cóng","到":"dào","很":"hěn","的":"de"},"full":["我|从|北京|来|。","wǒ|cóng|Běi jīng|lái|","I come from Beijing."]},{"en":"From eight to five.","before":"从八点","after":"五点。","a":"到","wrong":["从","很","的"],"pins":{"到":"dào","从":"cóng","很":"hěn","的":"de"},"full":["从|八|点|到|五|点|。","cóng|bā|diǎn|dào|wǔ|diǎn|","From eight to five."]},{"en":"They go from Shanghai to Beijing.","before":"他们","after":"上海到北京。","a":"从","wrong":["比","很","的"],"pins":{"从":"cóng","比":"bǐ","很":"hěn","的":"de"},"full":["他们|从|上海|到|北京|。","tā men|cóng|Shàng hǎi|dào|Běi jīng|","They go from Shanghai to Beijing."]}],"order":[{"en":"I come from China.","a":"我|从|中国|来|。","alt":[],"full":["我|从|中国|来|。","wǒ|cóng|Zhōng guó|lái|","I come from China."]},{"en":"It is close from my home to the school.","a":"从|我|家|到|学校|很|近|。","alt":[],"full":["从|我|家|到|学校|很|近|。","cóng|wǒ|jiā|dào|xué xiào|hěn|jìn|","It is close from my home to the school."]},{"en":"I work from eight to five.","a":"我|从|八|点|到|五|点|工作|。","alt":[],"full":["我|从|八|点|到|五|点|工作|。","wǒ|cóng|bā|diǎn|dào|wǔ|diǎn|gōng zuò|","I work from eight to five."]}],"spot":[{"en":"I come from Beijing.","right":"我从北京来。","wrong":"我来从北京。","full":["我|从|北京|来|。","wǒ|cóng|Běi jīng|lái|","I come from Beijing."]},{"en":"It is far from here to there.","right":"从这儿到那儿很远。","wrong":"到这儿从那儿很远。","full":["从|这儿|到|那儿|很|远|。","cóng|zhèr|dào|nà r|hěn|yuǎn|","It is far from here to there."]}]},{"id":"li","level":2,"title":"离: how far from","pattern":"A + 离 + B + 远 or 近","why":"离 says how far apart two places are, or two times. English says \"from\" here, but 从 won't do: 从 is for moving, 离 for distance.","mark":["离"],"mistake":["我家从学校很近。","我家离学校很近。","For distance, use 离."],"ex":[["我|家|离|学校|很|近|。","wǒ|jiā|lí|xué xiào|hěn|jìn|","My home is close to the school."],["北京|离|上海|很|远|。","Běi jīng|lí|Shàng hǎi|hěn|yuǎn|","Beijing is far from Shanghai."],["这儿|离|医院|不|远|。","zhèr|lí|yī yuàn|bù|yuǎn|","It isn't far from here to the hospital."]],"gap":[{"en":"My home is close to the school.","before":"我家","after":"学校很近。","a":"离","wrong":["从","比","和"],"pins":{"离":"lí","从":"cóng","比":"bǐ","和":"hé"},"full":["我|家|离|学校|很|近|。","wǒ|jiā|lí|xué xiào|hěn|jìn|","My home is close to the school."]},{"en":"It is far from here to Beijing.","before":"这儿","after":"北京很远。","a":"离","wrong":["从","在","是"],"pins":{"离":"lí","从":"cóng","在":"zài","是":"shì"},"full":["这儿|离|北京|很|远|。","zhèr|lí|Běi jīng|hěn|yuǎn|","It is far from here to Beijing."]},{"en":"The school isn't far from my home.","before":"学校离我家不","after":"。","a":"远","wrong":["离","很","吗"],"pins":{"远":"yuǎn","离":"lí","很":"hěn","吗":"ma"},"full":["学校|离|我|家|不|远|。","xué xiào|lí|wǒ|jiā|bù|yuǎn|","The school isn't far from my home."]}],"order":[{"en":"My home is close to the school.","a":"我|家|离|学校|很|近|。","alt":[],"full":["我|家|离|学校|很|近|。","wǒ|jiā|lí|xué xiào|hěn|jìn|","My home is close to the school."]},{"en":"Beijing is far from Shanghai.","a":"北京|离|上海|很|远|。","alt":["上海|离|北京|很|远|。"],"full":["北京|离|上海|很|远|。","Běi jīng|lí|Shàng hǎi|hěn|yuǎn|","Beijing is far from Shanghai."]},{"en":"The hospital isn't far from here.","a":"医院|离|这儿|不|远|。","alt":[],"full":["医院|离|这儿|不|远|。","yī yuàn|lí|zhèr|bù|yuǎn|","The hospital isn't far from here."]}],"spot":[{"en":"My home is close to the school.","right":"我家离学校很近。","wrong":"我家从学校很近。","full":["我|家|离|学校|很|近|。","wǒ|jiā|lí|xué xiào|hěn|jìn|","My home is close to the school."]},{"en":"It is far from here to Beijing.","right":"这儿离北京很远。","wrong":"这儿很远离北京。","full":["这儿|离|北京|很|远|。","zhèr|lí|Běi jīng|hěn|yuǎn|","It is far from here to Beijing."]}]},{"id":"yinwei","level":2,"title":"因为…所以: because, so","pattern":"因为 + reason，所以 + result","why":"Chinese often marks both halves: the reason with 因为, the result with 所以. In English you would use only one of them.","mark":["因为","所以"],"mistake":["所以下雨，因为我不去。","因为下雨，所以我不去。","The reason comes first, with 因为."],"ex":[["因为|下雨|，|所以|我|不|去|。","yīn wèi|xià yǔ||suǒ yǐ|wǒ|bù|qù|","Because it's raining, I'm not going."],["因为|他|很|忙|，|所以|没|来|。","yīn wèi|tā|hěn|máng||suǒ yǐ|méi|lái|","He is busy, so he didn't come."],["因为|我|喜欢|中国|，|所以|学|中文|。","yīn wèi|wǒ|xǐ huan|Zhōng guó||suǒ yǐ|xué|Zhōng wén|","I like China, so I study Chinese."]],"gap":[{"en":"Because it's cold today, I'm not going.","before":"","after":"今天很冷，所以我不去。","a":"因为","wrong":["但是","虽然","如果"],"pins":{"因为":"yīn wèi","但是":"dàn shì","虽然":"suī rán","如果":"rú guǒ"},"full":["因为|今天|很|冷|，|所以|我|不|去|。","yīn wèi|jīn tiān|hěn|lěng||suǒ yǐ|wǒ|bù|qù|","Because it's cold today, I'm not going."]},{"en":"He is ill, so he didn't come to school.","before":"因为他病了，","after":"没来学校。","a":"所以","wrong":["但是","虽然","因为"],"pins":{"所以":"suǒ yǐ","但是":"dàn shì","虽然":"suī rán","因为":"yīn wèi"},"full":["因为|他|病|了|，|所以|没|来|学校|。","yīn wèi|tā|bìng|le||suǒ yǐ|méi|lái|xué xiào|","He is ill, so he didn't come to school."]},{"en":"It's too expensive, so I'm not buying it.","before":"因为太贵了，","after":"我不买。","a":"所以","wrong":["但是","如果","也"],"pins":{"所以":"suǒ yǐ","但是":"dàn shì","如果":"rú guǒ","也":"yě"},"full":["因为|太|贵|了|，|所以|我|不|买|。","yīn wèi|tài|guì|le||suǒ yǐ|wǒ|bù|mǎi|","It's too expensive, so I'm not buying it."]}],"order":[{"en":"Because it's raining, I'm not going.","a":"因为|下雨|，|所以|我|不|去|。","alt":[],"full":["因为|下雨|，|所以|我|不|去|。","yīn wèi|xià yǔ||suǒ yǐ|wǒ|bù|qù|","Because it's raining, I'm not going."]},{"en":"He is too busy, so he didn't come.","a":"因为|太|忙|，|所以|他|没|来|。","alt":[],"full":["因为|太|忙|，|所以|他|没|来|。","yīn wèi|tài|máng||suǒ yǐ|tā|méi|lái|","He is too busy, so he didn't come."]},{"en":"Because it's cold, I'm not going.","a":"因为|很|冷|，|所以|我|不|去|。","alt":[],"full":["因为|很|冷|，|所以|我|不|去|。","yīn wèi|hěn|lěng||suǒ yǐ|wǒ|bù|qù|","Because it's cold, I'm not going."]}],"spot":[{"en":"Because it's raining, I'm not going.","right":"因为下雨，所以我不去。","wrong":"所以下雨，因为我不去。","full":["因为|下雨|，|所以|我|不|去|。","yīn wèi|xià yǔ||suǒ yǐ|wǒ|bù|qù|","Because it's raining, I'm not going."]},{"en":"I was busy, so I didn't come.","right":"因为很忙，所以我没来。","wrong":"因为很忙，但是我没来。","full":["因为|很|忙|，|所以|我|没|来|。","yīn wèi|hěn|máng||suǒ yǐ|wǒ|méi|lái|","I was busy, so I didn't come."]}]},{"id":"suiran","level":2,"title":"虽然…但是: although, but","pattern":"虽然 + one thing，但是 + the other","why":"Saying \"although … but\" is wrong in English, and right in Chinese. Both halves are normally marked.","mark":["虽然","但是"],"mistake":["虽然很贵，所以我买了。","虽然很贵，但是我买了。","虽然 pairs with 但是, not 所以."],"ex":[["虽然|很|贵|，|但是|我|想|买|。","suī rán|hěn|guì||dàn shì|wǒ|xiǎng|mǎi|","It's expensive, but I want to buy it."],["虽然|下雨|，|但是|他|来|了|。","suī rán|xià yǔ||dàn shì|tā|lái|le|","Although it was raining, he came."],["虽然|很|累|，|但是|我|很|高兴|。","suī rán|hěn|lèi||dàn shì|wǒ|hěn|gāo xìng|","I'm tired, but I'm happy."]],"gap":[{"en":"It's expensive, but I want to buy it.","before":"","after":"很贵，但是我想买。","a":"虽然","wrong":["因为","如果","所以"],"pins":{"虽然":"suī rán","因为":"yīn wèi","如果":"rú guǒ","所以":"suǒ yǐ"},"full":["虽然|很|贵|，|但是|我|想|买|。","suī rán|hěn|guì||dàn shì|wǒ|xiǎng|mǎi|","It's expensive, but I want to buy it."]},{"en":"It's cold, but I'm going.","before":"虽然很冷，","after":"我要去。","a":"但是","wrong":["所以","因为","如果"],"pins":{"但是":"dàn shì","所以":"suǒ yǐ","因为":"yīn wèi","如果":"rú guǒ"},"full":["虽然|很|冷|，|但是|我|要|去|。","suī rán|hěn|lěng||dàn shì|wǒ|yào|qù|","It's cold, but I'm going."]},{"en":"He is busy, but he came.","before":"虽然他很忙，","after":"他来了。","a":"但是","wrong":["所以","因为","也"],"pins":{"但是":"dàn shì","所以":"suǒ yǐ","因为":"yīn wèi","也":"yě"},"full":["虽然|他|很|忙|，|但是|他|来|了|。","suī rán|tā|hěn|máng||dàn shì|tā|lái|le|","He is busy, but he came."]}],"order":[{"en":"I'm tired, but I'm happy.","a":"虽然|很|累|，|但是|我|很|高兴|。","alt":[],"full":["虽然|很|累|，|但是|我|很|高兴|。","suī rán|hěn|lèi||dàn shì|wǒ|hěn|gāo xìng|","I'm tired, but I'm happy."]},{"en":"Although it was raining, he came.","a":"虽然|下雨|，|但是|他|来|了|。","alt":[],"full":["虽然|下雨|，|但是|他|来|了|。","suī rán|xià yǔ||dàn shì|tā|lái|le|","Although it was raining, he came."]},{"en":"It's expensive, but I want to buy it.","a":"虽然|很|贵|，|但是|我|想|买|。","alt":[],"full":["虽然|很|贵|，|但是|我|想|买|。","suī rán|hěn|guì||dàn shì|wǒ|xiǎng|mǎi|","It's expensive, but I want to buy it."]}],"spot":[{"en":"It's expensive, but I want to buy it.","right":"虽然很贵，但是我想买。","wrong":"虽然很贵，所以我想买。","full":["虽然|很|贵|，|但是|我|想|买|。","suī rán|hěn|guì||dàn shì|wǒ|xiǎng|mǎi|","It's expensive, but I want to buy it."]},{"en":"Although it's raining, I'm going.","right":"虽然下雨，但是我去。","wrong":"但是下雨，虽然我去。","full":["虽然|下雨|，|但是|我|去|。","suī rán|xià yǔ||dàn shì|wǒ|qù|","Although it's raining, I'm going."]}]},{"id":"haishi","level":2,"title":"还是 and 或者: or","pattern":"Question: A 还是 B？ · Statement: A 或者 B","why":"Chinese has two words for \"or\". 还是 asks which one. 或者 says either one will do.","mark":["还是","或者"],"mistake":["你喝茶或者咖啡？","你喝茶还是咖啡？","When you are asking which, use 还是."],"ex":[["你|喝茶|还是|咖啡|？","nǐ|hē chá|hái shi|kā fēi|","Are you having tea or coffee?"],["你|今天|去|还是|明天|去|？","nǐ|jīn tiān|qù|hái shi|míng tiān|qù|","Are you going today or tomorrow?"],["茶|或者|咖啡|都|可以|。","chá|huò zhě|kā fēi|dōu|kě yǐ|","Tea or coffee, either is fine."]],"gap":[{"en":"Are you having tea or coffee?","before":"你喝茶","after":"喝咖啡？","a":"还是","wrong":["或者","和","也"],"pins":{"还是":"hái shi","或者":"huò zhě","和":"hé","也":"yě"},"full":["你|喝茶|还是|喝|咖啡|？","nǐ|hē chá|hái shi|hē|kā fēi|","Are you having tea or coffee?"]},{"en":"Is he a teacher or a student?","before":"他是老师","after":"学生？","a":"还是","wrong":["或者","和","也"],"pins":{"还是":"hái shi","或者":"huò zhě","和":"hé","也":"yě"},"full":["他|是|老师|还是|学生|？","tā|shì|lǎo shī|hái shi|xué sheng|","Is he a teacher or a student?"]},{"en":"Today or tomorrow, either is fine.","before":"今天","after":"明天都可以。","a":"或者","wrong":["还是","也","吗"],"pins":{"或者":"huò zhě","还是":"hái shi","也":"yě","吗":"ma"},"full":["今天|或者|明天|都|可以|。","jīn tiān|huò zhě|míng tiān|dōu|kě yǐ|","Today or tomorrow, either is fine."]}],"order":[{"en":"Are you having tea or coffee?","a":"你|喝|茶|还是|咖啡|？","alt":["你|喝|咖啡|还是|茶|？"],"full":["你|喝|茶|还是|咖啡|？","nǐ|hē|chá|hái shi|kā fēi|","Are you having tea or coffee?"]},{"en":"Is he a teacher or a student?","a":"他|是|老师|还是|学生|？","alt":["他|是|学生|还是|老师|？"],"full":["他|是|老师|还是|学生|？","tā|shì|lǎo shī|hái shi|xué sheng|","Is he a teacher or a student?"]},{"en":"Are you going today or tomorrow?","a":"你|今天|去|还是|明天|去|？","alt":["你|明天|去|还是|今天|去|？"],"full":["你|今天|去|还是|明天|去|？","nǐ|jīn tiān|qù|hái shi|míng tiān|qù|","Are you going today or tomorrow?"]}],"spot":[{"en":"Are you having tea or coffee?","right":"你喝茶还是咖啡？","wrong":"你喝茶或者咖啡？","full":["你|喝茶|还是|咖啡|？","nǐ|hē chá|hái shi|kā fēi|","Are you having tea or coffee?"]},{"en":"Are you going or not?","right":"你去还是不去？","wrong":"你去或者不去？","full":["你|去|还是|不|去|？","nǐ|qù|hái shi|bù|qù|","Are you going or not?"]}]},{"id":"yijing","level":2,"title":"已经…了: already","pattern":"已经 + verb + 了","why":"已经 means \"already\", and the sentence normally ends in 了, to say that this is now how things stand.","mark":["已经","了"],"mistake":["我已经吃。","我已经吃了。","已经 needs its 了."],"ex":[["我|已经|吃饭|了|。","wǒ|yǐ jīng|chī fàn|le|","I have already eaten."],["他|已经|回家|了|。","tā|yǐ jīng|huí jiā|le|","He has already gone home."],["现在|已经|八|点|了|。","xiàn zài|yǐ jīng|bā|diǎn|le|","It is already eight o'clock."]],"gap":[{"en":"I have already eaten.","before":"我","after":"吃饭了。","a":"已经","wrong":["正在","很","也"],"pins":{"已经":"yǐ jīng","正在":"zhèng zài","很":"hěn","也":"yě"},"full":["我|已经|吃饭|了|。","wǒ|yǐ jīng|chī fàn|le|","I have already eaten."]},{"en":"He has already gone home.","before":"他已经回家","after":"。","a":"了","wrong":["的","吗","很"],"pins":{"了":"le","的":"de","吗":"ma","很":"hěn"},"full":["他|已经|回家|了|。","tā|yǐ jīng|huí jiā|le|","He has already gone home."]},{"en":"It is already nine o'clock.","before":"现在","after":"九点了。","a":"已经","wrong":["很","是","也"],"pins":{"已经":"yǐ jīng","很":"hěn","是":"shì","也":"yě"},"full":["现在|已经|九|点|了|。","xiàn zài|yǐ jīng|jiǔ|diǎn|le|","It is already nine o'clock."]}],"order":[{"en":"I have already eaten.","a":"我|已经|吃饭|了|。","alt":[],"full":["我|已经|吃饭|了|。","wǒ|yǐ jīng|chī fàn|le|","I have already eaten."]},{"en":"He has already gone home.","a":"他|已经|回家|了|。","alt":[],"full":["他|已经|回家|了|。","tā|yǐ jīng|huí jiā|le|","He has already gone home."]},{"en":"It is already ten o'clock.","a":"现在|已经|十|点|了|。","alt":[],"full":["现在|已经|十|点|了|。","xiàn zài|yǐ jīng|shí|diǎn|le|","It is already ten o'clock."]}],"spot":[{"en":"He has already come.","right":"他已经来了。","wrong":"他来已经了。","full":["他|已经|来|了|。","tā|yǐ jīng|lái|le|","He has already come."]},{"en":"I have already eaten.","right":"我已经吃了。","wrong":"我已经吃。","full":["我|已经|吃|了|。","wǒ|yǐ jīng|chī|le|","I have already eaten."]}]},{"id":"youdian","level":2,"title":"有点儿 and 一点儿: a bit","pattern":"有点儿 + adjective · adjective + 一点儿","why":"有点儿 goes before the adjective, and usually sounds like a complaint: a bit too cold. 一点儿 goes after it, and compares or asks for a change: a bit cheaper.","mark":["有点儿","一点儿"],"mistake":["我一点儿累。","我有点儿累。","Before an adjective, use 有点儿."],"ex":[["今天|有点儿|冷|。","jīn tiān|yǒu diǎn r|lěng|","It's a bit cold today."],["这|个|有点儿|贵|。","zhè|gè|yǒu diǎn r|guì|","This is a bit expensive."],["便宜|一点儿|吧|。","pián yi|yī diǎn r|ba|","Make it a bit cheaper."]],"gap":[{"en":"I'm a bit tired.","before":"我","after":"累。","a":"有点儿","wrong":["一点儿","是","的"],"pins":{"有点儿":"yǒu diǎn r","一点儿":"yī diǎn r","是":"shì","的":"de"},"full":["我|有点儿|累|。","wǒ|yǒu diǎn r|lèi|","I'm a bit tired."]},{"en":"It's a bit hot today.","before":"今天","after":"热。","a":"有点儿","wrong":["一点儿","是","的"],"pins":{"有点儿":"yǒu diǎn r","一点儿":"yī diǎn r","是":"shì","的":"de"},"full":["今天|有点儿|热|。","jīn tiān|yǒu diǎn r|rè|","It's a bit hot today."]},{"en":"Please be a bit quicker.","before":"请快","after":"。","a":"一点儿","wrong":["有点儿","的","吗"],"pins":{"一点儿":"yī diǎn r","有点儿":"yǒu diǎn r","的":"de","吗":"ma"},"full":["请|快|一点儿|。","qǐng|kuài|yī diǎn r|","Please be a bit quicker."]}],"order":[{"en":"It's a bit cold today.","a":"今天|有点儿|冷|。","alt":[],"full":["今天|有点儿|冷|。","jīn tiān|yǒu diǎn r|lěng|","It's a bit cold today."]},{"en":"This book is a bit expensive.","a":"这|本|书|有点儿|贵|。","alt":[],"full":["这|本|书|有点儿|贵|。","zhè|běn|shū|yǒu diǎn r|guì|","This book is a bit expensive."]},{"en":"I'm a bit tired today.","a":"我|今天|有点儿|累|。","alt":["今天|我|有点儿|累|。"],"full":["我|今天|有点儿|累|。","wǒ|jīn tiān|yǒu diǎn r|lèi|","I'm a bit tired today."]}],"spot":[{"en":"I'm a bit tired.","right":"我有点儿累。","wrong":"我一点儿累。","full":["我|有点儿|累|。","wǒ|yǒu diǎn r|lèi|","I'm a bit tired."]},{"en":"This is a bit expensive.","right":"这个有点儿贵。","wrong":"这个贵有点儿。","full":["这|个|有点儿|贵|。","zhè|gè|yǒu diǎn r|guì|","This is a bit expensive."]}]},{"id":"xian","level":2,"title":"先…然后: first, then","pattern":"先 + first thing，然后 + next thing","why":"先 goes before the first verb, after the subject. 然后 starts the second half of the sentence.","mark":["先","然后"],"mistake":["先我吃饭，然后看书。","我先吃饭，然后看书。","先 follows the subject."],"ex":[["我|先|吃饭|，|然后|看书|。","wǒ|xiān|chī fàn||rán hòu|kàn shū|","First I'll eat, then I'll read."],["你|先|去|，|然后|我|去|。","nǐ|xiān|qù||rán hòu|wǒ|qù|","You go first, then I'll go."],["我们|先|去|北京|，|然后|去|上海|。","wǒ men|xiān|qù|Běi jīng||rán hòu|qù|Shàng hǎi|","We'll go to Beijing first, then Shanghai."]],"gap":[{"en":"First I'll eat, then go to school.","before":"我","after":"吃饭，然后去学校。","a":"先","wrong":["也","很","都"],"pins":{"先":"xiān","也":"yě","很":"hěn","都":"dōu"},"full":["我|先|吃饭|，|然后|去|学校|。","wǒ|xiān|chī fàn||rán hòu|qù|xué xiào|","First I'll eat, then go to school."]},{"en":"First I'll work, then read.","before":"我先工作，","after":"看书。","a":"然后","wrong":["先","也","很"],"pins":{"然后":"rán hòu","先":"xiān","也":"yě","很":"hěn"},"full":["我|先|工作|，|然后|看书|。","wǒ|xiān|gōng zuò||rán hòu|kàn shū|","First I'll work, then read."]},{"en":"Have your tea first, then we'll leave.","before":"你","after":"喝茶，然后我们走。","a":"先","wrong":["也","很","的"],"pins":{"先":"xiān","也":"yě","很":"hěn","的":"de"},"full":["你|先|喝茶|，|然后|我们|走|。","nǐ|xiān|hē chá||rán hòu|wǒ men|zǒu|","Have your tea first, then we'll leave."]}],"order":[{"en":"First I'll eat, then I'll read.","a":"我|先|吃饭|，|然后|看书|。","alt":[],"full":["我|先|吃饭|，|然后|看书|。","wǒ|xiān|chī fàn||rán hòu|kàn shū|","First I'll eat, then I'll read."]},{"en":"We'll go to Beijing first, then Shanghai.","a":"我们|先|去|北京|，|然后|去|上海|。","alt":[],"full":["我们|先|去|北京|，|然后|去|上海|。","wǒ men|xiān|qù|Běi jīng||rán hòu|qù|Shàng hǎi|","We'll go to Beijing first, then Shanghai."]},{"en":"You go first, then I'll go.","a":"你|先|去|，|然后|我|去|。","alt":[],"full":["你|先|去|，|然后|我|去|。","nǐ|xiān|qù||rán hòu|wǒ|qù|","You go first, then I'll go."]}],"spot":[{"en":"First I'll eat, then I'll read.","right":"我先吃饭，然后看书。","wrong":"先我吃饭，然后看书。","full":["我|先|吃饭|，|然后|看书|。","wǒ|xiān|chī fàn||rán hòu|kàn shū|","First I'll eat, then I'll read."]},{"en":"You go first, then I'll go.","right":"你先去，然后我去。","wrong":"你然后去，先我去。","full":["你|先|去|，|然后|我|去|。","nǐ|xiān|qù||rán hòu|wǒ|qù|","You go first, then I'll go."]}]},{"id":"ba3","level":3,"title":"把: doing something to a thing","pattern":"Subject + 把 + thing + verb + result","why":"把 brings the thing to the front, to say what happens to it. The verb can't stand alone at the end: it needs a result, a place, or 了.","mark":["把"],"mistake":["我把书放。","我把书放在桌子上。","After 把, the verb must say what became of the thing."],"ex":[["我|把|书|放|在|桌子|上|。","wǒ|bǎ|shū|fàng|zài|zhuō zi|shang|","I put the book on the table."],["他|把|茶|喝|了|。","tā|bǎ|chá|hē|le|","He drank the tea."],["请|把|门|关上|。","qǐng|bǎ|mén|guān shàng|","Please close the door."]],"gap":[{"en":"I put the book on the table.","before":"我","after":"书放在桌子上。","a":"把","wrong":["被","是","很"],"pins":{"把":"bǎ","被":"bèi","是":"shì","很":"hěn"},"full":["我|把|书|放|在|桌子|上|。","wǒ|bǎ|shū|fàng|zài|zhuō zi|shang|","I put the book on the table."]},{"en":"Please close the door.","before":"请","after":"门关上。","a":"把","wrong":["被","是","很"],"pins":{"把":"bǎ","被":"bèi","是":"shì","很":"hěn"},"full":["请|把|门|关上|。","qǐng|bǎ|mén|guān shàng|","Please close the door."]},{"en":"He drank the water.","before":"他","after":"水喝了。","a":"把","wrong":["被","是","很"],"pins":{"把":"bǎ","被":"bèi","是":"shì","很":"hěn"},"full":["他|把|水|喝|了|。","tā|bǎ|shuǐ|hē|le|","He drank the water."]}],"order":[{"en":"I put the book on the table.","a":"我|把|书|放|在|桌子|上|。","alt":[],"full":["我|把|书|放|在|桌子|上|。","wǒ|bǎ|shū|fàng|zài|zhuō zi|shang|","I put the book on the table."]},{"en":"Please close the door.","a":"请|把|门|关上|。","alt":[],"full":["请|把|门|关上|。","qǐng|bǎ|mén|guān shàng|","Please close the door."]},{"en":"She drank the tea.","a":"她|把|茶|喝|了|。","alt":[],"full":["她|把|茶|喝|了|。","tā|bǎ|chá|hē|le|","She drank the tea."]}],"spot":[{"en":"I put the book on the table.","right":"我把书放在桌子上了。","wrong":"我把书放。","full":["我|把|书|放|在|桌子|上|了|。","wǒ|bǎ|shū|fàng|zài|zhuō zi|shang|le|","I put the book on the table."]},{"en":"He drank the water.","right":"他把水喝了。","wrong":"他喝把水了。","full":["他|把|水|喝|了|。","tā|bǎ|shuǐ|hē|le|","He drank the water."]}]},{"id":"bei","level":3,"title":"被: having something done to it","pattern":"Thing + 被 + doer + verb + result","why":"被 puts what the action happened to first, then who did it. It is the reverse of 把, and it often tells of something unwelcome.","mark":["被"],"mistake":["苹果被他吃。","苹果被他吃了。","被, like 把, needs a result: here, 了."],"ex":[["我|的|书|被|他|拿走|了|。","wǒ|de|shū|bèi|tā|ná zǒu|le|","My book was taken by him."],["苹果|被|吃|了|。","píng guǒ|bèi|chī|le|","The apple got eaten."],["他|被|老师|看见|了|。","tā|bèi|lǎo shī|kàn jiàn|le|","He was seen by the teacher."]],"gap":[{"en":"My phone was taken by him.","before":"我的手机","after":"他拿走了。","a":"被","wrong":["把","是","很"],"pins":{"被":"bèi","把":"bǎ","是":"shì","很":"hěn"},"full":["我|的|手机|被|他|拿走|了|。","wǒ|de|shǒu jī|bèi|tā|ná zǒu|le|","My phone was taken by him."]},{"en":"The apple got eaten.","before":"苹果","after":"吃了。","a":"被","wrong":["把","是","很"],"pins":{"被":"bèi","把":"bǎ","是":"shì","很":"hěn"},"full":["苹果|被|吃|了|。","píng guǒ|bèi|chī|le|","The apple got eaten."]},{"en":"He was seen by the teacher.","before":"他被老师看见","after":"。","a":"了","wrong":["的","吗","很"],"pins":{"了":"le","的":"de","吗":"ma","很":"hěn"},"full":["他|被|老师|看见|了|。","tā|bèi|lǎo shī|kàn jiàn|le|","He was seen by the teacher."]}],"order":[{"en":"My book was taken by him.","a":"我|的|书|被|他|拿走|了|。","alt":[],"full":["我|的|书|被|他|拿走|了|。","wǒ|de|shū|bèi|tā|ná zǒu|le|","My book was taken by him."]},{"en":"The apple was eaten by him.","a":"苹果|被|他|吃|了|。","alt":[],"full":["苹果|被|他|吃|了|。","píng guǒ|bèi|tā|chī|le|","The apple was eaten by him."]},{"en":"He was seen by the teacher.","a":"他|被|老师|看见|了|。","alt":[],"full":["他|被|老师|看见|了|。","tā|bèi|lǎo shī|kàn jiàn|le|","He was seen by the teacher."]}],"spot":[{"en":"The apple was eaten by him.","right":"苹果被他吃了。","wrong":"苹果被他吃。","full":["苹果|被|他|吃|了|。","píng guǒ|bèi|tā|chī|le|","The apple was eaten by him."]},{"en":"My book was taken by him.","right":"我的书被他拿走了。","wrong":"他被我的书拿走了。","full":["我|的|书|被|他|拿走|了|。","wǒ|de|shū|bèi|tā|ná zǒu|le|","My book was taken by him."]}]},{"id":"zhe","level":3,"title":"着: staying that way","pattern":"Verb + 着","why":"着 after a verb says the state carries on: the door stays open. Followed by another verb, it says how the second action is done: sitting and reading.","mark":["着"],"mistake":["门开着了。","门开着。","着 says it is still that way, so it doesn't take 了."],"ex":[["门|开|着|。","mén|kāi|zhe|","The door is open."],["他|穿|着|红色|的|衣服|。","tā|chuān|zhe|hóng sè|de|yī fu|","He is wearing red clothes."],["她|坐|着|看书|。","tā|zuò|zhe|kàn shū|","She sits and reads."]],"gap":[{"en":"The door is open.","before":"门开","after":"。","a":"着","wrong":["的","吗","很"],"pins":{"着":"zhe","的":"de","吗":"ma","很":"hěn"},"full":["门|开|着|。","mén|kāi|zhe|","The door is open."]},{"en":"He is wearing red clothes.","before":"他穿","after":"红色的衣服。","a":"着","wrong":["的","吗","很"],"pins":{"着":"zhe","的":"de","吗":"ma","很":"hěn"},"full":["他|穿|着|红色|的|衣服|。","tā|chuān|zhe|hóng sè|de|yī fu|","He is wearing red clothes."]},{"en":"She sits and reads.","before":"她坐","after":"看书。","a":"着","wrong":["的","吗","很"],"pins":{"着":"zhe","的":"de","吗":"ma","很":"hěn"},"full":["她|坐|着|看书|。","tā|zuò|zhe|kàn shū|","She sits and reads."]}],"order":[{"en":"The door is open.","a":"门|开|着|。","alt":[],"full":["门|开|着|。","mén|kāi|zhe|","The door is open."]},{"en":"I sit and drink tea.","a":"我|坐|着|喝|茶|。","alt":[],"full":["我|坐|着|喝|茶|。","wǒ|zuò|zhe|hē|chá|","I sit and drink tea."]},{"en":"She is wearing red clothes.","a":"她|穿|着|红色|的|衣服|。","alt":[],"full":["她|穿|着|红色|的|衣服|。","tā|chuān|zhe|hóng sè|de|yī fu|","She is wearing red clothes."]}],"spot":[{"en":"The door is open.","right":"门开着。","wrong":"门开着了。","full":["门|开|着|。","mén|kāi|zhe|","The door is open."]},{"en":"He sits and reads.","right":"他坐着看书。","wrong":"他看书坐着。","full":["他|坐|着|看书|。","tā|zuò|zhe|kàn shū|","He sits and reads."]}]},{"id":"di","level":3,"title":"地: how, before a verb","pattern":"Adjective + 地 + verb","why":"地 turns a description into an adverb: 慢慢地 is \"slowly\". All three de sound alike: 的 goes before a noun, 地 before a verb, and 得 after a verb.","mark":["地"],"mistake":["她走慢慢地。","她慢慢地走。","地 and its description come before the verb."],"ex":[["他|高兴|地|说|。","tā|gāo xìng|de|shuō|","He said happily."],["她|慢慢|地|走|。","tā|màn màn|de|zǒu|","She walks slowly."],["我们|认真|地|学习|。","wǒ men|rèn zhēn|de|xué xí|","We study seriously."]],"gap":[{"en":"He laughed happily.","before":"他高兴","after":"笑了。","a":"地","wrong":["吗","很","也"],"pins":{"地":"de","吗":"ma","很":"hěn","也":"yě"},"full":["他|高兴|地|笑|了|。","tā|gāo xìng|de|xiào|le|","He laughed happily."]},{"en":"She walks slowly.","before":"她慢慢","after":"走。","a":"地","wrong":["吗","很","也"],"pins":{"地":"de","吗":"ma","很":"hěn","也":"yě"},"full":["她|慢慢|地|走|。","tā|màn màn|de|zǒu|","She walks slowly."]},{"en":"You should study seriously.","before":"你要认真","after":"学习。","a":"地","wrong":["吗","很","也"],"pins":{"地":"de","吗":"ma","很":"hěn","也":"yě"},"full":["你|要|认真|地|学习|。","nǐ|yào|rèn zhēn|de|xué xí|","You should study seriously."]}],"order":[{"en":"He said happily.","a":"他|高兴|地|说|。","alt":[],"full":["他|高兴|地|说|。","tā|gāo xìng|de|shuō|","He said happily."]},{"en":"She walks slowly.","a":"她|慢慢|地|走|。","alt":[],"full":["她|慢慢|地|走|。","tā|màn màn|de|zǒu|","She walks slowly."]},{"en":"We study Chinese seriously.","a":"我们|认真|地|学习|中文|。","alt":[],"full":["我们|认真|地|学习|中文|。","wǒ men|rèn zhēn|de|xué xí|Zhōng wén|","We study Chinese seriously."]}],"spot":[{"en":"She walks slowly.","right":"她慢慢地走。","wrong":"她走慢慢地。","full":["她|慢慢|地|走|。","tā|màn màn|de|zǒu|","She walks slowly."]},{"en":"He laughed happily.","right":"他高兴地笑了。","wrong":"他笑高兴地了。","full":["他|高兴|地|笑|了|。","tā|gāo xìng|de|xiào|le|","He laughed happily."]}]},{"id":"ruguo","level":3,"title":"如果…就: if, then","pattern":"如果 + condition，subject + 就 + result","why":"如果 sets the condition. 就 goes in the second half, after the subject and right before the verb.","mark":["如果","就"],"mistake":["如果你去，就我去。","如果你去，我就去。","就 follows the subject."],"ex":[["如果|下雨|，|我|就|不|去|。","rú guǒ|xià yǔ||wǒ|jiù|bù|qù|","If it rains, I won't go."],["如果|你|想|去|，|我们|就|去|。","rú guǒ|nǐ|xiǎng|qù||wǒ men|jiù|qù|","If you want to go, we'll go."],["如果|有|时间|，|我|就|看书|。","rú guǒ|yǒu|shí jiān||wǒ|jiù|kàn shū|","If I have time, I'll read."]],"gap":[{"en":"If it rains tomorrow, I won't go.","before":"","after":"明天下雨，我就不去。","a":"如果","wrong":["因为","虽然","所以"],"pins":{"如果":"rú guǒ","因为":"yīn wèi","虽然":"suī rán","所以":"suǒ yǐ"},"full":["如果|明天|下雨|，|我|就|不|去|。","rú guǒ|míng tiān|xià yǔ||wǒ|jiù|bù|qù|","If it rains tomorrow, I won't go."]},{"en":"If you come, I'll be happy.","before":"如果你来，我","after":"很高兴。","a":"就","wrong":["所以","的","吗"],"pins":{"就":"jiù","所以":"suǒ yǐ","的":"de","吗":"ma"},"full":["如果|你|来|，|我|就|很|高兴|。","rú guǒ|nǐ|lái||wǒ|jiù|hěn|gāo xìng|","If you come, I'll be happy."]},{"en":"If we have time, we'll go to Beijing.","before":"如果有时间，我们","after":"去北京。","a":"就","wrong":["的","吗","很"],"pins":{"就":"jiù","的":"de","吗":"ma","很":"hěn"},"full":["如果|有|时间|，|我们|就|去|北京|。","rú guǒ|yǒu|shí jiān||wǒ men|jiù|qù|Běi jīng|","If we have time, we'll go to Beijing."]}],"order":[{"en":"If it rains, I won't go.","a":"如果|下雨|，|我|就|不|去|。","alt":[],"full":["如果|下雨|，|我|就|不|去|。","rú guǒ|xià yǔ||wǒ|jiù|bù|qù|","If it rains, I won't go."]},{"en":"If I have time, I'll read.","a":"如果|有|时间|，|我|就|看书|。","alt":[],"full":["如果|有|时间|，|我|就|看书|。","rú guǒ|yǒu|shí jiān||wǒ|jiù|kàn shū|","If I have time, I'll read."]},{"en":"If you want to go, we'll go.","a":"如果|你|想|去|，|我们|就|去|。","alt":[],"full":["如果|你|想|去|，|我们|就|去|。","rú guǒ|nǐ|xiǎng|qù||wǒ men|jiù|qù|","If you want to go, we'll go."]}],"spot":[{"en":"If it rains, I won't go.","right":"如果下雨，我就不去。","wrong":"下雨如果，就我不去。","full":["如果|下雨|，|我|就|不|去|。","rú guǒ|xià yǔ||wǒ|jiù|bù|qù|","If it rains, I won't go."]},{"en":"If you go, I'll go.","right":"如果你去，我就去。","wrong":"如果你去，就我去。","full":["如果|你|去|，|我|就|去|。","rú guǒ|nǐ|qù||wǒ|jiù|qù|","If you go, I'll go."]}]},{"id":"yi-jiu","level":3,"title":"一…就: as soon as","pattern":"Subject + 一 + verb，就 + verb","why":"一 before the first verb and 就 before the second say that the second thing follows straight away.","mark":["一","就"],"mistake":["一我回家就吃饭。","我一回家就吃饭。","一 follows the subject."],"ex":[["我|一|回家|就|吃饭|。","wǒ|yī|huí jiā|jiù|chī fàn|","As soon as I get home, I eat."],["他|一|看|就|懂|。","tā|yī|kàn|jiù|dǒng|","He understands as soon as he looks."],["她|一|到|就|给|我|打电话|。","tā|yī|dào|jiù|gěi|wǒ|dǎ diàn huà|","She phoned me as soon as she arrived."]],"gap":[{"en":"As soon as I get home, I eat.","before":"我","after":"回家就吃饭。","a":"一","wrong":["也","很","的"],"pins":{"一":"yī","也":"yě","很":"hěn","的":"de"},"full":["我|一|回家|就|吃饭|。","wǒ|yī|huí jiā|jiù|chī fàn|","As soon as I get home, I eat."]},{"en":"He understands as soon as he looks.","before":"他一看","after":"懂。","a":"就","wrong":["也","很","的"],"pins":{"就":"jiù","也":"yě","很":"hěn","的":"de"},"full":["他|一|看|就|懂|。","tā|yī|kàn|jiù|dǒng|","He understands as soon as he looks."]},{"en":"She phoned me as soon as she arrived.","before":"她一到","after":"给我打电话。","a":"就","wrong":["也","很","的"],"pins":{"就":"jiù","也":"yě","很":"hěn","的":"de"},"full":["她|一|到|就|给|我|打电话|。","tā|yī|dào|jiù|gěi|wǒ|dǎ diàn huà|","She phoned me as soon as she arrived."]}],"order":[{"en":"As soon as I get home, I eat.","a":"我|一|回家|就|吃饭|。","alt":[],"full":["我|一|回家|就|吃饭|。","wǒ|yī|huí jiā|jiù|chī fàn|","As soon as I get home, I eat."]},{"en":"As soon as he arrives, he makes a phone call.","a":"他|一|到|就|打|电话|。","alt":[],"full":["他|一|到|就|打|电话|。","tā|yī|dào|jiù|dǎ|diàn huà|","As soon as he arrives, he makes a phone call."]},{"en":"She understands as soon as she looks.","a":"她|一|看|就|懂|。","alt":[],"full":["她|一|看|就|懂|。","tā|yī|kàn|jiù|dǒng|","She understands as soon as she looks."]}],"spot":[{"en":"As soon as I get home, I eat.","right":"我一回家就吃饭。","wrong":"一我回家就吃饭。","full":["我|一|回家|就|吃饭|。","wǒ|yī|huí jiā|jiù|chī fàn|","As soon as I get home, I eat."]},{"en":"He understands as soon as he looks.","right":"他一看就懂。","wrong":"他看一懂就。","full":["他|一|看|就|懂|。","tā|yī|kàn|jiù|dǒng|","He understands as soon as he looks."]}]},{"id":"yuelaiyue","level":3,"title":"越来越: more and more","pattern":"越来越 + adjective","why":"越来越 says something keeps changing, getting more and more so. It already means \"more\", so 很 can't go with it.","mark":["越来越"],"mistake":["天气越来越很冷。","天气越来越冷。","No 很 after 越来越."],"ex":[["天气|越来越|冷|。","tiān qì|yuè lái yuè|lěng|","The weather is getting colder and colder."],["我|的|中文|越来越|好|。","wǒ|de|Zhōng wén|yuè lái yuè|hǎo|","My Chinese is getting better and better."],["东西|越来越|贵|。","dōng xi|yuè lái yuè|guì|","Things are getting more and more expensive."]],"gap":[{"en":"The weather is getting colder.","before":"天气","after":"冷了。","a":"越来越","wrong":["很","是","的"],"pins":{"越来越":"yuè lái yuè","很":"hěn","是":"shì","的":"de"},"full":["天气|越来越|冷|了|。","tiān qì|yuè lái yuè|lěng|le|","The weather is getting colder."]},{"en":"Your Chinese is getting better.","before":"你的中文","after":"好了。","a":"越来越","wrong":["是","的","吗"],"pins":{"越来越":"yuè lái yuè","是":"shì","的":"de","吗":"ma"},"full":["你|的|中文|越来越|好|了|。","nǐ|de|Zhōng wén|yuè lái yuè|hǎo|le|","Your Chinese is getting better."]},{"en":"Things are getting more expensive.","before":"东西越来越","after":"。","a":"贵","wrong":["很","是","吗"],"pins":{"贵":"guì","很":"hěn","是":"shì","吗":"ma"},"full":["东西|越来越|贵|。","dōng xi|yuè lái yuè|guì|","Things are getting more expensive."]}],"order":[{"en":"The weather is getting hotter.","a":"天气|越来越|热|了|。","alt":[],"full":["天气|越来越|热|了|。","tiān qì|yuè lái yuè|rè|le|","The weather is getting hotter."]},{"en":"My Chinese is getting better.","a":"我|的|中文|越来越|好|。","alt":[],"full":["我|的|中文|越来越|好|。","wǒ|de|Zhōng wén|yuè lái yuè|hǎo|","My Chinese is getting better."]},{"en":"Things here are getting more expensive.","a":"这儿|的|东西|越来越|贵|。","alt":[],"full":["这儿|的|东西|越来越|贵|。","zhèr|de|dōng xi|yuè lái yuè|guì|","Things here are getting more expensive."]}],"spot":[{"en":"The weather is getting colder.","right":"天气越来越冷。","wrong":"天气越来越很冷。","full":["天气|越来越|冷|。","tiān qì|yuè lái yuè|lěng|","The weather is getting colder."]},{"en":"Things are getting more expensive.","right":"东西越来越贵。","wrong":"东西贵越来越。","full":["东西|越来越|贵|。","dōng xi|yuè lái yuè|guì|","Things are getting more expensive."]}]},{"id":"you-you","level":3,"title":"又…又: both at once","pattern":"又 + A + 又 + B","why":"又…又 says two things are true at the same time, each with its own 又. They are usually both good, or both bad.","mark":["又"],"mistake":["她又高，漂亮。","她又高又漂亮。","Each one takes a 又."],"ex":[["这|个|又|便宜|又|好|。","zhè|gè|yòu|pián yi|yòu|hǎo|","This is both cheap and good."],["她|又|高|又|漂亮|。","tā|yòu|gāo|yòu|piào liang|","She is tall and beautiful."],["他|又|忙|又|累|。","tā|yòu|máng|yòu|lèi|","He is busy and tired."]],"gap":[{"en":"This apple is big and tasty.","before":"这个苹果又大","after":"好吃。","a":"又","wrong":["和","也","很"],"pins":{"又":"yòu","和":"hé","也":"yě","很":"hěn"},"full":["这|个|苹果|又|大|又|好吃|。","zhè|gè|píng guǒ|yòu|dà|yòu|hǎo chī|","This apple is big and tasty."]},{"en":"He is busy and tired.","before":"他","after":"忙又累。","a":"又","wrong":["和","很","的"],"pins":{"又":"yòu","和":"hé","很":"hěn","的":"de"},"full":["他|又|忙|又|累|。","tā|yòu|máng|yòu|lèi|","He is busy and tired."]},{"en":"She is tall and beautiful.","before":"她又高又","after":"。","a":"漂亮","wrong":["很","是","吗"],"pins":{"漂亮":"piào liang","很":"hěn","是":"shì","吗":"ma"},"full":["她|又|高|又|漂亮|。","tā|yòu|gāo|yòu|piào liang|","She is tall and beautiful."]}],"order":[{"en":"She is tall and beautiful.","a":"她|又|高|又|漂亮|。","alt":["她|又|漂亮|又|高|。"],"full":["她|又|高|又|漂亮|。","tā|yòu|gāo|yòu|piào liang|","She is tall and beautiful."]},{"en":"This is both cheap and good.","a":"这个|又|便宜|又|好|。","alt":["这个|又|好|又|便宜|。"],"full":["这个|又|便宜|又|好|。","zhè gè|yòu|pián yi|yòu|hǎo|","This is both cheap and good."]},{"en":"I am tired and hungry.","a":"我|又|累|又|饿|。","alt":["我|又|饿|又|累|。"],"full":["我|又|累|又|饿|。","wǒ|yòu|lèi|yòu|è|","I am tired and hungry."]}],"spot":[{"en":"She is tall and beautiful.","right":"她又高又漂亮。","wrong":"她又高，漂亮。","full":["她|又|高|又|漂亮|。","tā|yòu|gāo|yòu|piào liang|","She is tall and beautiful."]},{"en":"He is busy and tired.","right":"他又忙又累。","wrong":"他忙又又累。","full":["他|又|忙|又|累|。","tā|yòu|máng|yòu|lèi|","He is busy and tired."]}]},{"id":"chule","level":3,"title":"除了: besides, or except","pattern":"除了 + A，subject + 也 or 都 + verb","why":"The second half decides the meaning. With 也, A is included: \"besides A, also\". With 都, A is left out: \"everyone except A\".","mark":["除了"],"mistake":["除了茶，我喜欢也咖啡。","除了茶，我也喜欢咖啡。","也 comes before the verb."],"ex":[["除了|茶|，|我|也|喜欢|咖啡|。","chú le|chá||wǒ|yě|xǐ huan|kā fēi|","Besides tea, I also like coffee."],["除了|他|，|我们|都|去|。","chú le|tā||wǒ men|dōu|qù|","We are all going, except him."],["除了|星期天|，|我|每|天|都|工作|。","chú le|xīng qī tiān||wǒ|měi|tiān|dōu|gōng zuò|","I work every day except Sunday."]],"gap":[{"en":"Besides tea, I also like coffee.","before":"","after":"茶，我也喜欢咖啡。","a":"除了","wrong":["因为","虽然","如果"],"pins":{"除了":"chú le","因为":"yīn wèi","虽然":"suī rán","如果":"rú guǒ"},"full":["除了|茶|，|我|也|喜欢|咖啡|。","chú le|chá||wǒ|yě|xǐ huan|kā fēi|","Besides tea, I also like coffee."]},{"en":"We are all going, except him.","before":"除了他，我们","after":"去。","a":"都","wrong":["很","的","吗"],"pins":{"都":"dōu","很":"hěn","的":"de","吗":"ma"},"full":["除了|他|，|我们|都|去|。","chú le|tā||wǒ men|dōu|qù|","We are all going, except him."]},{"en":"Besides Chinese, I can also speak English.","before":"除了中文，我","after":"会说英语。","a":"也","wrong":["很","的","吗"],"pins":{"也":"yě","很":"hěn","的":"de","吗":"ma"},"full":["除了|中文|，|我|也|会|说|英语|。","chú le|Zhōng wén||wǒ|yě|huì|shuō|Yīng yǔ|","Besides Chinese, I can also speak English."]}],"order":[{"en":"Besides tea, I also like coffee.","a":"除了|茶|，|我|也|喜欢|咖啡|。","alt":[],"full":["除了|茶|，|我|也|喜欢|咖啡|。","chú le|chá||wǒ|yě|xǐ huan|kā fēi|","Besides tea, I also like coffee."]},{"en":"We are all going, except him.","a":"除了|他|，|我们|都|去|。","alt":[],"full":["除了|他|，|我们|都|去|。","chú le|tā||wǒ men|dōu|qù|","We are all going, except him."]},{"en":"Besides Chinese, I can also speak English.","a":"除了|中文|，|我|也|会|说|英语|。","alt":[],"full":["除了|中文|，|我|也|会|说|英语|。","chú le|Zhōng wén||wǒ|yě|huì|shuō|Yīng yǔ|","Besides Chinese, I can also speak English."]}],"spot":[{"en":"Besides tea, I also like coffee.","right":"除了茶，我也喜欢咖啡。","wrong":"除了茶，我喜欢也咖啡。","full":["除了|茶|，|我|也|喜欢|咖啡|。","chú le|chá||wǒ|yě|xǐ huan|kā fēi|","Besides tea, I also like coffee."]},{"en":"We are all going, except him.","right":"除了他，我们都去。","wrong":"除了他，都我们去。","full":["除了|他|，|我们|都|去|。","chú le|tā||wǒ men|dōu|qù|","We are all going, except him."]}]},{"id":"shi-de","level":3,"title":"是…的: when, where, how it happened","pattern":"Subject + 是 + when/where/how + verb + 的","why":"For something that has already happened, 是…的 puts the weight on a detail: when, where, how or with whom. The 是 can be left out in speech; the 的 cannot.","mark":["是","的"],"mistake":["我是昨天来了。","我是昨天来的。","With 是…的 the sentence ends in 的, not 了."],"ex":[["我|是|昨天|来|的|。","wǒ|shì|zuó tiān|lái|de|","I came yesterday."],["你|是|怎么|来|的|？","nǐ|shì|zěn me|lái|de|","How did you get here?"],["他|是|坐|飞机|去|的|。","tā|shì|zuò|fēi jī|qù|de|","He went by plane."]],"gap":[{"en":"I came yesterday.","before":"我是昨天来","after":"。","a":"的","wrong":["了","吗","着"],"pins":{"的":"de","了":"le","吗":"ma","着":"zhe"},"full":["我|是|昨天|来|的|。","wǒ|shì|zuó tiān|lái|de|","I came yesterday."]},{"en":"How did you get here?","before":"你","after":"怎么来的？","a":"是","wrong":["在","很","有"],"pins":{"是":"shì","在":"zài","很":"hěn","有":"yǒu"},"full":["你|是|怎么|来|的|？","nǐ|shì|zěn me|lái|de|","How did you get here?"]},{"en":"He went by plane.","before":"他是坐飞机去","after":"。","a":"的","wrong":["了","过","着"],"pins":{"的":"de","了":"le","过":"guo","着":"zhe"},"full":["他|是|坐|飞机|去|的|。","tā|shì|zuò|fēi jī|qù|de|","He went by plane."]}],"order":[{"en":"I came yesterday.","a":"我|是|昨天|来|的|。","alt":[],"full":["我|是|昨天|来|的|。","wǒ|shì|zuó tiān|lái|de|","I came yesterday."]},{"en":"How did you get here?","a":"你|是|怎么|来|的|？","alt":[],"full":["你|是|怎么|来|的|？","nǐ|shì|zěn me|lái|de|","How did you get here?"]},{"en":"He went by plane.","a":"他|是|坐|飞机|去|的|。","alt":[],"full":["他|是|坐|飞机|去|的|。","tā|shì|zuò|fēi jī|qù|de|","He went by plane."]}],"spot":[{"en":"I came yesterday.","right":"我是昨天来的。","wrong":"我是昨天来了。","full":["我|是|昨天|来|的|。","wǒ|shì|zuó tiān|lái|de|","I came yesterday."]},{"en":"He went by plane.","right":"他是坐飞机去的。","wrong":"他坐飞机是去的。","full":["他|是|坐|飞机|去|的|。","tā|shì|zuò|fēi jī|qù|de|","He went by plane."]}]},{"id":"yibian","level":3,"title":"一边…一边: two things at once","pattern":"Subject + 一边 + verb A + 一边 + verb B","why":"Two actions at the same time, each after its own 一边. Say the subject once, at the front.","mark":["一边"],"mistake":["我一边吃饭，一边我看电视。","我一边吃饭，一边看电视。","Say the subject once, before the first 一边."],"ex":[["我|一边|吃饭|一边|看|电视|。","wǒ|yī biān|chī fàn|yī biān|kàn|diàn shì|","I watch TV while I eat."],["她|一边|走|一边|唱歌|。","tā|yī biān|zǒu|yī biān|chàng gē|","She sings as she walks."],["他们|一边|喝茶|一边|聊天|。","tā men|yī biān|hē chá|yī biān|liáo tiān|","They chat over tea."]],"gap":[{"en":"I watch TV while I eat.","before":"我","after":"吃饭一边看电视。","a":"一边","wrong":["一起","一下","一点"],"pins":{"一边":"yī biān","一起":"yī qǐ","一下":"yī xià","一点":"yī diǎn"},"full":["我|一边|吃饭|一边|看|电视|。","wǒ|yī biān|chī fàn|yī biān|kàn|diàn shì|","I watch TV while I eat."]},{"en":"She sings as she walks.","before":"她一边走","after":"唱歌。","a":"一边","wrong":["一起","一下","一点"],"pins":{"一边":"yī biān","一起":"yī qǐ","一下":"yī xià","一点":"yī diǎn"},"full":["她|一边|走|一边|唱歌|。","tā|yī biān|zǒu|yī biān|chàng gē|","She sings as she walks."]},{"en":"They chat over tea.","before":"他们一边喝茶","after":"聊天。","a":"一边","wrong":["一起","以后","一样"],"pins":{"一边":"yī biān","一起":"yī qǐ","以后":"yǐ hòu","一样":"yī yàng"},"full":["他们|一边|喝茶|一边|聊天|。","tā men|yī biān|hē chá|yī biān|liáo tiān|","They chat over tea."]}],"order":[{"en":"I watch TV while I eat.","a":"我|一边|吃饭|一边|看|电视|。","alt":["我|一边|看|电视|一边|吃饭|。"],"full":["我|一边|吃饭|一边|看|电视|。","wǒ|yī biān|chī fàn|yī biān|kàn|diàn shì|","I watch TV while I eat."]},{"en":"She sings as she walks.","a":"她|一边|走|一边|唱歌|。","alt":["她|一边|唱歌|一边|走|。"],"full":["她|一边|走|一边|唱歌|。","tā|yī biān|zǒu|yī biān|chàng gē|","She sings as she walks."]},{"en":"They chat over tea.","a":"他们|一边|喝|茶|一边|聊天|。","alt":["他们|一边|聊天|一边|喝|茶|。"],"full":["他们|一边|喝|茶|一边|聊天|。","tā men|yī biān|hē|chá|yī biān|liáo tiān|","They chat over tea."]}],"spot":[{"en":"I watch TV while I eat.","right":"我一边吃饭一边看电视。","wrong":"我一边吃饭，一边我看电视。","full":["我|一边|吃饭|一边|看|电视|。","wǒ|yī biān|chī fàn|yī biān|kàn|diàn shì|","I watch TV while I eat."]},{"en":"She sings as she walks.","right":"她一边走一边唱歌。","wrong":"一边她走一边唱歌。","full":["她|一边|走|一边|唱歌|。","tā|yī biān|zǒu|yī biān|chàng gē|","She sings as she walks."]}]},{"id":"jiu-cai","level":3,"title":"就 and 才: early, or not until","pattern":"time + 就 + verb + 了 · time + 才 + verb","why":"Both go before the verb, after a time. 就 says it happened early or easily, and usually takes 了; 才 says it happened late, only after a wait, and takes no 了.","mark":["就","才"],"mistake":["他十点才来了。","他十点才来。","才 already says \"not until\"; it doesn't take 了."],"ex":[["他|七|点|就|来|了|。","tā|qī|diǎn|jiù|lái|le|","He came as early as seven."],["他|十|点|才|来|。","tā|shí|diǎn|cái|lái|","He didn't come until ten."],["我|昨天|才|知道|。","wǒ|zuó tiān|cái|zhī dào|","I only found out yesterday."]],"gap":[{"en":"He came as early as seven.","before":"他七点","after":"来了。","a":"就","wrong":["才","都","也"],"pins":{"就":"jiù","才":"cái","都":"dōu","也":"yě"},"full":["他|七|点|就|来|了|。","tā|qī|diǎn|jiù|lái|le|","He came as early as seven."]},{"en":"He didn't come until ten.","before":"他十点","after":"来。","a":"才","wrong":["就","都","也"],"pins":{"才":"cái","就":"jiù","都":"dōu","也":"yě"},"full":["他|十|点|才|来|。","tā|shí|diǎn|cái|lái|","He didn't come until ten."]},{"en":"I only found out yesterday.","before":"我昨天","after":"知道。","a":"才","wrong":["就","都","很"],"pins":{"才":"cái","就":"jiù","都":"dōu","很":"hěn"},"full":["我|昨天|才|知道|。","wǒ|zuó tiān|cái|zhī dào|","I only found out yesterday."]}],"order":[{"en":"He came as early as seven.","a":"他|七点|就|来|了|。","alt":["七点|他|就|来|了|。"],"full":["他|七点|就|来|了|。","tā|qī diǎn|jiù|lái|le|","He came as early as seven."]},{"en":"He didn't come until ten.","a":"他|十点|才|来|。","alt":["十点|他|才|来|。"],"full":["他|十点|才|来|。","tā|shí diǎn|cái|lái|","He didn't come until ten."]},{"en":"I only found out yesterday.","a":"我|昨天|才|知道|。","alt":["昨天|我|才|知道|。"],"full":["我|昨天|才|知道|。","wǒ|zuó tiān|cái|zhī dào|","I only found out yesterday."]}],"spot":[{"en":"He didn't come until ten.","right":"他十点才来。","wrong":"他十点才来了。","full":["他|十|点|才|来|。","tā|shí|diǎn|cái|lái|","He didn't come until ten."]},{"en":"He came as early as seven.","right":"他七点就来了。","wrong":"他七点来就了。","full":["他|七|点|就|来|了|。","tā|qī|diǎn|jiù|lái|le|","He came as early as seven."]}]},{"id":"result","level":3,"title":"verb + result: 完, 懂, 到","pattern":"verb + 完/懂/到/好 (+ 了) · 没 + verb + result","why":"A second word right after the verb says how the action ended: 完 finished, 懂 understood, 到 reached or got, 好 done properly. For \"didn't manage to\", put 没 in front and drop 了.","mark":["完","懂","到"],"mistake":["我不看完了这本书。","我没看完这本书。","For something not finished, use 没, not 不, and drop 了."],"ex":[["我|看|完|了|这|本|书|。","wǒ|kàn|wán|le|zhè|běn|shū|","I've finished reading this book."],["你|听懂|了|吗|？","nǐ|tīng dǒng|le|ma|","Did you understand?"],["我|找到|我|的|手机|了|。","wǒ|zhǎo dào|wǒ|de|shǒu jī|le|","I found my phone."]],"gap":[{"en":"I've finished reading this book.","before":"我看","after":"了这本书。","a":"完","wrong":["在","给","着"],"pins":{"完":"wán","在":"zài","给":"gěi","着":"zhe"},"full":["我|看|完|了|这|本|书|。","wǒ|kàn|wán|le|zhè|běn|shū|","I've finished reading this book."]},{"en":"Did you understand?","before":"你听","after":"了吗？","a":"懂","wrong":["在","给","着"],"pins":{"懂":"dǒng","在":"zài","给":"gěi","着":"zhe"},"full":["你|听懂|了|吗|？","nǐ|tīng dǒng|le|ma|","Did you understand?"]},{"en":"I found my phone.","before":"我找","after":"我的手机了。","a":"到","wrong":["懂","给","在"],"pins":{"到":"dào","懂":"dǒng","给":"gěi","在":"zài"},"full":["我|找到|我|的|手机|了|。","wǒ|zhǎo dào|wǒ|de|shǒu jī|le|","I found my phone."]}],"order":[{"en":"I've finished reading this book.","a":"我|看|完|了|这|本|书|。","alt":["这|本|书|我|看|完|了|。"],"full":["我|看|完|了|这|本|书|。","wǒ|kàn|wán|le|zhè|běn|shū|","I've finished reading this book."]},{"en":"Did you understand?","a":"你|听|懂|了|吗|？","alt":[],"full":["你|听|懂|了|吗|？","nǐ|tīng|dǒng|le|ma|","Did you understand?"]},{"en":"I found my phone.","a":"我|找|到|我|的|手机|了|。","alt":["我|找|到|了|我|的|手机|。"],"full":["我|找|到|我|的|手机|了|。","wǒ|zhǎo|dào|wǒ|de|shǒu jī|le|","I found my phone."]}],"spot":[{"en":"I didn't finish this book.","right":"我没看完这本书。","wrong":"我不看完了这本书。","full":["我|没|看|完|这|本|书|。","wǒ|méi|kàn|wán|zhè|běn|shū|","I didn't finish this book."]},{"en":"Did you understand?","right":"你听懂了吗？","wrong":"你懂听了吗？","full":["你|听懂|了|吗|？","nǐ|tīng dǒng|le|ma|","Did you understand?"]}]},{"id":"lai-qu","level":3,"title":"verb + 来 / 去: which way it goes","pattern":"verb + 来 (towards the speaker) · verb + 去 (away)","why":"After a verb of moving, 来 means towards the speaker and 去 away from them. 进, 出, 上, 下 and 回 can sit in between: 走进来 \"walk in (to here)\", 跑出去 \"run out (from here)\". A place goes before the 来 or 去: 进房间来.","mark":["来","去"],"mistake":["请你进来我的房间。","请你进我的房间来。","A place goes between the verb and 来: 进 + place + 来."],"ex":[["请|进来|。","qǐng|jin lai|","Please come in."],["他|跑|出去|了|。","tā|pǎo|chu qu|le|","He ran out."],["妈妈|回来|了|。","mā ma|huí lai|le|","Mum is back."]],"gap":[{"en":"Please come in.","before":"请进","after":"。","a":"来","wrong":["在","给","着"],"pins":{"来":"lái","在":"zài","给":"gěi","着":"zhe"},"full":["请|进来|。","qǐng|jin lai|","Please come in."]},{"en":"He ran out.","before":"他跑出","after":"了。","a":"去","wrong":["在","给","着"],"pins":{"去":"qù","在":"zài","给":"gěi","着":"zhe"},"full":["他|跑|出去|了|。","tā|pǎo|chu qu|le|","He ran out."]},{"en":"Mum is back.","before":"妈妈回","after":"了。","a":"来","wrong":["在","给","着"],"pins":{"来":"lái","在":"zài","给":"gěi","着":"zhe"},"full":["妈妈|回来|了|。","mā ma|huí lai|le|","Mum is back."]}],"order":[{"en":"Please come in.","a":"请|进来|。","alt":[],"full":["请|进来|。","qǐng|jìn lai|","Please come in."]},{"en":"He ran out.","a":"他|跑|出去|了|。","alt":[],"full":["他|跑|出去|了|。","tā|pǎo|chū qu|le|","He ran out."]},{"en":"Mum is back.","a":"妈妈|回来|了|。","alt":[],"full":["妈妈|回来|了|。","mā ma|huí lai|le|","Mum is back."]}],"spot":[{"en":"Mum is back.","right":"妈妈回来了。","wrong":"妈妈来回了。","full":["妈妈|回来|了|。","mā ma|huí lai|le|","Mum is back."]},{"en":"Please come into my room.","right":"请你进我的房间来。","wrong":"请你进来去我的房间。","full":["请|你|进|我|的|房间|来|。","qǐng|nǐ|jìn|wǒ|de|fáng jiān|lái|","Please come into my room."]}]},{"id":"yue-yue","level":3,"title":"越…越: the more …, the more …","pattern":"越 + A + 越 + B","why":"B grows as A does. Each 越 goes straight before a verb or a describing word. 越 already says \"more\", so no 很 after it.","mark":["越"],"mistake":["雨越下越很大。","雨越下越大。","越 already says how much: no 很 after it."],"ex":[["雨|越|下|越|大|。","yǔ|yuè|xià|yuè|dà|","The rain got heavier and heavier."],["他|越|说|越|快|。","tā|yuè|shuō|yuè|kuài|","The more he talked, the faster he went."],["中文|我|越|学|越|喜欢|。","Zhōng wén|wǒ|yuè|xué|yuè|xǐ huan|","The more I learn Chinese, the more I like it."]],"gap":[{"en":"The rain got heavier and heavier.","before":"雨越下","after":"大。","a":"越","wrong":["很","太","都"],"pins":{"越":"yuè","很":"hěn","太":"tài","都":"dōu"},"full":["雨|越|下|越|大|。","yǔ|yuè|xià|yuè|dà|","The rain got heavier and heavier."]},{"en":"The more he talked, the faster he went.","before":"他","after":"说越快。","a":"越","wrong":["很","就","都"],"pins":{"越":"yuè","很":"hěn","就":"jiù","都":"dōu"},"full":["他|越|说|越|快|。","tā|yuè|shuō|yuè|kuài|","The more he talked, the faster he went."]},{"en":"The more I learn Chinese, the more I like it.","before":"中文我","after":"学越喜欢。","a":"越","wrong":["很","最","都"],"pins":{"越":"yuè","很":"hěn","最":"zuì","都":"dōu"},"full":["中文|我|越|学|越|喜欢|。","Zhōng wén|wǒ|yuè|xué|yuè|xǐ huan|","The more I learn Chinese, the more I like it."]}],"order":[{"en":"The rain got heavier and heavier.","a":"雨|越|下|越|大|。","alt":[],"full":["雨|越|下|越|大|。","yǔ|yuè|xià|yuè|dà|","The rain got heavier and heavier."]},{"en":"The more he talked, the faster he went.","a":"他|越|说|越|快|。","alt":[],"full":["他|越|说|越|快|。","tā|yuè|shuō|yuè|kuài|","The more he talked, the faster he went."]},{"en":"The more I learn Chinese, the more I like it.","a":"中文|我|越|学|越|喜欢|。","alt":["我|越|学|中文|越|喜欢|。"],"full":["中文|我|越|学|越|喜欢|。","Zhōng wén|wǒ|yuè|xué|yuè|xǐ huan|","The more I learn Chinese, the more I like it."]}],"spot":[{"en":"The rain got heavier and heavier.","right":"雨越下越大。","wrong":"雨越下越很大。","full":["雨|越|下|越|大|。","yǔ|yuè|xià|yuè|dà|","The rain got heavier and heavier."]},{"en":"The more he talked, the faster he went.","right":"他越说越快。","wrong":"他说越越快。","full":["他|越|说|越|快|。","tā|yuè|shuō|yuè|kuài|","The more he talked, the faster he went."]}]},{"id":"budan","level":3,"title":"不但…而且: not only, but also","pattern":"Subject + 不但 + A，而且 + B","why":"不但 gives one point and 而且 adds another, usually the stronger. With one subject for both halves, it comes before 不但.","mark":["不但","而且"],"mistake":["不但他会说中文，而且会写汉字。","他不但会说中文，而且会写汉字。","With one subject, put it before 不但."],"ex":[["他|不但|会|说|中文|，|而且|会|写|汉字|。","tā|bù dàn|huì|shuō|Zhōng wén||ér qiě|huì|xiě|hàn zì|","He can not only speak Chinese but write characters too."],["这|个|菜|不但|好看|，|而且|好吃|。","zhè|gè|cài|bù dàn|hǎo kàn||ér qiě|hǎo chī|","This dish looks good and tastes good too."],["她|不但|聪明|，|而且|很|努力|。","tā|bù dàn|cōng ming||ér qiě|hěn|nǔ lì|","She is not only clever but hard-working too."]],"gap":[{"en":"He can not only speak Chinese but write characters too.","before":"他","after":"会说中文，而且会写汉字。","a":"不但","wrong":["因为","虽然","如果"],"pins":{"不但":"bù dàn","因为":"yīn wèi","虽然":"suī rán","如果":"rú guǒ"},"full":["他|不但|会|说|中文|，|而且|会|写|汉字|。","tā|bù dàn|huì|shuō|Zhōng wén||ér qiě|huì|xiě|hàn zì|","He can not only speak Chinese but write characters too."]},{"en":"This dish looks good and tastes good too.","before":"这个菜不但好看，","after":"好吃。","a":"而且","wrong":["所以","但是","因为"],"pins":{"而且":"ér qiě","所以":"suǒ yǐ","但是":"dàn shì","因为":"yīn wèi"},"full":["这|个|菜|不但|好看|，|而且|好吃|。","zhè|gè|cài|bù dàn|hǎo kàn||ér qiě|hǎo chī|","This dish looks good and tastes good too."]},{"en":"She is not only clever but hard-working too.","before":"她不但聪明，","after":"很努力。","a":"而且","wrong":["所以","因为","如果"],"pins":{"而且":"ér qiě","所以":"suǒ yǐ","因为":"yīn wèi","如果":"rú guǒ"},"full":["她|不但|聪明|，|而且|很|努力|。","tā|bù dàn|cōng ming||ér qiě|hěn|nǔ lì|","She is not only clever but hard-working too."]}],"order":[{"en":"This dish looks good and tastes good too.","a":"这个|菜|不但|好看|，|而且|好吃|。","alt":["这个|菜|不但|好吃|，|而且|好看|。"],"full":["这个|菜|不但|好看|，|而且|好吃|。","zhè gè|cài|bù dàn|hǎo kàn||ér qiě|hǎo chī|","This dish looks good and tastes good too."]},{"en":"She is not only clever but hard-working too.","a":"她|不但|聪明|，|而且|很|努力|。","alt":["她|不但|很|努力|，|而且|聪明|。"],"full":["她|不但|聪明|，|而且|很|努力|。","tā|bù dàn|cōng ming||ér qiě|hěn|nǔ lì|","She is not only clever but hard-working too."]},{"en":"He can not only speak Chinese but write characters too.","a":"他|不但|会|说|中文|，|而且|会|写|汉字|。","alt":["他|不但|会|写|汉字|，|而且|会|说|中文|。"],"full":["他|不但|会|说|中文|，|而且|会|写|汉字|。","tā|bù dàn|huì|shuō|Zhōng wén||ér qiě|huì|xiě|hàn zì|","He can not only speak Chinese but write characters too."]}],"spot":[{"en":"He can not only speak Chinese but write characters too.","right":"他不但会说中文，而且会写汉字。","wrong":"不但他会说中文，而且会写汉字。","full":["他|不但|会|说|中文|，|而且|会|写|汉字|。","tā|bù dàn|huì|shuō|Zhōng wén||ér qiě|huì|xiě|hàn zì|","He can not only speak Chinese but write characters too."]},{"en":"This dish looks good and tastes good too.","right":"这个菜不但好看，而且好吃。","wrong":"这个菜不但好看，但是好吃。","full":["这|个|菜|不但|好看|，|而且|好吃|。","zhè|gè|cài|bù dàn|hǎo kàn||ér qiě|hǎo chī|","This dish looks good and tastes good too."]}]},{"id":"kuai-le","level":3,"title":"快要…了: about to happen","pattern":"快要 / 快 / 就要 + verb + 了","why":"快要…了, 快…了 or 就要…了 says something is about to happen; the 了 at the end is part of the pattern. With an exact time (明天, 五点) use 就要, not 快要.","mark":["快要","快","就要"],"mistake":["火车快要开。","火车快要开了。","The pattern needs its 了 at the end."],"ex":[["火车|快要|开|了|。","huǒ chē|kuài yào|kāi|le|","The train is about to leave."],["我们|快|到|了|。","wǒ men|kuài|dào|le|","We're nearly there."],["明天|就|要|考试|了|。","míng tiān|jiù|yào|kǎo shì|le|","The exam is tomorrow."]],"gap":[{"en":"The train is about to leave.","before":"火车快要开","after":"。","a":"了","wrong":["的","吗","着"],"pins":{"了":"le","的":"de","吗":"ma","着":"zhe"},"full":["火车|快要|开|了|。","huǒ chē|kuài yào|kāi|le|","The train is about to leave."]},{"en":"We're nearly there.","before":"我们","after":"到了。","a":"快","wrong":["很","太","最"],"pins":{"快":"kuài","很":"hěn","太":"tài","最":"zuì"},"full":["我们|快|到|了|。","wǒ men|kuài|dào|le|","We're nearly there."]},{"en":"The exam is tomorrow.","before":"明天","after":"考试了。","a":"就要","wrong":["快要","很","太"],"pins":{"就要":"jiù yào","快要":"kuài yào","很":"hěn","太":"tài"},"full":["明天|就|要|考试|了|。","míng tiān|jiù|yào|kǎo shì|le|","The exam is tomorrow."]}],"order":[{"en":"The train is about to leave.","a":"火车|快要|开|了|。","alt":[],"full":["火车|快要|开|了|。","huǒ chē|kuài yào|kāi|le|","The train is about to leave."]},{"en":"We're nearly there.","a":"我们|快|到|了|。","alt":[],"full":["我们|快|到|了|。","wǒ men|kuài|dào|le|","We're nearly there."]},{"en":"The exam is tomorrow.","a":"明天|就要|考试|了|。","alt":[],"full":["明天|就要|考试|了|。","míng tiān|jiù yào|kǎo shì|le|","The exam is tomorrow."]}],"spot":[{"en":"The train is about to leave.","right":"火车快要开了。","wrong":"火车快要开。","full":["火车|快要|开|了|。","huǒ chē|kuài yào|kāi|le|","The train is about to leave."]},{"en":"The exam is tomorrow.","right":"明天就要考试了。","wrong":"明天快要考试了。","full":["明天|就|要|考试|了|。","míng tiān|jiù|yào|kǎo shì|le|","The exam is tomorrow."]}]},{"id":"lian-dou","level":4,"title":"连…都 / 也: even","pattern":"连 + A + 都/也 + verb","why":"连 picks out the most surprising case, and 都 or 也 has to follow it, before the verb: if even A, then surely everything else.","mark":["连"],"mistake":["他连饭吃都没有。","他连饭都没吃。","都 comes right after what 连 picks out, before the verb."],"ex":[["他|连|饭|都|没|吃|。","tā|lián|fàn|dōu|méi|chī|","He didn't even eat."],["这|个|字|连|老师|也|不|认识|。","zhè|gè|zì|lián|lǎo shī|yě|bù|rèn shi|","Even the teacher doesn't know this character."],["我|忙|得|连|喝|水|的|时间|都|没有|。","wǒ|máng|de|lián|hē|shuǐ|de|shí jiān|dōu|méi yǒu|","I'm so busy I don't even have time to drink water."]],"gap":[{"en":"He didn't even eat.","before":"他","after":"饭都没吃。","a":"连","wrong":["和","跟","把"],"pins":{"连":"lián","和":"hé","跟":"gēn","把":"bǎ"},"full":["他|连|饭|都|没|吃|。","tā|lián|fàn|dōu|méi|chī|","He didn't even eat."]},{"en":"Even the teacher doesn't know this character.","before":"这个字连老师","after":"不认识。","a":"也","wrong":["很","就","才"],"pins":{"也":"yě","很":"hěn","就":"jiù","才":"cái"},"full":["这|个|字|连|老师|也|不|认识|。","zhè|gè|zì|lián|lǎo shī|yě|bù|rèn shi|","Even the teacher doesn't know this character."]},{"en":"I don't even have time to drink water.","before":"我连喝水的时间","after":"没有。","a":"都","wrong":["很","就","才"],"pins":{"都":"dōu","很":"hěn","就":"jiù","才":"cái"},"full":["我|连|喝|水|的|时间|都|没有|。","wǒ|lián|hē|shuǐ|de|shí jiān|dōu|méi yǒu|","I don't even have time to drink water."]}],"order":[{"en":"He didn't even eat.","a":"他|连|饭|都|没|吃|。","alt":[],"full":["他|连|饭|都|没|吃|。","tā|lián|fàn|dōu|méi|chī|","He didn't even eat."]},{"en":"Even the teacher doesn't know this character.","a":"这个|字|连|老师|也|不|认识|。","alt":["连|老师|也|不|认识|这个|字|。"],"full":["这个|字|连|老师|也|不|认识|。","zhè gè|zì|lián|lǎo shī|yě|bù|rèn shi|","Even the teacher doesn't know this character."]},{"en":"I don't even have time to drink water.","a":"我|连|喝|水|的|时间|都|没有|。","alt":[],"full":["我|连|喝|水|的|时间|都|没有|。","wǒ|lián|hē|shuǐ|de|shí jiān|dōu|méi yǒu|","I don't even have time to drink water."]}],"spot":[{"en":"He didn't even eat.","right":"他连饭都没吃。","wrong":"他连饭吃都没有。","full":["他|连|饭|都|没|吃|。","tā|lián|fàn|dōu|méi|chī|","He didn't even eat."]},{"en":"Even the teacher doesn't know this character.","right":"这个字连老师也不认识。","wrong":"这个字连老师不认识。","full":["这|个|字|连|老师|也|不|认识|。","zhè|gè|zì|lián|lǎo shī|yě|bù|rèn shi|","Even the teacher doesn't know this character."]}]},{"id":"buguan","level":4,"title":"不管 / 无论…都: no matter","pattern":"不管/无论 + open question + 都 + verb","why":"The first half is left open, with a question word (什么, 谁, 怎么, 多) or \"A or B\". The second half has 都 (or 也): the result is the same whatever the answer.","mark":["不管","无论"],"mistake":["不管天气怎么样，我去。","不管天气怎么样，我都去。","The second half needs 都 (or 也)."],"ex":[["不管|天气|怎么样|，|我|都|去|。","bù guǎn|tiān qì|zěn me yàng||wǒ|dōu|qù|","I'm going whatever the weather."],["无论|谁|来|，|我|都|欢迎|。","wú lùn|shéi|lái||wǒ|dōu|huān yíng|","Whoever comes is welcome."],["不管|多|忙|，|他|每|天|都|跑步|。","bù guǎn|duō|máng||tā|měi|tiān|dōu|pǎo bù|","However busy he is, he runs every day."]],"gap":[{"en":"I'm going whatever the weather.","before":"","after":"天气怎么样，我都去。","a":"不管","wrong":["因为","虽然","如果"],"pins":{"不管":"bù guǎn","因为":"yīn wèi","虽然":"suī rán","如果":"rú guǒ"},"full":["不管|天气|怎么样|，|我|都|去|。","bù guǎn|tiān qì|zěn me yàng||wǒ|dōu|qù|","I'm going whatever the weather."]},{"en":"Whoever comes is welcome.","before":"无论谁来，我","after":"欢迎。","a":"都","wrong":["就","才","很"],"pins":{"都":"dōu","就":"jiù","才":"cái","很":"hěn"},"full":["无论|谁|来|，|我|都|欢迎|。","wú lùn|shéi|lái||wǒ|dōu|huān yíng|","Whoever comes is welcome."]},{"en":"However busy he is, he runs every day.","before":"不管多忙，他每天","after":"跑步。","a":"都","wrong":["就","才","很"],"pins":{"都":"dōu","就":"jiù","才":"cái","很":"hěn"},"full":["不管|多|忙|，|他|每|天|都|跑步|。","bù guǎn|duō|máng||tā|měi|tiān|dōu|pǎo bù|","However busy he is, he runs every day."]}],"order":[{"en":"I'm going whatever the weather.","a":"不管|天气|怎么样|，|我|都|去|。","alt":[],"full":["不管|天气|怎么样|，|我|都|去|。","bù guǎn|tiān qì|zěn me yàng||wǒ|dōu|qù|","I'm going whatever the weather."]},{"en":"Whoever comes is welcome.","a":"无论|谁|来|，|我|都|欢迎|。","alt":[],"full":["无论|谁|来|，|我|都|欢迎|。","wú lùn|shéi|lái||wǒ|dōu|huān yíng|","Whoever comes is welcome."]},{"en":"However busy he is, he runs every day.","a":"不管|多|忙|，|他|每天|都|跑步|。","alt":[],"full":["不管|多|忙|，|他|每天|都|跑步|。","bù guǎn|duō|máng||tā|měi tiān|dōu|pǎo bù|","However busy he is, he runs every day."]}],"spot":[{"en":"I'm going whatever the weather.","right":"不管天气怎么样，我都去。","wrong":"不管天气怎么样，我去。","full":["不管|天气|怎么样|，|我|都|去|。","bù guǎn|tiān qì|zěn me yàng||wǒ|dōu|qù|","I'm going whatever the weather."]},{"en":"Whoever comes is welcome.","right":"无论谁来，我都欢迎。","wrong":"无论谁来，都我欢迎。","full":["无论|谁|来|，|我|都|欢迎|。","wú lùn|shéi|lái||wǒ|dōu|huān yíng|","Whoever comes is welcome."]}]},{"id":"jishi","level":4,"title":"即使…也: even if","pattern":"即使 + condition，subject + 也 + verb","why":"即使 brings a condition, even one that may not be true, and 也 before the second verb says the result holds anyway. Unlike 虽然, it doesn't say the condition is real.","mark":["即使"],"mistake":["即使下雨，我们去。","即使下雨，我们也去。","The second half needs 也."],"ex":[["即使|下雨|，|我们|也|去|。","jí shǐ|xià yǔ||wǒ men|yě|qù|","We'll go even if it rains."],["即使|很|累|，|她|也|要|做|完|。","jí shǐ|hěn|lèi||tā|yě|yào|zuò|wán|","Even if she's tired, she'll finish it."],["即使|你|不|说|，|我|也|知道|。","jí shǐ|nǐ|bù|shuō||wǒ|yě|zhī dào|","Even if you don't say it, I know."]],"gap":[{"en":"We'll go even if it rains.","before":"","after":"下雨，我们也去。","a":"即使","wrong":["因为","所以","只有"],"pins":{"即使":"jí shǐ","因为":"yīn wèi","所以":"suǒ yǐ","只有":"zhǐ yǒu"},"full":["即使|下雨|，|我们|也|去|。","jí shǐ|xià yǔ||wǒ men|yě|qù|","We'll go even if it rains."]},{"en":"Even if she's tired, she'll finish it.","before":"即使很累，她","after":"要做完。","a":"也","wrong":["就","才","很"],"pins":{"也":"yě","就":"jiù","才":"cái","很":"hěn"},"full":["即使|很|累|，|她|也|要|做|完|。","jí shǐ|hěn|lèi||tā|yě|yào|zuò|wán|","Even if she's tired, she'll finish it."]},{"en":"Even if you don't say it, I know.","before":"即使你不说，我","after":"知道。","a":"也","wrong":["就","很","才"],"pins":{"也":"yě","就":"jiù","很":"hěn","才":"cái"},"full":["即使|你|不|说|，|我|也|知道|。","jí shǐ|nǐ|bù|shuō||wǒ|yě|zhī dào|","Even if you don't say it, I know."]}],"order":[{"en":"We'll go even if it rains.","a":"即使|下雨|，|我们|也|去|。","alt":[],"full":["即使|下雨|，|我们|也|去|。","jí shǐ|xià yǔ||wǒ men|yě|qù|","We'll go even if it rains."]},{"en":"Even if she's tired, she'll finish it.","a":"即使|很|累|，|她|也|要|做完|。","alt":["她|即使|很|累|，|也|要|做完|。"],"full":["即使|很|累|，|她|也|要|做完|。","jí shǐ|hěn|lèi||tā|yě|yào|zuò wán|","Even if she's tired, she'll finish it."]},{"en":"Even if you don't say it, I know.","a":"即使|你|不|说|，|我|也|知道|。","alt":[],"full":["即使|你|不|说|，|我|也|知道|。","jí shǐ|nǐ|bù|shuō||wǒ|yě|zhī dào|","Even if you don't say it, I know."]}],"spot":[{"en":"We'll go even if it rains.","right":"即使下雨，我们也去。","wrong":"即使下雨，也我们去。","full":["即使|下雨|，|我们|也|去|。","jí shǐ|xià yǔ||wǒ men|yě|qù|","We'll go even if it rains."]},{"en":"Even if you don't say it, I know.","right":"即使你不说，我也知道。","wrong":"即使你不说，我知道也。","full":["即使|你|不|说|，|我|也|知道|。","jí shǐ|nǐ|bù|shuō||wǒ|yě|zhī dào|","Even if you don't say it, I know."]}]},{"id":"jiran","level":4,"title":"既然…就: since, then","pattern":"既然 + accepted fact，就 + conclusion","why":"既然 gives a fact both speakers accept, and 就 draws the conclusion, often advice or a decision. It means \"given that\", not 因为 \"because\".","mark":["既然"],"mistake":["你病了既然，就休息吧。","既然你病了，就休息吧。","既然 starts the first half, or comes right after its subject."],"ex":[["既然|你|病|了|，|就|好好|休息|吧|。","jì rán|nǐ|bìng|le||jiù|hǎo hǎo|xiū xi|ba|","Since you're ill, have a good rest."],["既然|来|了|，|就|多|住|几|天|。","jì rán|lái|le||jiù|duō|zhù|jǐ|tiān|","Now that you're here, stay a few more days."],["你|既然|不|喜欢|，|就|别|买|了|。","nǐ|jì rán|bù|xǐ huan||jiù|bié|mǎi|le|","If you don't like it, don't buy it."]],"gap":[{"en":"Since you're ill, have a good rest.","before":"","after":"你病了，就好好休息吧。","a":"既然","wrong":["虽然","但是","除了"],"pins":{"既然":"jì rán","虽然":"suī rán","但是":"dàn shì","除了":"chú le"},"full":["既然|你|病|了|，|就|好好|休息|吧|。","jì rán|nǐ|bìng|le||jiù|hǎo hǎo|xiū xi|ba|","Since you're ill, have a good rest."]},{"en":"Now that you're here, stay a few more days.","before":"既然来了，","after":"多住几天。","a":"就","wrong":["才","都","很"],"pins":{"就":"jiù","才":"cái","都":"dōu","很":"hěn"},"full":["既然|来|了|，|就|多|住|几|天|。","jì rán|lái|le||jiù|duō|zhù|jǐ|tiān|","Now that you're here, stay a few more days."]},{"en":"If you don't like it, don't buy it.","before":"你既然不喜欢，","after":"别买了。","a":"就","wrong":["才","都","很"],"pins":{"就":"jiù","才":"cái","都":"dōu","很":"hěn"},"full":["你|既然|不|喜欢|，|就|别|买|了|。","nǐ|jì rán|bù|xǐ huan||jiù|bié|mǎi|le|","If you don't like it, don't buy it."]}],"order":[{"en":"Since you're ill, have a good rest.","a":"既然|你|病|了|，|就|好好|休息|吧|。","alt":["你|既然|病|了|，|就|好好|休息|吧|。"],"full":["既然|你|病|了|，|就|好好|休息|吧|。","jì rán|nǐ|bìng|le||jiù|hǎo hǎo|xiū xi|ba|","Since you're ill, have a good rest."]},{"en":"Now that you're here, stay a few more days.","a":"既然|来|了|，|就|多|住|几|天|。","alt":[],"full":["既然|来|了|，|就|多|住|几|天|。","jì rán|lái|le||jiù|duō|zhù|jǐ|tiān|","Now that you're here, stay a few more days."]},{"en":"If you don't like it, don't buy it.","a":"你|既然|不|喜欢|，|就|别|买|了|。","alt":["既然|你|不|喜欢|，|就|别|买|了|。"],"full":["你|既然|不|喜欢|，|就|别|买|了|。","nǐ|jì rán|bù|xǐ huan||jiù|bié|mǎi|le|","If you don't like it, don't buy it."]}],"spot":[{"en":"Now that you're here, stay a few more days.","right":"既然来了，就多住几天。","wrong":"既然来了，多就住几天。","full":["既然|来|了|，|就|多|住|几|天|。","jì rán|lái|le||jiù|duō|zhù|jǐ|tiān|","Now that you're here, stay a few more days."]},{"en":"If you don't like it, don't buy it.","right":"你既然不喜欢，就别买了。","wrong":"你不喜欢既然，就别买了。","full":["你|既然|不|喜欢|，|就|别|买|了|。","nǐ|jì rán|bù|xǐ huan||jiù|bié|mǎi|le|","If you don't like it, don't buy it."]}]},{"id":"zhiyou","level":4,"title":"只有…才: only if","pattern":"只有 + the one condition，才 + result","why":"只有 names the one condition that works, and 才 (not 就) brings the result. Compare 只要…就 \"as long as\", which says the condition is enough.","mark":["只有"],"mistake":["只有多练习，就能说好。","只有多练习，才能说好。","只有 pairs with 才, not 就."],"ex":[["只有|多|练习|，|才能|说|好|中文|。","zhǐ yǒu|duō|liàn xí||cái néng|shuō|hǎo|Zhōng wén|","Only with lots of practice can you speak Chinese well."],["只有|周末|，|我|才|有|时间|。","zhǐ yǒu|zhōu mò||wǒ|cái|yǒu|shí jiān|","Only at weekends do I have time."],["只有|你|去|，|他|才|会|去|。","zhǐ yǒu|nǐ|qù||tā|cái|huì|qù|","He'll only go if you go."]],"gap":[{"en":"Only with lots of practice can you speak Chinese well.","before":"","after":"多练习，才能说好中文。","a":"只有","wrong":["只要","因为","虽然"],"pins":{"只有":"zhǐ yǒu","只要":"zhǐ yào","因为":"yīn wèi","虽然":"suī rán"},"full":["只有|多|练习|，|才能|说|好|中文|。","zhǐ yǒu|duō|liàn xí||cái néng|shuō|hǎo|Zhōng wén|","Only with lots of practice can you speak Chinese well."]},{"en":"Only at weekends do I have time.","before":"只有周末，我","after":"有时间。","a":"才","wrong":["就","都","很"],"pins":{"才":"cái","就":"jiù","都":"dōu","很":"hěn"},"full":["只有|周末|，|我|才|有|时间|。","zhǐ yǒu|zhōu mò||wǒ|cái|yǒu|shí jiān|","Only at weekends do I have time."]},{"en":"He'll only go if you go.","before":"只有你去，他","after":"会去。","a":"才","wrong":["就","都","很"],"pins":{"才":"cái","就":"jiù","都":"dōu","很":"hěn"},"full":["只有|你|去|，|他|才|会|去|。","zhǐ yǒu|nǐ|qù||tā|cái|huì|qù|","He'll only go if you go."]}],"order":[{"en":"Only with lots of practice can you speak Chinese well.","a":"只有|多|练习|，|才|能|说|好|中文|。","alt":[],"full":["只有|多|练习|，|才|能|说|好|中文|。","zhǐ yǒu|duō|liàn xí||cái|néng|shuō|hǎo|Zhōng wén|","Only with lots of practice can you speak Chinese well."]},{"en":"Only at weekends do I have time.","a":"只有|周末|，|我|才|有|时间|。","alt":[],"full":["只有|周末|，|我|才|有|时间|。","zhǐ yǒu|zhōu mò||wǒ|cái|yǒu|shí jiān|","Only at weekends do I have time."]},{"en":"He'll only go if you go.","a":"只有|你|去|，|他|才|会|去|。","alt":[],"full":["只有|你|去|，|他|才|会|去|。","zhǐ yǒu|nǐ|qù||tā|cái|huì|qù|","He'll only go if you go."]}],"spot":[{"en":"He'll only go if you go.","right":"只有你去，他才会去。","wrong":"只有你去，他就会去。","full":["只有|你|去|，|他|才|会|去|。","zhǐ yǒu|nǐ|qù||tā|cái|huì|qù|","He'll only go if you go."]},{"en":"Only at weekends do I have time.","right":"只有周末，我才有时间。","wrong":"只有周末，才我有时间。","full":["只有|周末|，|我|才|有|时间|。","zhǐ yǒu|zhōu mò||wǒ|cái|yǒu|shí jiān|","Only at weekends do I have time."]}]},{"id":"zhiyao","level":4,"title":"只要…就: as long as","pattern":"只要 + condition，就 + result","why":"只要 names a condition that is enough on its own, and 就 brings the result: \"as long as A, then B\". 才 goes with 只有, not with 只要.","mark":["只要"],"mistake":["只要你努力，才能学好。","只要你努力，就能学好。","只要 pairs with 就; 才 goes with 只有."],"ex":[["只要|你|努力|，|就|能|学好|。","zhǐ yào|nǐ|nǔ lì||jiù|néng|xué hǎo|","As long as you work hard, you'll learn it."],["只要|有|时间|，|我|就|去|看|你|。","zhǐ yào|yǒu|shí jiān||wǒ|jiù|qù|kàn|nǐ|","Whenever I have time, I'll come and see you."],["只要|不|下雨|，|我们|就|去|爬山|。","zhǐ yào|bù|xià yǔ||wǒ men|jiù|qù|pá shān|","As long as it doesn't rain, we'll go climbing."]],"gap":[{"en":"As long as you work hard, you'll learn it.","before":"","after":"你努力，就能学好。","a":"只要","wrong":["只有","虽然","因为"],"pins":{"只要":"zhǐ yào","只有":"zhǐ yǒu","虽然":"suī rán","因为":"yīn wèi"},"full":["只要|你|努力|，|就|能|学好|。","zhǐ yào|nǐ|nǔ lì||jiù|néng|xué hǎo|","As long as you work hard, you'll learn it."]},{"en":"Whenever I have time, I'll come and see you.","before":"只要有时间，我","after":"去看你。","a":"就","wrong":["才","很","太"],"pins":{"就":"jiù","才":"cái","很":"hěn","太":"tài"},"full":["只要|有|时间|，|我|就|去|看|你|。","zhǐ yào|yǒu|shí jiān||wǒ|jiù|qù|kàn|nǐ|","Whenever I have time, I'll come and see you."]},{"en":"As long as it doesn't rain, we'll go climbing.","before":"只要不下雨，我们","after":"去爬山。","a":"就","wrong":["才","很","太"],"pins":{"就":"jiù","才":"cái","很":"hěn","太":"tài"},"full":["只要|不|下雨|，|我们|就|去|爬山|。","zhǐ yào|bù|xià yǔ||wǒ men|jiù|qù|pá shān|","As long as it doesn't rain, we'll go climbing."]}],"order":[{"en":"As long as you work hard, you'll learn it.","a":"只要|你|努力|，|就|能|学|好|。","alt":[],"full":["只要|你|努力|，|就|能|学|好|。","zhǐ yào|nǐ|nǔ lì||jiù|néng|xué|hǎo|","As long as you work hard, you'll learn it."]},{"en":"Whenever I have time, I'll come and see you.","a":"只要|有|时间|，|我|就|去|看|你|。","alt":[],"full":["只要|有|时间|，|我|就|去|看|你|。","zhǐ yào|yǒu|shí jiān||wǒ|jiù|qù|kàn|nǐ|","Whenever I have time, I'll come and see you."]},{"en":"As long as it doesn't rain, we'll go climbing.","a":"只要|不|下雨|，|我们|就|去|爬山|。","alt":[],"full":["只要|不|下雨|，|我们|就|去|爬山|。","zhǐ yào|bù|xià yǔ||wǒ men|jiù|qù|pá shān|","As long as it doesn't rain, we'll go climbing."]}],"spot":[{"en":"As long as it doesn't rain, we'll go climbing.","right":"只要不下雨，我们就去爬山。","wrong":"只要不下雨，就我们去爬山。","full":["只要|不|下雨|，|我们|就|去|爬山|。","zhǐ yào|bù|xià yǔ||wǒ men|jiù|qù|pá shān|","As long as it doesn't rain, we'll go climbing."]},{"en":"As long as you work hard, you'll learn it.","right":"只要你努力，就能学好。","wrong":"只要你努力，才能学好。","full":["只要|你|努力|，|就|能|学好|。","zhǐ yào|nǐ|nǔ lì||jiù|néng|xué hǎo|","As long as you work hard, you'll learn it."]}]},{"id":"bushi-ershi","level":4,"title":"不是…而是: not A, but B","pattern":"不是 + A，而是 + B","why":"不是 sets one idea aside and 而是 puts the right one in its place. To correct something use 而是, not 但是.","mark":["不是","而是"],"mistake":["他不是老师，但是学生。","他不是老师，而是学生。","To correct, use 而是, not 但是."],"ex":[["他|不|是|老师|，|而是|学生|。","tā|bù|shì|lǎo shī||ér shì|xué sheng|","He isn't a teacher but a student."],["我|不|是|不|想|去|，|而是|没有|时间|。","wǒ|bù|shì|bù|xiǎng|qù||ér shì|méi yǒu|shí jiān|","It's not that I don't want to go; I just don't have time."],["问题|不|是|钱|，|而是|时间|。","wèn tí|bù|shì|qián||ér shì|shí jiān|","The problem isn't money but time."]],"gap":[{"en":"He isn't a teacher but a student.","before":"他不是老师，","after":"学生。","a":"而是","wrong":["但是","所以","因为"],"pins":{"而是":"ér shì","但是":"dàn shì","所以":"suǒ yǐ","因为":"yīn wèi"},"full":["他|不|是|老师|，|而是|学生|。","tā|bù|shì|lǎo shī||ér shì|xué sheng|","He isn't a teacher but a student."]},{"en":"It's not that I don't want to go; I just don't have time.","before":"我","after":"不想去，而是没有时间。","a":"不是","wrong":["没有","不要","不会"],"pins":{"不是":"bù shì","没有":"méi yǒu","不要":"bù yào","不会":"bù huì"},"full":["我|不|是|不|想|去|，|而是|没有|时间|。","wǒ|bù|shì|bù|xiǎng|qù||ér shì|méi yǒu|shí jiān|","It's not that I don't want to go; I just don't have time."]},{"en":"The problem isn't money but time.","before":"问题不是钱，","after":"时间。","a":"而是","wrong":["但是","所以","还是"],"pins":{"而是":"ér shì","但是":"dàn shì","所以":"suǒ yǐ","还是":"hái shi"},"full":["问题|不|是|钱|，|而是|时间|。","wèn tí|bù|shì|qián||ér shì|shí jiān|","The problem isn't money but time."]}],"order":[{"en":"He isn't a teacher but a student.","a":"他|不是|老师|，|而是|学生|。","alt":[],"full":["他|不是|老师|，|而是|学生|。","tā|bù shì|lǎo shī||ér shì|xué sheng|","He isn't a teacher but a student."]},{"en":"The problem isn't money but time.","a":"问题|不是|钱|，|而是|时间|。","alt":[],"full":["问题|不是|钱|，|而是|时间|。","wèn tí|bù shì|qián||ér shì|shí jiān|","The problem isn't money but time."]},{"en":"It's not that I don't want to go; I just don't have time.","a":"我|不是|不|想|去|，|而是|没有|时间|。","alt":[],"full":["我|不是|不|想|去|，|而是|没有|时间|。","wǒ|bù shì|bù|xiǎng|qù||ér shì|méi yǒu|shí jiān|","It's not that I don't want to go; I just don't have time."]}],"spot":[{"en":"He isn't a teacher but a student.","right":"他不是老师，而是学生。","wrong":"他不是老师，但是学生。","full":["他|不|是|老师|，|而是|学生|。","tā|bù|shì|lǎo shī||ér shì|xué sheng|","He isn't a teacher but a student."]},{"en":"The problem isn't money but time.","right":"问题不是钱，而是时间。","wrong":"问题而是钱，不是时间。","full":["问题|不|是|钱|，|而是|时间|。","wèn tí|bù|shì|qián||ér shì|shí jiān|","The problem isn't money but time."]}]},{"id":"jingran","level":4,"title":"竟然: to my surprise","pattern":"Subject + 竟然 + verb","why":"竟然 goes before the verb, after the subject, and says the speaker didn't expect it: \"actually, of all things\". It is about surprise, not time.","mark":["竟然"],"mistake":["他忘了竟然我的名字。","他竟然忘了我的名字。","竟然 goes before the verb, not after it."],"ex":[["他|竟然|忘|了|我|的|名字|。","tā|jìng rán|wàng|le|wǒ|de|míng zi|","He actually forgot my name."],["这么|难|的|题|，|她|竟然|做|对|了|。","zhè me|nán|de|tí||tā|jìng rán|zuò|duì|le|","She actually got such a hard question right."],["我|竟然|在|这里|见到|你|！","wǒ|jìng rán|zài|zhè li|jiàn dào|nǐ|","Fancy seeing you here!"]],"gap":[{"en":"He actually forgot my name.","before":"他","after":"忘了我的名字。","a":"竟然","wrong":["一起","一点","因为"],"pins":{"竟然":"jìng rán","一起":"yī qǐ","一点":"yī diǎn","因为":"yīn wèi"},"full":["他|竟然|忘|了|我|的|名字|。","tā|jìng rán|wàng|le|wǒ|de|míng zi|","He actually forgot my name."]},{"en":"She actually got such a hard question right.","before":"这么难的题，她","after":"做对了。","a":"竟然","wrong":["一起","因为","所以"],"pins":{"竟然":"jìng rán","一起":"yī qǐ","因为":"yīn wèi","所以":"suǒ yǐ"},"full":["这么|难|的|题|，|她|竟然|做|对|了|。","zhè me|nán|de|tí||tā|jìng rán|zuò|duì|le|","She actually got such a hard question right."]},{"en":"Fancy seeing you here!","before":"我","after":"在这里见到你！","a":"竟然","wrong":["一起","所以","因为"],"pins":{"竟然":"jìng rán","一起":"yī qǐ","所以":"suǒ yǐ","因为":"yīn wèi"},"full":["我|竟然|在|这里|见到|你|！","wǒ|jìng rán|zài|zhè li|jiàn dào|nǐ|","Fancy seeing you here!"]}],"order":[{"en":"He actually forgot my name.","a":"他|竟然|忘|了|我|的|名字|。","alt":[],"full":["他|竟然|忘|了|我|的|名字|。","tā|jìng rán|wàng|le|wǒ|de|míng zi|","He actually forgot my name."]},{"en":"She actually got such a hard question right.","a":"这么|难|的|题|，|她|竟然|做|对|了|。","alt":[],"full":["这么|难|的|题|，|她|竟然|做|对|了|。","zhè me|nán|de|tí||tā|jìng rán|zuò|duì|le|","She actually got such a hard question right."]},{"en":"Fancy seeing you here!","a":"我|竟然|在|这里|见到|你|！","alt":[],"full":["我|竟然|在|这里|见到|你|！","wǒ|jìng rán|zài|zhè li|jiàn dào|nǐ|","Fancy seeing you here!"]}],"spot":[{"en":"He actually forgot my name.","right":"他竟然忘了我的名字。","wrong":"他忘了竟然我的名字。","full":["他|竟然|忘|了|我|的|名字|。","tā|jìng rán|wàng|le|wǒ|de|míng zi|","He actually forgot my name."]},{"en":"Fancy seeing you here!","right":"我竟然在这里见到你！","wrong":"我在这里见到你竟然！","full":["我|竟然|在|这里|见到|你|！","wǒ|jìng rán|zài|zhè li|jiàn dào|nǐ|","Fancy seeing you here!"]}]},{"id":"nandao","level":4,"title":"难道…吗: surely not?","pattern":"难道 + question + 吗？","why":"难道 turns a question into a challenge: the speaker thinks the answer is obvious. It ends in 吗, and a 不 inside means \"surely you do\".","mark":["难道"],"mistake":["难道你不知道。","难道你不知道吗？","A 难道 question ends in 吗 and a question mark."],"ex":[["难道|你|不|知道|吗|？","nán dào|nǐ|bù|zhī dào|ma|","Don't tell me you didn't know?"],["难道|他|已经|走|了|吗|？","nán dào|tā|yǐ jīng|zǒu|le|ma|","Surely he hasn't gone already?"],["这么|简单|的|事|，|难道|你|不|会|做|吗|？","zhè me|jiǎn dān|de|shì||nán dào|nǐ|bù|huì|zuò|ma|","Something this simple: surely you can do it?"]],"gap":[{"en":"Don't tell me you didn't know?","before":"","after":"你不知道吗？","a":"难道","wrong":["因为","虽然","所以"],"pins":{"难道":"nán dào","因为":"yīn wèi","虽然":"suī rán","所以":"suǒ yǐ"},"full":["难道|你|不|知道|吗|？","nán dào|nǐ|bù|zhī dào|ma|","Don't tell me you didn't know?"]},{"en":"Surely he hasn't gone already?","before":"难道他已经走了","after":"？","a":"吗","wrong":["的","着","过"],"pins":{"吗":"ma","的":"de","着":"zhe","过":"guo"},"full":["难道|他|已经|走|了|吗|？","nán dào|tā|yǐ jīng|zǒu|le|ma|","Surely he hasn't gone already?"]},{"en":"Surely you can do it?","before":"难道你不会做","after":"？","a":"吗","wrong":["的","着","过"],"pins":{"吗":"ma","的":"de","着":"zhe","过":"guo"},"full":["难道|你|不|会|做|吗|？","nán dào|nǐ|bù|huì|zuò|ma|","Surely you can do it?"]}],"order":[{"en":"Don't tell me you didn't know?","a":"难道|你|不|知道|吗|？","alt":["你|难道|不|知道|吗|？"],"full":["难道|你|不|知道|吗|？","nán dào|nǐ|bù|zhī dào|ma|","Don't tell me you didn't know?"]},{"en":"Surely he hasn't gone already?","a":"难道|他|已经|走|了|吗|？","alt":["他|难道|已经|走|了|吗|？"],"full":["难道|他|已经|走|了|吗|？","nán dào|tā|yǐ jīng|zǒu|le|ma|","Surely he hasn't gone already?"]},{"en":"Surely you can do it?","a":"难道|你|不|会|做|吗|？","alt":["你|难道|不|会|做|吗|？"],"full":["难道|你|不|会|做|吗|？","nán dào|nǐ|bù|huì|zuò|ma|","Surely you can do it?"]}],"spot":[{"en":"Don't tell me you didn't know?","right":"难道你不知道吗？","wrong":"难道你不知道。","full":["难道|你|不|知道|吗|？","nán dào|nǐ|bù|zhī dào|ma|","Don't tell me you didn't know?"]},{"en":"Surely he hasn't gone already?","right":"难道他已经走了吗？","wrong":"难道他走已经了吗？","full":["难道|他|已经|走|了|吗|？","nán dào|tā|yǐ jīng|zǒu|le|ma|","Surely he hasn't gone already?"]}]},{"id":"duilaishuo","level":4,"title":"对…来说: for someone","pattern":"对 + person + 来说，opinion","why":"对 + person + 来说 frames a view: \"for them, as far as they are concerned\". The phrase comes first, before the opinion, and the order 对 … 来说 is fixed.","mark":["来说"],"mistake":["对我说来，中文很难。","对我来说，中文很难。","The fixed order is 对 … 来说."],"ex":[["对|我|来|说|，|中文|很|难|。","duì|wǒ|lái|shuō||Zhōng wén|hěn|nán|","For me, Chinese is hard."],["对|孩子|来|说|，|玩|很|重要|。","duì|hái zi|lái|shuō||wán|hěn|zhòng yào|","For children, play is important."],["对|他|来|说|，|这|不|是|问题|。","duì|tā|lái|shuō||zhè|bù|shì|wèn tí|","For him, this isn't a problem."]],"gap":[{"en":"For me, Chinese is hard.","before":"","after":"我来说，中文很难。","a":"对","wrong":["给","在","把"],"pins":{"对":"duì","给":"gěi","在":"zài","把":"bǎ"},"full":["对|我|来|说|，|中文|很|难|。","duì|wǒ|lái|shuō||Zhōng wén|hěn|nán|","For me, Chinese is hard."]},{"en":"For children, play is important.","before":"对孩子","after":"，玩很重要。","a":"来说","wrong":["说来","以前","以后"],"pins":{"来说":"lái shuō","说来":"shuō lái","以前":"yǐ qián","以后":"yǐ hòu"},"full":["对|孩子|来|说|，|玩|很|重要|。","duì|hái zi|lái|shuō||wán|hěn|zhòng yào|","For children, play is important."]},{"en":"For him, this isn't a problem.","before":"对他","after":"，这不是问题。","a":"来说","wrong":["说来","以前","以后"],"pins":{"来说":"lái shuō","说来":"shuō lái","以前":"yǐ qián","以后":"yǐ hòu"},"full":["对|他|来|说|，|这|不|是|问题|。","duì|tā|lái|shuō||zhè|bù|shì|wèn tí|","For him, this isn't a problem."]}],"order":[{"en":"For me, Chinese is hard.","a":"对|我|来说|，|中文|很|难|。","alt":[],"full":["对|我|来说|，|中文|很|难|。","duì|wǒ|lái shuō||Zhōng wén|hěn|nán|","For me, Chinese is hard."]},{"en":"For children, play is important.","a":"对|孩子|来说|，|玩|很|重要|。","alt":[],"full":["对|孩子|来说|，|玩|很|重要|。","duì|hái zi|lái shuō||wán|hěn|zhòng yào|","For children, play is important."]},{"en":"For him, this isn't a problem.","a":"对|他|来说|，|这|不是|问题|。","alt":[],"full":["对|他|来说|，|这|不是|问题|。","duì|tā|lái shuō||zhè|bù shì|wèn tí|","For him, this isn't a problem."]}],"spot":[{"en":"For me, Chinese is hard.","right":"对我来说，中文很难。","wrong":"对我说来，中文很难。","full":["对|我|来|说|，|中文|很|难|。","duì|wǒ|lái|shuō||Zhōng wén|hěn|nán|","For me, Chinese is hard."]},{"en":"For him, this isn't a problem.","right":"对他来说，这不是问题。","wrong":"对他来说，这是不问题。","full":["对|他|来|说|，|这|不|是|问题|。","duì|tā|lái|shuō||zhè|bù|shì|wèn tí|","For him, this isn't a problem."]}]},{"id":"jinguan","level":4,"title":"尽管…还是: although, still","pattern":"尽管 + fact，subject + 还是/也 + verb","why":"尽管 admits a fact, and 还是 or 也 in the second half says it changes nothing. It is close to 虽然…但是, a little more formal; 还是 goes after the subject, before the verb.","mark":["尽管"],"mistake":["尽管很累，还是他继续工作。","尽管很累，他还是继续工作。","还是 goes after the subject, before the verb."],"ex":[["尽管|很|累|，|他|还是|继续|工作|。","jǐn guǎn|hěn|lèi||tā|hái shi|jì xù|gōng zuò|","Tired as he was, he kept on working."],["尽管|下|着|雨|，|比赛|还是|开始|了|。","jǐn guǎn|xià|zhe|yǔ||bǐ sài|hái shi|kāi shǐ|le|","Although it was raining, the match still began."],["尽管|我|说|了|很|多次|，|他|也|不|听|。","jǐn guǎn|wǒ|shuō|le|hěn|duō cì||tā|yě|bù|tīng|","Though I've told him many times, he doesn't listen."]],"gap":[{"en":"Tired as he was, he kept on working.","before":"","after":"很累，他还是继续工作。","a":"尽管","wrong":["因为","所以","只要"],"pins":{"尽管":"jǐn guǎn","因为":"yīn wèi","所以":"suǒ yǐ","只要":"zhǐ yào"},"full":["尽管|很|累|，|他|还是|继续|工作|。","jǐn guǎn|hěn|lèi||tā|hái shi|jì xù|gōng zuò|","Tired as he was, he kept on working."]},{"en":"Although it was raining, the match still began.","before":"尽管下着雨，比赛","after":"开始了。","a":"还是","wrong":["所以","因为","而且"],"pins":{"还是":"hái shi","所以":"suǒ yǐ","因为":"yīn wèi","而且":"ér qiě"},"full":["尽管|下|着|雨|，|比赛|还是|开始|了|。","jǐn guǎn|xià|zhe|yǔ||bǐ sài|hái shi|kāi shǐ|le|","Although it was raining, the match still began."]},{"en":"Though I've told him many times, he doesn't listen.","before":"尽管我说了很多次，他","after":"不听。","a":"也","wrong":["就","才","很"],"pins":{"也":"yě","就":"jiù","才":"cái","很":"hěn"},"full":["尽管|我|说|了|很|多次|，|他|也|不|听|。","jǐn guǎn|wǒ|shuō|le|hěn|duō cì||tā|yě|bù|tīng|","Though I've told him many times, he doesn't listen."]}],"order":[{"en":"Tired as he was, he kept on working.","a":"尽管|很|累|，|他|还是|继续|工作|。","alt":["他|尽管|很|累|，|还是|继续|工作|。"],"full":["尽管|很|累|，|他|还是|继续|工作|。","jǐn guǎn|hěn|lèi||tā|hái shi|jì xù|gōng zuò|","Tired as he was, he kept on working."]},{"en":"Although it was raining, the match still began.","a":"尽管|下|着|雨|，|比赛|还是|开始|了|。","alt":[],"full":["尽管|下|着|雨|，|比赛|还是|开始|了|。","jǐn guǎn|xià|zhe|yǔ||bǐ sài|hái shi|kāi shǐ|le|","Although it was raining, the match still began."]},{"en":"Though I've told him many times, he doesn't listen.","a":"尽管|我|说|了|很|多|次|，|他|也|不|听|。","alt":[],"full":["尽管|我|说|了|很|多|次|，|他|也|不|听|。","jǐn guǎn|wǒ|shuō|le|hěn|duō|cì||tā|yě|bù|tīng|","Though I've told him many times, he doesn't listen."]}],"spot":[{"en":"Tired as he was, he kept on working.","right":"尽管很累，他还是继续工作。","wrong":"尽管很累，还是他继续工作。","full":["尽管|很|累|，|他|还是|继续|工作|。","jǐn guǎn|hěn|lèi||tā|hái shi|jì xù|gōng zuò|","Tired as he was, he kept on working."]},{"en":"Although it was raining, the match still began.","right":"尽管下着雨，比赛还是开始了。","wrong":"尽管下着雨，比赛开始还是了。","full":["尽管|下|着|雨|，|比赛|还是|开始|了|。","jǐn guǎn|xià|zhe|yǔ||bǐ sài|hái shi|kāi shǐ|le|","Although it was raining, the match still began."]}]},{"id":"yuqi","level":5,"title":"与其…不如: rather than A, better B","pattern":"与其 + A，不如 + B","why":"与其 names the choice to turn down and 不如 the better one, often as advice: \"rather than A, you might as well B\". 与其 always pairs with 不如.","mark":["与其","不如"],"mistake":["与其等车，还是走路。","与其等车，不如走路。","与其 pairs with 不如."],"ex":[["与其|等|车|，|不如|走路|。","yǔ qí|děng|chē||bù rú|zǒu lù|","Rather than wait for the bus, we might as well walk."],["与其|在|家|睡觉|，|不如|出去|走走|。","yǔ qí|zài|jiā|shuì jiào||bù rú|chū qu|zǒu zou|","Better to go out for a walk than sleep at home."],["与其|后悔|，|不如|现在|就|开始|。","yǔ qí|hòu huǐ||bù rú|xiàn zài|jiù|kāi shǐ|","Rather than regret it, start now."]],"gap":[{"en":"Rather than wait for the bus, we might as well walk.","before":"","after":"等车，不如走路。","a":"与其","wrong":["因为","如果","虽然"],"pins":{"与其":"yǔ qí","因为":"yīn wèi","如果":"rú guǒ","虽然":"suī rán"},"full":["与其|等|车|，|不如|走路|。","yǔ qí|děng|chē||bù rú|zǒu lù|","Rather than wait for the bus, we might as well walk."]},{"en":"Rather than wait for the bus, we might as well walk.","before":"与其等车，","after":"走路。","a":"不如","wrong":["还是","所以","而且"],"pins":{"不如":"bù rú","还是":"hái shi","所以":"suǒ yǐ","而且":"ér qiě"},"full":["与其|等|车|，|不如|走路|。","yǔ qí|děng|chē||bù rú|zǒu lù|","Rather than wait for the bus, we might as well walk."]},{"en":"Better to go out for a walk than sleep at home.","before":"与其在家睡觉，","after":"出去走走。","a":"不如","wrong":["还是","所以","而且"],"pins":{"不如":"bù rú","还是":"hái shi","所以":"suǒ yǐ","而且":"ér qiě"},"full":["与其|在|家|睡觉|，|不如|出去|走走|。","yǔ qí|zài|jiā|shuì jiào||bù rú|chū qu|zǒu zou|","Better to go out for a walk than sleep at home."]}],"order":[{"en":"Rather than wait for the bus, we might as well walk.","a":"与其|等|车|，|不如|走路|。","alt":[],"full":["与其|等|车|，|不如|走路|。","yǔ qí|děng|chē||bù rú|zǒu lù|","Rather than wait for the bus, we might as well walk."]},{"en":"Better to go out for a walk than sleep at home.","a":"与其|在|家|睡觉|，|不如|出去|走走|。","alt":[],"full":["与其|在|家|睡觉|，|不如|出去|走走|。","yǔ qí|zài|jiā|shuì jiào||bù rú|chū qu|zǒu zou|","Better to go out for a walk than sleep at home."]},{"en":"Rather than regret it, start now.","a":"与其|后悔|，|不如|现在|就|开始|。","alt":[],"full":["与其|后悔|，|不如|现在|就|开始|。","yǔ qí|hòu huǐ||bù rú|xiàn zài|jiù|kāi shǐ|","Rather than regret it, start now."]}],"spot":[{"en":"Rather than wait for the bus, we might as well walk.","right":"与其等车，不如走路。","wrong":"与其等车，还是走路。","full":["与其|等|车|，|不如|走路|。","yǔ qí|děng|chē||bù rú|zǒu lù|","Rather than wait for the bus, we might as well walk."]},{"en":"Rather than regret it, start now.","right":"与其后悔，不如现在就开始。","wrong":"不如后悔，与其现在就开始。","full":["与其|后悔|，|不如|现在|就|开始|。","yǔ qí|hòu huǐ||bù rú|xiàn zài|jiù|kāi shǐ|","Rather than regret it, start now."]}]},{"id":"ningke","level":5,"title":"宁可…也不: would rather … than","pattern":"宁可 + the hard choice，也不 + what you refuse","why":"宁可 names the hard choice the speaker accepts, and 也不 the thing they refuse; 也要 instead says what they insist on. It shows determination.","mark":["宁可"],"mistake":["我宁可走路，不坐他的车。","我宁可走路，也不坐他的车。","The second half needs 也 before 不."],"ex":[["我|宁可|走路|，|也|不|坐|他|的|车|。","wǒ|nìng kě|zǒu lù||yě|bù|zuò|tā|de|chē|","I'd rather walk than ride in his car."],["她|宁可|饿|着|，|也|不|吃|快餐|。","tā|nìng kě|è|zhe||yě|bù|chī|kuài cān|","She'd rather go hungry than eat fast food."],["他|宁可|少|睡|一点|，|也|要|把|工作|做|完|。","tā|nìng kě|shǎo|shuì|yī diǎn||yě|yào|bǎ|gōng zuò|zuò|wán|","He'd rather sleep less than leave the work unfinished."]],"gap":[{"en":"I'd rather walk than ride in his car.","before":"我","after":"走路，也不坐他的车。","a":"宁可","wrong":["因为","虽然","如果"],"pins":{"宁可":"nìng kě","因为":"yīn wèi","虽然":"suī rán","如果":"rú guǒ"},"full":["我|宁可|走路|，|也|不|坐|他|的|车|。","wǒ|nìng kě|zǒu lù||yě|bù|zuò|tā|de|chē|","I'd rather walk than ride in his car."]},{"en":"I'd rather walk than ride in his car.","before":"我宁可走路，","after":"不坐他的车。","a":"也","wrong":["就","才","很"],"pins":{"也":"yě","就":"jiù","才":"cái","很":"hěn"},"full":["我|宁可|走路|，|也|不|坐|他|的|车|。","wǒ|nìng kě|zǒu lù||yě|bù|zuò|tā|de|chē|","I'd rather walk than ride in his car."]},{"en":"She'd rather go hungry than eat fast food.","before":"她宁可饿着，也","after":"吃快餐。","a":"不","wrong":["很","都","太"],"pins":{"不":"bù","很":"hěn","都":"dōu","太":"tài"},"full":["她|宁可|饿|着|，|也|不|吃|快餐|。","tā|nìng kě|è|zhe||yě|bù|chī|kuài cān|","She'd rather go hungry than eat fast food."]}],"order":[{"en":"I'd rather walk than ride in his car.","a":"我|宁可|走路|，|也|不|坐|他|的|车|。","alt":[],"full":["我|宁可|走路|，|也|不|坐|他|的|车|。","wǒ|nìng kě|zǒu lù||yě|bù|zuò|tā|de|chē|","I'd rather walk than ride in his car."]},{"en":"She'd rather go hungry than eat fast food.","a":"她|宁可|饿|着|，|也|不|吃|快餐|。","alt":[],"full":["她|宁可|饿|着|，|也|不|吃|快餐|。","tā|nìng kě|è|zhe||yě|bù|chī|kuài cān|","She'd rather go hungry than eat fast food."]},{"en":"He'd rather sleep less than leave the work unfinished.","a":"他|宁可|少|睡|一点|，|也|要|把|工作|做完|。","alt":[],"full":["他|宁可|少|睡|一点|，|也|要|把|工作|做完|。","tā|nìng kě|shǎo|shuì|yī diǎn||yě|yào|bǎ|gōng zuò|zuò wán|","He'd rather sleep less than leave the work unfinished."]}],"spot":[{"en":"She'd rather go hungry than eat fast food.","right":"她宁可饿着，也不吃快餐。","wrong":"她宁可饿着，不也吃快餐。","full":["她|宁可|饿|着|，|也|不|吃|快餐|。","tā|nìng kě|è|zhe||yě|bù|chī|kuài cān|","She'd rather go hungry than eat fast food."]},{"en":"I'd rather walk than ride in his car.","right":"我宁可走路，也不坐他的车。","wrong":"我宁可走路，也坐不他的车。","full":["我|宁可|走路|，|也|不|坐|他|的|车|。","wǒ|nìng kě|zǒu lù||yě|bù|zuò|tā|de|chē|","I'd rather walk than ride in his car."]}]},{"id":"zhisuoyi","level":5,"title":"之所以…是因为: the reason is","pattern":"result + 之所以 …，是因为 + reason","why":"A written pattern that gives the result first and the reason after, putting the weight on the reason. The second half needs 是 before 因为.","mark":["之所以"],"mistake":["我之所以来中国，因为喜欢中文。","我之所以来中国，是因为喜欢中文。","The second half needs 是 before 因为."],"ex":[["我|之所以|来|中国|，|是|因为|喜欢|中文|。","wǒ|zhī suǒ yǐ|lái|Zhōng guó||shì|yīn wèi|xǐ huan|Zhōng wén|","The reason I came to China is that I like Chinese."],["他|之所以|迟到|，|是|因为|路上|堵车|。","tā|zhī suǒ yǐ|chí dào||shì|yīn wèi|lù shang|dǔ chē|","He was late because of the traffic."],["这|本|书|之所以|受|欢迎|，|是|因为|故事|很|有意思|。","zhè|běn|shū|zhī suǒ yǐ|shòu|huān yíng||shì|yīn wèi|gù shi|hěn|yǒu yì si|","This book is popular because the story is interesting."]],"gap":[{"en":"The reason I came to China is that I like Chinese.","before":"我","after":"来中国，是因为喜欢中文。","a":"之所以","wrong":["因为","虽然","如果"],"pins":{"之所以":"zhī suǒ yǐ","因为":"yīn wèi","虽然":"suī rán","如果":"rú guǒ"},"full":["我|之所以|来|中国|，|是|因为|喜欢|中文|。","wǒ|zhī suǒ yǐ|lái|Zhōng guó||shì|yīn wèi|xǐ huan|Zhōng wén|","The reason I came to China is that I like Chinese."]},{"en":"He was late because of the traffic.","before":"他之所以迟到，","after":"路上堵车。","a":"是因为","wrong":["所以","但是","而且"],"pins":{"是因为":"shì yīn wèi","所以":"suǒ yǐ","但是":"dàn shì","而且":"ér qiě"},"full":["他|之所以|迟到|，|是|因为|路上|堵车|。","tā|zhī suǒ yǐ|chí dào||shì|yīn wèi|lù shang|dǔ chē|","He was late because of the traffic."]},{"en":"This book is popular because the story is interesting.","before":"这本书之所以受欢迎，","after":"故事很有意思。","a":"是因为","wrong":["所以","但是","而且"],"pins":{"是因为":"shì yīn wèi","所以":"suǒ yǐ","但是":"dàn shì","而且":"ér qiě"},"full":["这|本|书|之所以|受|欢迎|，|是|因为|故事|很|有意思|。","zhè|běn|shū|zhī suǒ yǐ|shòu|huān yíng||shì|yīn wèi|gù shi|hěn|yǒu yì si|","This book is popular because the story is interesting."]}],"order":[{"en":"The reason I came to China is that I like Chinese.","a":"我|之所以|来|中国|，|是|因为|喜欢|中文|。","alt":[],"full":["我|之所以|来|中国|，|是|因为|喜欢|中文|。","wǒ|zhī suǒ yǐ|lái|Zhōng guó||shì|yīn wèi|xǐ huan|Zhōng wén|","The reason I came to China is that I like Chinese."]},{"en":"He was late because of the traffic.","a":"他|之所以|迟到|，|是|因为|路上|堵车|。","alt":[],"full":["他|之所以|迟到|，|是|因为|路上|堵车|。","tā|zhī suǒ yǐ|chí dào||shì|yīn wèi|lù shang|dǔ chē|","He was late because of the traffic."]},{"en":"This book is popular because the story is interesting.","a":"这|本|书|之所以|受|欢迎|，|是|因为|故事|很|有意思|。","alt":[],"full":["这|本|书|之所以|受|欢迎|，|是|因为|故事|很|有意思|。","zhè|běn|shū|zhī suǒ yǐ|shòu|huān yíng||shì|yīn wèi|gù shi|hěn|yǒu yì si|","This book is popular because the story is interesting."]}],"spot":[{"en":"He was late because of the traffic.","right":"他之所以迟到，是因为路上堵车。","wrong":"他之所以迟到，因为路上堵车。","full":["他|之所以|迟到|，|是|因为|路上|堵车|。","tā|zhī suǒ yǐ|chí dào||shì|yīn wèi|lù shang|dǔ chē|","He was late because of the traffic."]},{"en":"The reason I came to China is that I like Chinese.","right":"我之所以来中国，是因为喜欢中文。","wrong":"我是因为来中国，之所以喜欢中文。","full":["我|之所以|来|中国|，|是|因为|喜欢|中文|。","wǒ|zhī suǒ yǐ|lái|Zhōng guó||shì|yīn wèi|xǐ huan|Zhōng wén|","The reason I came to China is that I like Chinese."]}]},{"id":"weibi","level":5,"title":"未必: not necessarily","pattern":"Subject + 未必 + verb / describing word","why":"未必 goes straight before the verb or describing word and softens a \"no\" into \"not necessarily\". It is more careful than 不.","mark":["未必"],"mistake":["贵的东西是未必好的。","贵的东西未必好。","未必 goes straight before what it doubts."],"ex":[["贵|的|东西|未必|好|。","guì|de|dōng xi|wèi bì|hǎo|","Expensive things aren't necessarily good."],["他|说|的|未必|是|真的|。","tā|shuō|de|wèi bì|shì|zhēn de|","What he says isn't necessarily true."],["你|未必|知道|这|件|事|。","nǐ|wèi bì|zhī dào|zhè|jiàn|shì|","You may not know about this."]],"gap":[{"en":"Expensive things aren't necessarily good.","before":"贵的东西","after":"好。","a":"未必","wrong":["一起","正在","已经"],"pins":{"未必":"wèi bì","一起":"yī qǐ","正在":"zhèng zài","已经":"yǐ jīng"},"full":["贵|的|东西|未必|好|。","guì|de|dōng xi|wèi bì|hǎo|","Expensive things aren't necessarily good."]},{"en":"What he says isn't necessarily true.","before":"他说的","after":"是真的。","a":"未必","wrong":["已经","一起","正在"],"pins":{"未必":"wèi bì","已经":"yǐ jīng","一起":"yī qǐ","正在":"zhèng zài"},"full":["他|说|的|未必|是|真的|。","tā|shuō|de|wèi bì|shì|zhēn de|","What he says isn't necessarily true."]},{"en":"You may not know about this.","before":"你","after":"知道这件事。","a":"未必","wrong":["一起","正在","非常"],"pins":{"未必":"wèi bì","一起":"yī qǐ","正在":"zhèng zài","非常":"fēi cháng"},"full":["你|未必|知道|这|件|事|。","nǐ|wèi bì|zhī dào|zhè|jiàn|shì|","You may not know about this."]}],"order":[{"en":"Expensive things aren't necessarily good.","a":"贵|的|东西|未必|好|。","alt":[],"full":["贵|的|东西|未必|好|。","guì|de|dōng xi|wèi bì|hǎo|","Expensive things aren't necessarily good."]},{"en":"What he says isn't necessarily true.","a":"他|说|的|未必|是|真|的|。","alt":[],"full":["他|说|的|未必|是|真|的|。","tā|shuō|de|wèi bì|shì|zhēn|de|","What he says isn't necessarily true."]},{"en":"You may not know about this.","a":"你|未必|知道|这|件|事|。","alt":["这|件|事|你|未必|知道|。"],"full":["你|未必|知道|这|件|事|。","nǐ|wèi bì|zhī dào|zhè|jiàn|shì|","You may not know about this."]}],"spot":[{"en":"Expensive things aren't necessarily good.","right":"贵的东西未必好。","wrong":"贵的东西好未必。","full":["贵|的|东西|未必|好|。","guì|de|dōng xi|wèi bì|hǎo|","Expensive things aren't necessarily good."]},{"en":"What he says isn't necessarily true.","right":"他说的未必是真的。","wrong":"他说的是未必真的。","full":["他|说|的|未必|是|真的|。","tā|shuō|de|wèi bì|shì|zhēn de|","What he says isn't necessarily true."]}]}];
